/* 令和7年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.r07.committeeSessions.push(...[{"id":"r07-20250825-8","meetingId":"r07-cm08","date":"2025年8月25日","dateIso":"2025-08-25","committee":"建設委員会","time":"午後 １時００分～午後 ４時１９分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を68件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"東京における都市計画道路の整備方針（仮称）中間のまとめ","agenda":"東京における都市計画道路の整備方針（仮称）中間のまとめ","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"資料の３のこれまでの検討状況というところなのですが、都と区の検討会議が開催されているとありますけれども、部長級と課長級の検討会議には品川区の担当部課長が参加したのでしょうか。伺いたいと思います。計５回ですけれども、参加したときに、品川区としての意見は何回述べたのか、また、述べたとしたら、どのような意見を述べたのか伺いたいのが１つです。","respondent":"高梨都市計画課長","answer":"具体的な時期については未定ですけれども、今現在、最終的な整備方針の策定と公表を年度末までにといったことで進めてありますので、今後、秋から冬にかけて整備方針の案を取りまとめて、しかるべき時期にパブリックコメントが実施されるものと、区としては認識しています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問","question":"分かりました。概要版の見開きの右下に、都市計画道路の必要性の検証項目ですとか、あるいは優先整備路線の選定項目が並んでおります。伺いたいのは、区が検証するこの都市計画道路は、区内では何本になるのでしょうかということと、また、区は、いつ頃、どのような体制で、どのような進め方で、この地域項目の検証に当たっていくのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"予算も昨年度補正でいただいております。その委託での調査も含めて、区のほうで、そういった検討会議を踏まえつつ、検討を進めているところです。","voiceIndex":7,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問","question":"先ほど、２回目のパブリックコメントという話もありました。その前に案ができるということなので、そこまでに検討を終えるということなのでしょうか。それでいいのか伺いたいのが１つと、あと、優先整備路線のほうの検証、選定もあるのですけれども、この選定には、品川区としてはどういうふうに関わっていくのか。伺いたいと思います。","respondent":"高梨都市計画課長","answer":"最初のご質問ですけれども、まさしく次の整備方針（案）の取りまとめでは、各路線の案が出てまいりますので、それまでに検討を終えていくというスケジュールです。次に、優先整備路線の選定についてです。","voiceIndex":9,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問・要望","question":"特定整備路線もそうなのですけれども、時代に合わなくなったような道路がたくさん増えているのではないでしょうか。今、意見照会というか、調査もあるということでしたので、この場で要望させていただきたいのですが、補助２７号線、あと補助３０号線、補助３１号線などの未着手道路がありますけれども、これらは整備による立ち退きや商店街への影響など、地域住民への影響がかなり大きい道路です。","respondent":"高梨都市計画課長","answer":"当然、この計画に載ることで、どのようなメリットがあるのかというようなところもそうですし、どのような整備がこのリメイクに合致するのかというようなところも含めて、しっかりと、この後、検討を進めて。","voiceIndex":11,"id":"exchange-004"},{"speaker":"中塚委員","kind":"質問・要望","question":"今のやり取りを伺っておりました。先ほどの説明ですと、リメイク候補路線の話の説明もあったので、まだ路線名を挙げての意見は述べていないのかなという感じもしましたけれども、この部長級、課長級の中で路線名を挙げて区の意向を伝えるということがあったのかどうか、まず１つ確認させてください。２つ目ですけれども、今、区の中で検討しているということです。","respondent":"高梨都市計画課長","answer":"区民からの意見集約の後にパブリックコメントを実施するですけれども、一定、東京都の中で各区市からの路線名等の案が取りまとまった段階で、整備方針案として、改めて区民の皆さんも含めてパブリックコメントを実施するといった方向で、現在、進めているところです。","voiceIndex":14,"id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"部長級、課長級の会議の場ではないけれども、都と調整をしている路線はどこかということを伺いたいと思います。都市計画道路ですから、直接の地権者の方もいらっしゃいますので、こういう意見を区として都に上げようと思っているけれども、住民の皆さんのご意見はいかがですかと、その時点でしっかり意見聴取を行うべきだと思います。この点について、改めて伺いたいと思います。","respondent":"高梨都市計画課長","answer":"議論をしていない路線はないです。次に、委託の成果物が上がった段階で、都への回答の前に意見聴取をというご意見でございましたけれども、今、区としましては、まずは、区として、どういった方向性で各路線を考えるべきかというところの検討を鋭意進めているところです。","voiceIndex":16,"id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"個別の路線については全てが対象だということです。区として意見を決定する前に、区として東京都に意向を伝える前に、関係住民にしっかりと意見聴取を行う、そうした仕組みを少なくともとるべきだということは重ねて要望したいと思います。そこで伺いますけれども、これら中間のまとめで示された方向性は、新たな再開発を進めるものだと私は考えますが、区のお考えを伺いたいと思います。","respondent":"高梨都市計画課長","answer":"一方で、今、委員からもご紹介がありましたけれども、見直すべきもの、必要性がないものについては、今回、計画廃止に向けた検討を行っていくといったところをしっかりと示しているといったところで、前進なのかなというふうに区としては考えているところです。","voiceIndex":18,"id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"これまでの経過と、今回示された新たな方針を指してはいない。ですから、先ほど課長が述べた都市計画道路は再開発に直結しているものではないという答弁は、私は、この中間のまとめで示された方針と異なるものだと思いますが、いかがでしょうか。ここまで示されていて、新たな再開発を進めるものだと私は確信し、それは行うべきではないと考えていますが、区の考えを伺いたいと思います。","respondent":"高梨都市計画課長","answer":"都と区で検討を進めているところですけれども、計画的といったところにつきましては、しっかりと時代に合わせて、その都度、タイミングで都市計画の内容を見直して、必要性の検証を行い、必要性がない、低いものについては。","voiceIndex":20,"id":"exchange-008"},{"speaker":"中塚委員","kind":"質問","question":"これをどう評価するかは別です。私は反対ですから、こういうことは進めるべきではないと思っている立場ですけれども、ここに書かれているわけです。少し飛んで、３１ページ目の都市計画区域マスタープラン、略称は「都市マス」と言うのでしょうか。再開発は直接的ではない、つまりは、間接的に再開発を進めるものだと、改めて指摘しますが、区の見解を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"まちづくりと道路の計画が全く含まれていないといったところについては、私の発言の意図するところではございません。再開発のみが、この都市計画道路の整備方針の目的である、目標であるといった部分については、そうではないといったところで発言をさせていただいたところです。","voiceIndex":22,"id":"exchange-009"},{"speaker":"中塚委員","kind":"意見","question":"最後に一言。これで質疑は終了したいと思いますけれども、そこに住んでいる方々、商店街の方々、地域住民の方々、みなさんこれ以上のタワーマンション、オフィスビルは必要ないと、私たちの住まいを奪わないでほしいと多様な声が上がっている中で、さらなる都市計画道路の整備で開発を加速させることは、絶対に行うべきではないと強く申し述べて質疑を終わりたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":24,"id":"exchange-010"},{"speaker":"ゆきた委員","kind":"質問","question":"都市計画道路の整備方針、中間まとめを見させていただきました。先ほど、リメイクの候補地については、検討するところがあるのかないのかも含めて考えていくということでございましたが、こういった都市計画道路の必要性を検証するための区民の声は、第４次計画まで今までされてきたと思いますけれども、どれだけ区民の声を集約できているのか、ここの点についてお聞きできればと思います。","respondent":"高梨都市計画課長","answer":"今ご提案がありましたリメイクを含めた道路のにぎわいづくりであったりとか、そういった部分につきましては、個別の寄せられる声というよりは、町場でいろいろ活動されている団体、まちづくりの中でいろいろと寄せられる声もありますので。","voiceIndex":26,"id":"exchange-011"},{"speaker":"ゆきた委員","kind":"質問","question":"先日、委員会の際に、防災区民憲章についても、デジタルプラットフォームを活用して区民の声を幅広く収集するとありましたけれども、東京都のパブリックコメントを品川区で再度公募する以外にも、品川区内の都市計画道路の必要性を検証するための区民の声を収集する手段を１つでも多く増やしていく必要があると思われます。この辺について、もう一度お聞きできればと思います。","respondent":"高梨都市計画課長","answer":"現在は、東京都とそろえてパブリックコメントで区民の方からご意見をいただくといったところを基軸に考えてありますけれども、ご意見を踏まえて考えてまいりたいと思ってあります。","voiceIndex":28,"id":"exchange-012"},{"speaker":"ゆきた委員","kind":"確認","question":"こちらも拝見させていただきました。品川区内は「しながわＭＡＰ」で確認できるということもあると思うのですけれども、この「しながわＭＡＰ」をまだ知らない方もいらっしゃると思います。ある程度、都市計画道路の検討をする候補地を場所を挙げて発信していくような形が望まれるのではないのかなと思うのですけれども、こちらについてお聞きできればと思います。","respondent":"高梨都市計画課長","answer":"今後、具体的な路線について、整備方針案というような形で載せてまいりますので、そちらについては、第４次のときもそうだったと思うのですけれども、しっかりと地図を用いて、どこの路線のことを言っているのか、都市計画道路の名前は。","voiceIndex":30,"id":"exchange-013"},{"speaker":"ゆきた委員","kind":"意見","question":"もう区民からすると、区道、都道、国道とあって、都市計画道路はどれも当てはまるということ。それも認識が難しいのかなというところもあるので、寄り添った形での発信の仕方も、まさに今後からだと思いますけれども、ぜひ検討していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-014"},{"speaker":"中塚委員","kind":"意見","question":"少なくとも、今、事業認可され、土地の買収が進んでいる補助２９号線や放射２号線、これが完成するのは、いつなのか。完成するめどが立っていない中、一方で、３０年の間で７０％の確率と言われる首都直下大震災が示されて、もう何年もたっているわけで、こうした都市計画道路の整備が防災対策では役に立たないということは繰り返し述べてきたつもりです。私は、そのとおりだという気持ちも分かるのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":34,"id":"exchange-015"}]},{"id":"topic-02","title":"羽田新飛行ルートに関する国土交通大臣への要望","agenda":"羽田新飛行ルートに関する国土交通大臣への要望","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"当日赴いたメンバーはどなただったのか伺います。ホームページなどにも掲載されておりますけれども、文書による要望ではなかったということです。こういった経過になったのは、どなたの意図によるものなのか伺います。問合せがあるといいますか。要望したことについて、区民から反応は区に寄せられているのでしょうか。寄せられているとしたら、内容はどのようなものなのか伺いたいと思います。","respondent":"高梨都市計画課長","answer":"要望に伺ったメンバー、同席したメンバーについて、回答しますけれども、森澤区長のほかは、堀越副区長と、都市環境部長と、都市計画課長の私です。","voiceIndex":39,"id":"exchange-016"},{"speaker":"安藤委員","kind":"質問・要望","question":"そうですか。文書による要望ではなかったということも、なぜなのかなと思いました。「区が求めてきた具体的な方策が示されていない今回の結果は、区として看過できない」と述べたのです。今回また区長が行ったわけですけれども、昨年の「看過できない」というのは、結局何を看過できなかったのかよく分からないので、もう少し半年前のこの要望について、伺いたいのですが、何を看過できなかったのでしょうか。","respondent":"高梨都市計画課長","answer":"令和６年１２月に区が申入れを行った内容についてのご質問です。２年以上の間、固定化回避検討会が開催されず、その間、区としましては、区民負担軽減に資する具体的な方策と、その提示を求めてきたところです。","voiceIndex":41,"id":"exchange-017"},{"speaker":"安藤委員","kind":"質問・要望","question":"結果として、今回は、区長が行ったわけですけれども、前回、副区長が要望した状況とは変わっていないわけです。仮に導入したとしても、新たな経路は市街地上空を通過することからというふうに認めているのですけれども、検討については慎重な対応が必要と結論づけているわけです。もう少し、看過できないと述べたその中身を伺いたいと思います。","respondent":"高梨都市計画課長","answer":"区として看過できないという申入れを行ったことにつきましては、第６回固定化回避検討会で、具体的に区民負担軽減につながる方策が示されなかった、その実行についても示されなかったということに関して、「看過できない」という表現で申入れを行ったところです。","voiceIndex":43,"id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"今回の要請についてですが、区は、今回の要請で、まず次回の、第７回固定化回避検討会の早期開催を求めているのです。そもそもこの固定化回避検討会は、Ａ・Ｃ滑走路に都心を北側から南に飛行機が進入してくるという、こういう現在の新ルートで行っている滑走路の使い方、これを前提にした検討会であるという認識で間違いないのか、区もそういうふうに認識しているのか確認させてください。","respondent":"高梨都市計画課長","answer":"国土交通省によりますと、固定化回避検討会は、現在の滑走路の使い方を前提に固定化を回避する方策について検討している会議体であるというふうに示されているところですので、区もそのように考えています。","voiceIndex":45,"id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"今の固定化回避検討会の検討に期待をしつつ、「海上ルート」という言葉を使っているのですけれども、結局、これも含めて、区は一体何を要請したのか伺いたいのです。固定化回避検討会を早く開くよう求めるということは、それを前提にして要請しているので、結局、今のＡ・Ｃ滑走路に北から降りてくるルートを曲げろ、それを何とか曲げて海上ルートと言っているのか。","respondent":"高梨都市計画課長","answer":"国は、第６回固定化回避検討会の後、今後の取組として、海上ルートの実現に資する方策について、国際動向等を踏まえた調査研究を実施するということで示しています。","voiceIndex":47,"id":"exchange-020"},{"speaker":"安藤委員","kind":"確認","question":"最後、もう１回確認したいのですけれども、区として、具体的にこの滑走路でこういうふうに降りなさいと言っているわけではないというお話がありましたが、区が要請した海上ルートは、現在の新ルートではない時間帯にＢ・Ｄ滑走路に海から降りてくる従来の海上ルートに戻すことも含まれているのか、含まれていないのか、そこら辺をお伺いしたい。","respondent":"高梨都市計画課長","answer":"含まれている、含まれていないの部分も含めて、しっかりと国で品川区民の負担軽減につながる具体的な方策が示されるよう、それが早期に実施されるように品川区は求めているという態度です。","voiceIndex":49,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"あるいは、求めたというよりも、それは国が考えることですみたいな感じに聞こえたのですけれども、いずれにしても、着陸寸前で、最も低空で影響が大きい自治体の区長が要請するというのは大きなことで、私たちとしては、「海上ルート」という言葉を使うのであれば、元の海上ルートに戻せというところを強く要請してほしいですし、それと、現在の都心の上をリスクをはらんで低空飛行してくるこの新ルート。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":51,"id":"exchange-022"},{"speaker":"中塚委員","kind":"質問・要望","question":"今まで、この羽田新ルートをめぐっては、課長とも、前任の課長とも様々質疑をさせていただきました。今回は、いわゆる海上ルートの実現に資する方策というふうに求めたのです。それとも、従来どおり、ルートは固定化回避検討会が検討することであって、区としては、区民負担の軽減を求める立場だということなのか、ご説明いただきたいと思います。","respondent":"高梨都市計画課長","answer":"引き続き、区といたしましては、具体的な使用する滑走路であったりとか、ルートについては、専門知識を有する固定化回避検討会であったり、実施主体である国が責任を持って調査検討を行って、区民負担軽減に資する具体的な方策を提示していただくべく。","voiceIndex":53,"id":"exchange-023"},{"speaker":"中塚委員","kind":"質問・要望","question":"これまでの姿勢と大きく変わったわけではなく、このニュースレターに書かれているように固定化回避検討会が発行するチラシにある「海上ルート」の実現に資する方策ということで、ここに書かれているのだから、区長として国にここを要望したということだということです。ぜひとも従来の、今までの海上ルートに戻せと、国土交通大臣に品川区長として述べていただきたいと思いますが、いかがでしょうか。","respondent":"高梨都市計画課長","answer":"先ほども申し述べたとおり、具体的な方策については、国の責任のもと、しっかりと検討してまいりたいと考えているところですが、委員の発言はじめ、そういった声があるといったところにつきましては、当然、区長のほうにも伝えてまいりたいと考えています。","voiceIndex":55,"id":"exchange-024"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう従来の海上ルートに戻してほしいという声が上がっていることを区長に伝えるということは当然のことですけれども、そのことを述べているのではなくて、検討会が述べるいわゆる海上ルートに資する方策ではなくて、従来の海上ルートの実現を国に求めてほしい、大臣に言ってほしい、そう思っているのですけれども、いかがでしょうか。","respondent":"高梨都市計画課長","answer":"今回の大臣訪問では、そのような意図で発言されたものではないというふうに考えているところです。今後、どのように要望するかにつきましては、区長に意見をしっかりと伝えた上で検討してまいりたいというふうに考えてあります。","voiceIndex":57,"id":"exchange-025"},{"speaker":"中塚委員","kind":"質問・要望","question":"今、課長が、その意図ではないとおっしゃいましたけれども、この一報が出たときに、ついに品川区長が海上ルートを求めたと喜ぶ声も伺いました。ですから、検討会が言う、いわゆる海上ルートを求めても、これは品川区の上を飛ばないルートにはならないということです。ぜひその意見も区長に伝えていただいて、今までの姿勢を変えていただきたいと申し述べて質問を終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":59,"id":"exchange-026"}]},{"id":"topic-03","title":"令和７年９月区民住宅（空き室）入居予定者登録募集","agenda":"令和７年９月区民住宅（空き室）入居予定者登録募集","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"単純に、毎回４０戸程度が空くと思うのですが、空き室が出る理由はどのような理由が多いのかを伺いたいなと思います。空き室が出ないと応募できないということだと思うのですけれども、伺いたいのが１つと、それと、今年度は大体どれぐらいの入居者数、逆に言うと、空きが出るのかを１年で想定しているのか伺いたいと思います。","respondent":"川原住宅課長","answer":"３点ご質問をいただきました。１点目、空き室はどのような理由によるものかといったご質問です。１１世帯を除いて、ほとんどが家族向けの住戸にお住まいのご家族の方ですので、空き室に関しては、引っ越し、転居、別の住戸に転居するといった予定が多いです。","voiceIndex":64,"id":"exchange-027"},{"speaker":"安藤委員","kind":"質問・要望","question":"転居ということですけれども、結構まあまあな間取りではなかったかと思うのです。それとも足りないと考えているのかということをお伺いしたいなというのが２つ目です。ぜひやっていただきたいのですが、そこら辺はいかがでしょうか。","respondent":"川原住宅課長","answer":"現在は、区民住宅の空き室の募集という形で行っておりまして、一定程度数、入居の希望のある方には、倍率でいうと約２倍から３倍の形で、希望する方には住居は確保できているというふうに考えてはおりますけれども、引き続き、区民住宅につきましても、一定程度。","voiceIndex":66,"id":"exchange-028"},{"speaker":"安藤委員","kind":"質問","question":"年に１回の募集ということで、やはり区が、ある程度の基準を備えてしっかりとつくっていく。なおかつ、市場に比べればややというところがあるのであれば、これは結構お役立ち情報といいますか、なかなか制度を知らない人のほうが多いと思うのです。ですから、ぜひそういった層に届くような情報の発信の仕方を、ぜひ工夫していってもらえればというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":68,"id":"exchange-029"}]},{"id":"topic-04","title":"しながわ中央公園ナイター照明ＬＥＤ化その他電気設備工事","agenda":"しながわ中央公園ナイター照明ＬＥＤ化その他電気設備工事","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"工事が４種類あると思うのですが、それぞれ工事契約費用、金額が幾らなのかお伺いしたいと思います。それと、太陽光発電パネルがあるということなのですが、すみません、現状どこに設置されているのか、何キロワットぐらいの電力を得られて、その電力はどこに使用されているのか伺いたいと思います。","respondent":"森道路課長","answer":"こちらにつきましては、明確な規格は手元にございませんけれども、それほど大きなものではございませんので、管理棟の必要な電力の一部をまかなっているというふうに考えています。","voiceIndex":73,"id":"exchange-030"},{"speaker":"安藤委員","kind":"意見","question":"こういった改修というタイミングでもいいのですけれども、公共施設の自然エネルギー活用などは、地球温暖化防止についてもやはりどんどん進めていく必要があるなと思いますので、今回は現状の改修ということですが、機会を見て、太陽光パネルの増設など、近隣住民の調整などもあるかと思いますけれども、ぜひ検討していっていただければなと考えています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":75,"id":"exchange-031"},{"speaker":"中塚委員","kind":"質問・要望","question":"ちょうど道路上を照らす街路灯のＬＥＤ化を進めたときに、結構まぶしいという話が私のところにも届きまして、でも、だんだんＬＥＤ自身が進化しているので、随分改善されたという話も伺いますけれども、今回、ナイター照明ということで、一定の高さから照らすことになるわけですから、改善されたとはいえ、ＬＥＤ照明がどんなふうに光るのかが少し心配だったので、まぶしさなど。","respondent":"森道路課長","answer":"先ほどご紹介いただきましたように、ＬＥＤの性能も変わっておりまして、出始めの頃はまぶしいというお話が、道路の街路灯でもあったということは私も認識しておりますけれども、最近はそういったお話はありません。しかも、今回、調光ができる、つまり、光の強さを変えられると。","voiceIndex":77,"id":"exchange-032"},{"speaker":"中塚委員","kind":"質問・要望","question":"丁寧に進めていただきたいと思います。今後、契約、１億円あまりの契約案件ですが、工事が始まるときには、説明会は開催されるのでしょうか。もちろん開催に当たっては、近隣の方にどのように見えるのか、あと、実際、稼働してみないと分からないという部分もあるでしょうから、調光ができるということなので、寄せられた意見には、丁寧に対応していただきたいと思いますが、最後に、いかがでしょうか。","respondent":"森道路課長","answer":"いわゆる工事説明会は考えておりませんが、工事を行うに当たっては、近隣の方への説明、チラシを配布させていただいて、こういった業者が、ここでいつからいつまでやりますという話はする予定です。","voiceIndex":79,"id":"exchange-033"},{"speaker":"中塚委員","kind":"質問・要望","question":"ＬＥＤ照明に変えて、電力消費量の削減と二酸化炭素の抑制、これはとても大切なテーマだと思います。ぜひ近隣の方々に丁寧に説明をいただいて、また調整もしていただいて進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":81,"id":"exchange-034"},{"speaker":"ゆきた委員","kind":"確認","question":"様々な事情があっての工事の時期の選択だと思われますが、しながわ中央公園では、日が落ちるのが早い時期にはナイター照明が午後５時から活用されていて、遅い時期には午後７時から活用されていると思われますが、この示されたスケジュールでは、日が落ちるのが早い時期で組まれているのが１点疑問でしたので、この点、１点だけ確認させていただければと思います。","respondent":"森道路課長","answer":"夏に設置工事ができれば、その工事の期間中はライトが使えないということなので、ナイターでの使用ができないということになりますので、数時間、もしかすると、夕方少し遅くまでできるということもあるかもしれませんけれども、すみません。","voiceIndex":83,"id":"exchange-035"},{"speaker":"ゆきた委員","kind":"確認","question":"単年度工事ということで、様々な事情を考慮してのことということで確認させていただきました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":85,"id":"exchange-036"}]},{"id":"topic-05","title":"水とみどりに関するアンケート調査の実施","agenda":"水とみどりに関するアンケート調査の実施","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"緑化や水辺に関する施策推進の基礎資料としてということなので、少し関連して伺います。街路樹は、都市部において、重要なみどりのインフラだと思うのです。そこで少し伺いたいのですが、品川区は、区道や公園などの公共施設に植樹する際の、ガイドラインみたいなものを作成しているのでしょうか。植えるに当たっては、こういうものを優先しているとか、そういったものがあるのかどうか伺わせてください。","respondent":"大友公園課長","answer":"その指針に基づいて実施していくところではあるのですけれども、地区によっても、その通りとエリア等々、場所でどのような樹種にしたほうがいいのかというような考え等々、一定、考えがまとまっているエリア等もありますので、そのような指針に基づいて設定をしています。","voiceIndex":90,"id":"exchange-037"},{"speaker":"安藤委員","kind":"質問","question":"ぜひ、このみどりの整備に当たって、特に区道について、なかなか区道への植樹はあまりないかなという印象があるのですが、こういった場合は、常緑広葉樹を基本にするという、ぜひ方針をこれを機会に持っていただけないかというふうに思うのですけれども、最後にいかがでしょうか。","respondent":"大友公園課長","answer":"街路樹に限らないというところもあるかもしれませんけれども、そのような指針等々、これから前向きに考えていきたいと考えています。","voiceIndex":92,"id":"exchange-038"},{"speaker":"ゆきた委員","kind":"質問","question":"小学生を対象としたアンケートについて、先ほど、小学５年生ということでお話があったと思うのですけれども、これは具体的にどのように進めていくのか。別途実施予定ということで書かれていますが、この点について教えていただければと思います。","respondent":"大友公園課長","answer":"小学生向けのアンケートにつきましてですけれども、こちらは、区内の義務教育学校等の小学生に対し、タブレット端末をお持ちということなので、そのタブレット端末を活用した調査を行うということで考えているところです。","voiceIndex":95,"id":"exchange-039"},{"speaker":"ゆきた委員","kind":"質問","question":"今回の追加項目で、グリーンインフラの整備に関して重要と考える視点については、啓発も兼ねた所管をまたがる教育との連携についてもアンケートが効果的だと感じています。あえて別途で小学生を対象としたアンケートを実施するのであれば、こういった観点も含めて、さらに、ワークショップとか、何か具体的な進め方があるかと思われますけれども、何かお考えがあれば、お聞きできればと思います。","respondent":"大友公園課長","answer":"現在、様々な意見を聞きながら進めていくための手段として、今回、新たにこのようなアンケート調査を小学生にも実施していくところであるのですけれども、その他の機会も使いながら、様々なアンケート、ワークショップ、その他もろもろ。","voiceIndex":97,"id":"exchange-040"}]},{"id":"topic-06","title":"しながわ水族館の臨時休館","agenda":"しながわ水族館の臨時休館","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"再発防止という言葉がありましたけれども、高圧ケーブルの不具合の原因は何だったのか、分かれば教えていただきたいのと、それとあと、今回の停電などで死んでしまった生物は一体もなかったということでよろしいのか伺いたいと思います。","respondent":"大友公園課長","answer":"原因の完全な特定については難しいかと考えておりますけれども、推察される原因としては以上となります。生物については、おおむね健康状態を維持できていると考えているところではあります。","voiceIndex":103,"id":"exchange-041"},{"speaker":"安藤委員","kind":"意見","question":"分かりました。本当に夏休みの最中ということで影響も大きかったかと思います。対応も大変だったと思うのですけれども、きちんと対応などもされているようですし、今後とも、このようなことがないように、日頃の点検なども含めて運営をよろしくお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":105,"id":"exchange-042"},{"speaker":"中塚委員","kind":"質問・要望","question":"いや、技術的に発見できるのであれば、日頃の点検の項目を増やしていただきたいということなのですけれども、そこを伺います。もちろん所管の範囲のご説明でいいのですけれども、つまり、今回の事故を受けて、ほかの施設も含めて、点検の強化といいますか、点検の仕方、ここに工夫ができないのか、その点を伺いたいと思います。","respondent":"大友公園課長","answer":"運営に支障がないレベルの非常用の発電機を置くというような手段も考えられるかと思います。今後のリニューアル等々を見据えて、このようなことが起きないよう、再発防止に努めて検討してまいりたいと考えているところです。","voiceIndex":107,"id":"exchange-043"},{"speaker":"中塚委員","kind":"質問","question":"もう１点だけ。１５日に発生して、まず、何日間停電だったのか。それとも何時間かの停電だったのか、非常用電源に変わったのがどれぐらいだったのか、１９日には復旧したということでよいのか、そこを伺います。庁舎のような建物と生き物がいる水族館とは大分違うと思うのですけれども、でも、優先順位もあるのでしょうか、少ししながわ水族館の対策を伺います。","respondent":"大友公園課長","answer":"しかしながら、今回、事象が発生したとき、猛暑の最中で暑かったため、水温管理が一番重要になるというところで、途中で冷凍庫の電源を水温管理の電源に切り替えを行っております。生物を生かす方向の施設に最大限電源を持ってきて対応させていただいたところです。","voiceIndex":109,"id":"exchange-044"},{"speaker":"中塚委員","kind":"質問・要望","question":"現場と連絡を取り合いながらご対応いただいて、本当に様々なご苦労があったと思います。今回の経験を踏まえて課題を抽出して、今後の対策に生かしていただきたいという趣旨なのですけれども、例えば、非常用電源の規模は、このままこの規模でいくのか。今回の事故を通じて課題として考えているものは何か、今後の対策に生かしていきたいと思っているものは何か、最後にそこだけ方向を伺いたいと思います。","respondent":"大友公園課長","answer":"仮に生物だけを生かす対応を検討していくというところであれば、非常用発電機を大きくするという話もあると思いますので、費用対効果も含めて検討する課題が明らかになったのかなと考えているところです。","voiceIndex":111,"id":"exchange-045"}]},{"id":"topic-07","title":"品川区総合治水対策推進計画改定","agenda":"品川区総合治水対策推進計画改定","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"資料の概要版についてです。今回、概要版だけいただいているのですけれども、計画本体もあるということですか。そちらを確認させていただきたいのと、この概要版のこれまでの取組状況というところに河川整備という欄があります。区では、都に対して河川整備の早期完了等を要望とあるのですけれども、具体的には何を要望しているのか、もう少しここを伺いたいと思います。","respondent":"関根河川下水道課長","answer":"それからもう１点、河川整備の取組状況で、都に対して行っている要望の具体的なものですけれども、例えば、前回ご参加いただきました河川大会、そういったところでの要望もありますし、それ以外にも、城南５区と呼ばれる品川区、目黒区、大田区、世田谷区、渋谷区が共同で。","voiceIndex":118,"id":"exchange-046"},{"speaker":"安藤委員","kind":"質問・要望","question":"それと、河川整備のところでは、具体的に品川区では都に対して河川整備の早期完了等を要望しているということなので、品川区内の河川のことで具体的に何か要望しているのかなと思ったので伺ったのですが、もし目黒川でどうして欲しいとか、立会川でどうして欲しいというものがあれば、具体的にどのように要望しているのか、もう一度お伺いしたいと思います。これが２点目です。これが３つ目です。","respondent":"関根河川下水道課長","answer":"こちらにつきましては、雨水の貯留、浸透施設を設置するときに、例えば、貯留槽をつくるときにはどのぐらい、何立方メートルぐらいためられる、あるいは、浸透施設をつくる場合には、１個つくると、このぐらいの浸透量が見込まれるといったものが指針にあります。","voiceIndex":120,"id":"exchange-047"},{"speaker":"安藤委員","kind":"質問","question":"最後のところは、つまり、何平方メートルぐらい、グリーンインフラといいますか、浸透施設を整備することを目標としているのでしょうか。それとあと、目黒川については、上流のほうの施設だということなのですが、こちらが整備されることで、下流である品川区、目黒川沿いの方も氾濫が抑えられるということもあるのか、その辺りも伺います。","respondent":"関根河川下水道課長","answer":"それからもう１点、目黒川流域調節池につきまして、上流の対策ではありますが、河川は上流から下流へ向かって水が流れてまいりますので、上流の時点で一定水をためることができれば、下流に対しての浸水被害の軽減の効果はあるというふうに認識しています。","voiceIndex":122,"id":"exchange-048"},{"speaker":"安藤委員","kind":"意見","question":"分かりました。導入することで、何らかのインセンティブがあるですとか、補助金が出るとか、そういったところも含めて整備していかなければ、なかなか勝手に進んでいくことはないのではないかと思いますので、そういったことも含めて、時間７５mm、まずは目標というところで、災害に強いまちをつくっていっていただければなというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":124,"id":"exchange-049"},{"speaker":"松永委員","kind":"質問","question":"私からは、１枚目のこれまでの取組状況についての中で、この棒グラフについて伺いたいと思うのですが、浸水棟数、時間最大雨量のグラフについてですけれども、令和４年から令和６年にアスタリスクがついているのですが、これはどういう意味でつけられたのかお知らせください。その後、このエリアについては、どういった対策を行っているのかお知らせください。","respondent":"関根河川下水道課長","answer":"令和６年度につきましては、主に西品川におきまして浸水被害が確認されています。こちらは、まさしく区が受託をして整備を進めております第二戸越幹線のエリアになってありますので、こちらの整備を引き続き着実に進めてまいりたいというふうに考えてあります。","voiceIndex":126,"id":"exchange-050"},{"speaker":"松永委員","kind":"質問・要望","question":"確かに南大井のところはお聞きしておりまして、対策をとっていただいているということで、ありがとうあります。ですが、西品川のほうは、今、整備中ということで、もしまた大きな雨が降った場合、こうしたことがまた起きるのではないかという懸念があります。そうしたところの対策もぜひとっていただきたいのですけれども、何かお考えがあれば、教えていただければと思います。","respondent":"関根河川下水道課長","answer":"は整備をしっかりと進めていくということが１つありますとともに、戸越地区につきましては、既存の調整池、貯留管等もありますので、そういったところの活用も引き続きしていきながら、早期の完成を目指すというところが一番かなというふうに認識しています。","voiceIndex":128,"id":"exchange-051"},{"speaker":"松永委員","kind":"質問","question":"ぜひそうした対策をとっていただければと思います。今回そうした浸水被害、エリアについてお聞きしました。その中で、もうやっているとは思うのですが、例えば、西大井の駅前とか、そうしたところも含めて、今後こうした被害がないように、しっかりと点検等も含めてやっていただければと思いますので、よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":130,"id":"exchange-052"},{"speaker":"中塚委員","kind":"提案","question":"この治水対策については、区や都の努力、また、議会での提案や質疑を含めて、資料にもあるとおり、浸水被害が大幅に減少してきたと思います。品川区の地形だったり、川だったりの特徴などは品川区が一番知っているわけですから、改定に合わせて充実させることはもちろん必要なことです。品川区として、地形や川の形や、独自の強化方法、そこをどのように考えているのか伺いたいと思います。","respondent":"関根河川下水道課長","answer":"達成した後も、そこで終えるのではなくて、この取組を引き続き継続していく。その継続し、取組を進めるに当たって、グリーンインフラの新たな取組ですとか、広報などを強化することで、一層加速化していく、そういったことが重要かと考えています。","voiceIndex":132,"id":"exchange-053"},{"speaker":"中塚委員","kind":"質問・要望","question":"なので、谷間や高潮の対策をしっかり強化していくということを改めて伺いたい。そうした避難の取組も強化をしていく必要があると思うのですけれども、いかがでしょうか。特に移動が困難な高齢者や障害者。マンションなどでは、電気室が１階ないし地下にあるということもあり、それが水没してしまうと、長い時間エレベーターが使えなくなるなどもあります。いかがでしょうか。","respondent":"関根河川下水道課長","answer":"私からは、谷間といった地形ですとか、高潮の対策について回答します。まさに委員ご指摘のとおり、そうした谷間ですとか、高潮の対策は重要な対策です。谷間につきましては、繰り返しで恐縮ですが、第二戸越幹線等にをしっかりと進めてまいります。","voiceIndex":134,"id":"exchange-054"},{"speaker":"中塚委員","kind":"質問・要望","question":"そういう意味では、２０４０年までに５０cmの嵩上げ、まずはここはクリアすることは当然ですけれども、それをさらに上回る対策も当然求められてくるのかなと思うのです。それと同時に、実際に被害が発生し得るわけで、その避難方法についても、さらに具体的に落とし込んでいくことが必要だと思うのですけれども、最後にいかがでしょうか。","respondent":"関根河川下水道課長、羽鳥防災課長","answer":"今回見直された計画では、１時間８５mmを目標としておりますが、もちろん８５mmを超えたから一気に大規模な被害が起きるということではなくて。マンション防災の話もありましたので、マンション防災、活動を含めて、マンションの住民、管理組合等々に啓発に努めてまいりたいと考えています。","voiceIndex":136,"id":"exchange-055"},{"speaker":"ゆきた委員","kind":"質問","question":"概要版の別紙の計画の目標、右上のところですけれども、グリーンインフラの活用と流域対策の広報強化とあります。例えば、グリーンインフラをまちの魅力向上や地域経済の活性化に結びつける役割として、産業振興課とか、あと、まちづくりビジョンの策定として都市計画課など、所管を超えての連携で推進していこうと検討しているものがあれば、現在のお考えをお聞きできればと思います。","respondent":"大友公園課長","answer":"今、この連携につきましては、特に東京都と連携を図って事業を進めているという形になるのですけれども、こちらの周知であったり、その具体的な内容、また、先ほどの話でもありました教育とか、そういう分野について。","voiceIndex":140,"id":"exchange-056"},{"speaker":"ゆきた委員","kind":"質問・要望","question":"特に教育委員会での啓発、学校で習ったことは家庭でも話をすると思われるので、さらなる啓発の広がりになると思われますし、また、ぜひ各所管を超えての連携した取組を進めていただければと思いますので、よろしくお願いします。こちらは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":142,"id":"exchange-057"}]},{"id":"topic-08","title":"品川区災害弔慰金等支給審査委員の委嘱および品川区パートナーシップ弔慰金の支給に関する要綱の制定","agenda":"品川区災害弔慰金等支給審査委員の委嘱および品川区パートナーシップ弔慰金の支給に関する要綱の制定","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"大きく２つ伺いたいのですけれども、まずは、制度の周知です。今回、同性カップルも対象にということですので、こういう仕組みができましたよという周知、こういう仕組みもできたので、ぜひ東京都のパートナーシップ宣誓制度を活用してはいかがですかという、両方からの制度の周知が必要かと思うのですけれども、その点をどのように考えているのか伺いたいと思います。","respondent":"羽鳥防災課長","answer":"ですので、防災課といたしましても、区の方針に合わせて、今回、このような要綱の制定をしたいというふうに考えているところです。","voiceIndex":147,"id":"exchange-058"},{"speaker":"中塚委員","kind":"質問・要望","question":"やはり傷つくと。ここに自分の居場所、支援があるのかという声も伺います。やはり条例を、作るだけではなく、生かしていくということは、どこの所管も当然必要なわけですけれども、今回、防災課で要綱の制定と説明ということでありますので、災害時における性的少数者への理解や支援が、差別のない社会へ、一言、ご発言をいただきたいと思います。","respondent":"羽鳥防災課長","answer":"そういった動きは、国や都の動き、他自治体の事例なども参考にしながら、今後、研究してまいりたいと考えています。","voiceIndex":149,"id":"exchange-059"},{"speaker":"中塚委員","kind":"質問・要望","question":"災害時の対策ですけれども、人権上の課題も含めて、対応していっていただきたいと思います。もちろん女性の視点も必要だと思いますが、今はまだ始まったばかりでありますけれども、性的マイノリティの当事者の視点や意見も十分酌み取っていただいて、これを機に対策の強化へ１つ１つ丁寧に進めていただきたいと要望したいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":151,"id":"exchange-060"},{"speaker":"安藤委員","kind":"質問・要望","question":"ジェンダー主流化と言いますけれども、性別に関わらず自分らしく生きられる社会ですとか、あるいは、性の多様性を尊重し合う社会をつくるという政策を、あらゆる区の施策に反映していくという取組を、先ほどもやり取りがありましたけれども、この建設委員会の所管課として、こういった今回の措置にとどまらず、どんどん進めていっていただきたいなというふうに思います。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":153,"id":"exchange-061"},{"speaker":"せお副委員長","kind":"質問","question":"パートナーシップ弔慰金の支給に関する要綱の制定については、大体説明で理解できたかなと思うのですけれども、同性パートナーではなくて、異性のパートナー、いわゆる籍を入れていない事実婚の方についても支給されると聞いたのですけれども、そこら辺の根拠が全然分からなくて、理解できていないのですけれども、教えていただいていいですか。","respondent":"羽鳥防災課長","answer":"「事実上婚姻関係と同様の事情にあった者を含む」と記載がありますので、ここから事実婚の方も対象になると読み取れるという認識です。","voiceIndex":155,"id":"exchange-062"},{"speaker":"せお副委員長","kind":"質問・要望","question":"会派でも、相続はないけれども、こういったところはあったり、あと、自治体によっても、弔慰金が違うのかというところだったり、本当に複雑で分からないなと。区民が理解しているのかということも分からなかったり、私自身も分からなかったりするので、そこら辺も何か周知ができたらなと思います。そこはぜひ工夫していただきたいと要望します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":157,"id":"exchange-063"}]},{"id":"topic-09","title":"その他","agenda":"その他","exchanges":[{"speaker":"中塚委員","kind":"質問・要望","question":"大変お疲れさまでした。伺いたいのですけれども、主な対応ということで、津波の避難対象地域周辺の公園などに避難の呼びかけをしたということですけれども、この４か所にいらっしゃる方に避難を呼びかけたということでよいのか。津波だから危険なのは公園だけではなく、その周辺でしょうと思うのか、実際に寄せられている情報から総合的に判断したものなのか、そこの判断の基準を１点まず伺いたいと思います。","respondent":"羽鳥防災課長","answer":"万が一停電が起きた際は、災害時協力協定を結んでいる民間の事業者などの協力を受けて、電源を確保して冷暖房を確保するということも考えられる。現状の熱中症対策は、そのような対応をとっております。","voiceIndex":164,"id":"exchange-064"},{"speaker":"中塚委員","kind":"質問・要望","question":"熱中症対策についても、民間事業所の協力も得て電源を確保するということでした。そういう経験を持っている区ですから、津波対応というところで、島にお住まいの方々の事前避難、品川区が島の方々とともに連携しながら発揮できる力を持っているのではないかと私は思っているのですけれども、現状まだ自治体間の調整なのか、都が中心に調整をするのか、その辺ももし分かれば教えていただきたいのです。","respondent":"羽鳥防災課長","answer":"東京都の諸島部についての事前避難等の受け入れ、これに関しましては、東京都と調整をして行うことになると思いますので、そのときは都と調整をして連携して実施してまいりたいというふうに考えております。","voiceIndex":166,"id":"exchange-065"},{"speaker":"安藤委員","kind":"質問","question":"１点なのですが、津波の公園等施設に対して避難の呼びかけを実施とあるのですけれども、具体的には、どのような形で呼びかけをしたのかを教えてください。","respondent":"大友公園課長","answer":"公園利用者に対して呼びかけを、直接の声かけであったり、掲示であったりというところで呼びかけをさせていただいたところです。","voiceIndex":169,"id":"exchange-066"},{"speaker":"安藤委員","kind":"質問","question":"何人ぐらいで行ったのかを教えてください。","respondent":"大友公園課長","answer":"すみません、直接のどのぐらいの人がご利用されていてという把握はできておりません。","voiceIndex":171,"id":"exchange-067"},{"speaker":"ゆきた委員","kind":"質問","question":"すみません、本当に細かいところで申し訳ないのですけれども、コールセンターを開設して、問合せが１１件あったということでした。先ほど、避難しなければいけないのかとか、そういった問合せがあったと説明がありましたけれども、ほかにどういった内容があって、どういう回答、対応をされて、ご理解いただけたのかどうかというところを教えていただければと思います。","respondent":"羽鳥防災課長、大友公園課長","answer":"コールセンターの問合せと、その対応の状況です。避難しなければいけないのかという質問が一番多かったのですけれど、その質問に関しましては、現在の状況では避難の案内は出していません。避難の行動は、高台への垂直避難が基本になりますので、近くに高いところがあれば、そちらに避難するようにお子様にお伝えいただくということも１つの方法ということで回答しています。","voiceIndex":176,"id":"exchange-068"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7183#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":55171,"voices":179}},{"id":"r07-20250825-9","meetingId":"r07-cm08","date":"2025年8月25日","dateIso":"2025-08-25","committee":"文教委員会","time":"午後 １時００分～午後 ２時２６分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を33件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"品川区立家庭あんしんセンター指定管理者候補者の公募","agenda":"品川区立家庭あんしんセンター指定管理者候補者の公募","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"今回の委託する業務も、単純に事業だけで見ても６つの事業があるので、様々な事業を行っている場所だと思いますので、しっかり適正に業務ができるようにしていっていただきたいということで、選定基準2)についての考えを伺いたいと思います。３つ目の基準のところでは、物的能力、人的能力を有しているかということでも書いてあるのですけれども、これはどのように判断をしていくのかを伺います。","respondent":"吉野子ども家庭支援センター長","answer":"選定委員会なのですけれども、学識経験者の方２名を配置することになっております。学識経験者の方、恐らく子ども系の関連する経験者の方になると思うのですけれども、知識のある方を選定する予定でおります。","voiceIndex":16,"id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"選定委員会のところでは、学識経験者２名ということで、しっかりそういった外部の知見も取り入れながら選定をして、よりよい施設にしていただきたい。これは要望にしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":18,"id":"exchange-002"},{"speaker":"横山委員","kind":"質問・要望","question":"私からは、確認をさせていただきたいのですけれども、前回の候補者の選定の際と今回で変更点があると思うのですが、その部分を教えていただけますでしょうか。","respondent":"吉野子ども家庭支援センター長","answer":"前回と今回なのですけれども、特に大きく変わったところはありません。やはり今の業務を安全に遂行していただくようにというところで、選定を行う予定でおります。","voiceIndex":20,"id":"exchange-003"},{"speaker":"横山委員","kind":"確認","question":"品川区指定管理者制度活用に係る指針に基づいて、運営者に連続性が要求されることから、公募によらず、特定の事業者を指定管理者候補者として選定を行うことというのが、前回のときもそういった文言が入っていたかと思うのですけれども、今回、連続性という部分が書類には入っていなかったのですが、この辺りは今回はどういった形になるのかを確認させてください。","respondent":"吉野子ども家庭支援センター長","answer":"今、委員のおっしゃられた品川区指定管理者制度活用に係る基本方針なのですけれども、こちらは１０年という期限がありまして、それによらない場合は、指定管理者の公募・選定、公募の原則としましては、公募型プロポーザルでやることが原則となっており。","voiceIndex":22,"id":"exchange-004"},{"speaker":"まつざわ委員","kind":"質問","question":"母子家庭であったり、子育て家庭の支援ニーズであったりというのは、いろいろと多様化をしていて、ここに例えばそういった複雑化したニーズを公募の要件の中に区としてどうやって反映させていくのかというのが１つと、あと、せっかくですから、そういう利用する子どもたちの声。","respondent":"吉野子ども家庭支援センター長","answer":"こちらの指定管理者なのですけれども、第三者委員会というのもやっておりまして、その都度、サービスを受ける場合には、アンケート等を今でも行っていただいているところになりますので、こちらについては、新しい候補者に対しましても。","voiceIndex":25,"id":"exchange-005"},{"speaker":"まつざわ委員","kind":"質問","question":"要は、指定管理者のほうでやってくださいということで。そうすると、５年という縛りが逆に重くのしかかってしまって、例えば２年３年という中間あたりで１回でも２回でも、何かそういう５年という縛りにとらわれずに、間、間で区がこういう手を差し伸べる、話を聞いて大変だという部分には、何かそういうことというのはできるのか、考えがあるのか、教えてください。","respondent":"吉野子ども家庭支援センター長","answer":"今、委員がおっしゃられたところなのですけれども、私ども、今の指定管理者に対しましては、事業が始まるたびに、関連といいますか、話は聞いておりまして、毎月のように指定管理者との会議を行っておりますので、変化に対しましては臨機応変に対応していきたいと考えております。","voiceIndex":27,"id":"exchange-006"},{"speaker":"高橋（し）委員","kind":"提案","question":"だから、プロポーザルの提案の中にそういう点も、やはり今までこうだったけれども、現在の状況の変化とか、今後どのようにしていこうというのが出てきてもらいたいと思うのですけれども、そういう提案についてはどのようにお考えですか。","respondent":"吉野子ども家庭支援センター長","answer":"日々、そういったところの部分は対応できるようにしていこうと考えております。新たな指定管理者に対しましては、やはりこの部分についてはとても大切な部分と受け止めておりますので、しっかりとやっていただきたいと考えております。","voiceIndex":30,"id":"exchange-007"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"議会の委員会とか予算・決算特別委員会の中でも、この家庭あんしんセンターの業務とかについては、こういう課題があって、このようにしたほうがいいという意見がいろいろな委員の方から出ているので、そういうのを踏まえて、先ほどモニタリングもあるというお話でしたけれども、そういった議会での議論を選定に活かしていただきたいと思います。最後にそれだけいかがでしょうか。","respondent":"吉野子ども家庭支援センター長","answer":"日々、変化を、次回の指定管理者に対しては、そういったところも求めて、新たなものにしていきたいと考えています。","voiceIndex":32,"id":"exchange-008"}]},{"id":"topic-02","title":"児童育成手当の所得限度額の改定","agenda":"児童育成手当の所得限度額の改定","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"今回、５万７,０００円引き上げるということで、その根拠といいますか、理由というのはあるのかどうか伺いたいのと、あと、再申請なしで既に出された方の再審査を行ったということは、住民の負担が少なくてよかったと思うのですが、今回１人、対象になる方がいるということで、対象者が増えてよかったと思うのですが、申請はしていないけれども対象になり得る人というのはいるのでしょうか。","respondent":"柏木子育て応援課長","answer":"その中で今回の改正に伴って、追加というのですか。今までですと不承認になっていたものが、承認される方が大体８名から９名いるという形で想定はしています。","voiceIndex":38,"id":"exchange-009"},{"speaker":"のだて委員","kind":"確認","question":"分かりました。そうすると、基準を引き上げた中で、今度の６月分の申請から、今まで申請していなかった人も対象になって、８人から９人ぐらいいるということですよね。やはり、そこでしか申請していなかった人というのは対象にならないということですね。一応、そこの確認。","respondent":"柏木子育て応援課長","answer":"子ども育成手当ですけれども、これは申請されて認定をするという形になりますので、申請されない方につきましては認定はされないということになります。","voiceIndex":40,"id":"exchange-010"},{"speaker":"のだて委員","kind":"質問","question":"今回、５万７,０００円引き上げたというところでは、私はもっと引き上げてもいいとも思うのですが、あと、支給額も月１万３,５００円で、今、子育てする中でいろいろお金がかかるということも言われていますので、そうしたことも必要かと思うのですが、今後、そういったことを考えていらっしゃるのかどうか伺いたいのと、あと、対象年齢も引き上げていくということもあるかと思うのです。","respondent":"柏木子育て応援課長","answer":"支給額の引上げ、あと、年齢の引上げ、あと、回数の増というお話ですが、こちらは品川区の事業にはなるのですが、もともと東京都の児童育成手当に関する条例、これに基づいて各区とも実施しているものになります。","voiceIndex":42,"id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"それは支給回数とかも独自にはしづらいということなのでしょうか。","respondent":"柏木子育て応援課長","answer":"こちら、支給の回数、月もなのですが、今ので言いますと、支給月が２月、６月、１０月という、そちらも施行規則で定められております。","voiceIndex":44,"id":"exchange-012"},{"speaker":"のだて委員","kind":"質問・要望","question":"独自にはやりづらいというお話なのですけれども、ほかのものでも２３区統一とか、そういった形でやられているものもありますが、そうした中でも独自にやっているところもありますので、ぜひ東京都にも働きかけていただきながら、区としても先んじて一歩踏み出せるような形でやっていただきたいと思います。いかがでしょうか。","respondent":"柏木子育て応援課長","answer":"繰り返しになる部分もありますけれども、機会を通じて都のほうにはそういう声を上げていきたいと考えております。","voiceIndex":46,"id":"exchange-013"},{"speaker":"横山委員","kind":"質問・要望","question":"確認なのですけれども、先ほどの周知の部分なのですが、ホームページ等でというのは、８月中とかに案内は掲載予定なのでしょうか。もう１点が、申請の翌月分から原則支給ということだと思うのですけれども、制度改正によって支給対象に新たになった方というのは、例えば、１２月末までに申請すれば６月分から支給みたいな形で、そういった遡っての支給があるのかを教えてください。","respondent":"柏木子育て応援課長","answer":"それと、申請の遡りですが、既に７月末までに申請されている方につきましては、６月に遡っての支給という形になりますが、それ以降につきましては、基本、申請された翌月からの支給になります。","voiceIndex":49,"id":"exchange-014"},{"speaker":"横山委員","kind":"質問・要望","question":"対象になる方に伝えていく手法というのは、ダイレクトに伝えることができると一番理想的と思うのですけれども、現在認定している方のみ通知が行われて、それ以外の方はご自身で、改定される内容、ホームページは８月で、広報しながわも載せていただいているのでしょうか。","respondent":"柏木子育て応援課長","answer":"現在、申請されていない方たちへの周知ですが、正直、ダイレクトにどの世帯がというのは把握ができないものですから、そういう方々にダイレクトに送るということはできませんけれども、ひとり親の関係で様々な相談、また、ほかの手当もありますので。","voiceIndex":51,"id":"exchange-015"}]},{"id":"topic-03","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"全体的な確認なのですけれども、私の捉えだと、児童相談所が虐待を担当して、子ども家庭支援センターは、そこまでいかないような家庭の支援というイメージを持っているのですけれども、それでいいのかどうかということと、この表を見ますと、養護：虐待というのもあるので、そこの確認をさせていただきたいと思います。どういった状況のことをいうのか、伺いたいと思います。","respondent":"吉野子ども家庭支援センター長","answer":"最初に、児童相談所との関係ですけれども、委員のご認識のとおり、児童相談所は一時的な保護ですとか、そういった大きなものに対しては児童相談所のほうで対応していただくことになります。","voiceIndex":57,"id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"もし違いがあれば、後でご答弁いただければと思います。その中で、この間、４月から実施してきて、地域子ども家庭支援センターがしっかり機能しているという認識かどうか伺いたいのと、現在までやってきた中で感じている課題などはどのようなことがあるでしょうか。","respondent":"吉野子ども家庭支援センター長","answer":"これによって、いわゆるお子さんの特性ですとか、そういった発達的な部分の早期の発見ということですと、かなり効果は発揮するかと考えています。今後の課題ですけども、連携はもっと密にして対応していきたいと考えているところです。","voiceIndex":59,"id":"exchange-017"},{"speaker":"のだて委員","kind":"質問・要望","question":"今のところ課題は連携だということです。ぜひ困難を抱えた家庭を支援していけるように、連携も密にしていただきながら、そして、知ってもらわないと相談も来ないと思いますので、ぜひお知らせをしながら、気軽に相談できるような形で進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":61,"id":"exchange-018"},{"speaker":"横山委員","kind":"質問・要望","question":"初めに、子ども家庭支援センターの相談対応数の中で、その他があるのですけれども、全数の中で５件で、地域子ども家庭支援センターの中で１件ということなのですが、その他の中にはどういった相談内容が含まれているのかを教えてください。","respondent":"吉野子ども家庭支援センター長","answer":"子どもの健康の部分、母子保健のいわゆる保健部門が、全てを分かっているわけではありませんので、その都度課題を出して、それぞれ足りない部分を補うような形で、日々、取り組んでいるところです。","voiceIndex":63,"id":"exchange-019"},{"speaker":"横山委員","kind":"質問・要望","question":"先ほどの母子保健との連携も始まったばかりですので、いろいろ今、様々、情報共有だとか、連携を徐々に深めていっていただいている段階かと思っています。力を入れていっていただきたいと私は思っているのですけれども、その辺り、区としてはどのようにお考えでしょうか。","respondent":"吉野子ども家庭支援センター長","answer":"先ほど委員のご指摘の部分、ひとり親相談というところもありましたけれども、まず、今、週に１回援助方針会議というのをやっておりまして、そこには、いわゆる児童相談担当だけではなくて、ひとり親の担当者も入り、かつ、ヤングケアラーの担当も。","voiceIndex":65,"id":"exchange-020"},{"speaker":"横山委員","kind":"質問・要望","question":"は情報をしっかりと持つ、共有すべきもので、しっかりと共有されているかどうかもそうですし、いろいろなところが関わっていけばいくほど、例えば、地域子ども家庭支援センターの担当者の方は分かっているけれども、子ども家庭支援センターのヤングケアラーの方の担当者が分かっていなかったであったりとか、または、同じ方が保育園に通っていて。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":67,"id":"exchange-021"},{"speaker":"まつざわ委員","kind":"質問","question":"例えば、職員の研修の体制で、虐待予防、発達支援とか、そういう高度なケースの対応というのですか、そういった部分の研修は十分にやられていくのかというのを聞きたいのと、あと、ハードな仕事の面で、離職するパーセンテージも多いと思うのです。","respondent":"吉野子ども家庭支援センター長","answer":"２人で行ったことによって、情報の共有化、そごがないような形で行っています。それから、研修につきましては、こういったところの相談内容に対応できるような研修は、今後とも充実させていきたいと考えております。","voiceIndex":69,"id":"exchange-022"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"そういった研修をしっかりやられていて、２人で行くという努力もされていて、その中でもいろいろな相談というのは本当に、傾聴というのはすごく難しいと私も感じているので、そこら辺を本当にしっかりフォローしてあげていただきたいのと、先ほど横山委員がおっしゃいましたが、支援の長期化という部分になると、結局、担当者が途中で替わってしまったりとか、ケースがずれてしまったりして。","respondent":"吉野子ども家庭支援センター長","answer":"支援の長期化なのですけれども、児童相談システムというのがありまして、そこに全ケースの、どういう対応をして、いつどのようにやったかを全て事細かに書いております。","voiceIndex":73,"id":"exchange-023"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"本当にハードで、大変だと思っていますので、メンタルも含めてですけれども、相談するというのはすごくすばらしいことで、窓口を拡充して、本当にいいことをやっていただいているものであるので、職員のメンテナンスというか、そこら辺は引き続きしっかりとやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":75,"id":"exchange-024"},{"speaker":"高橋（し）委員","kind":"質問","question":"この図によると、いろいろな機関が関わっているので、先ほどからお話に出ていますけれども、連携は非常に大切だと思うのですが、具体的にどのような機会に情報共有が、会議体があるだとか、連絡会議だとかがあるのかということが１つと、あと、要保護児童対策地域協議会との関係は何か。その辺り、この図の中心にいるセンター長の今後の決意というか、その辺をお伺いしたいのですけれども。","respondent":"吉野子ども家庭支援センター長","answer":"私の決意といいますか、関係する団体がとても多いので、連携は密にして、話しやすいという言い方は変ですけれども、情報を共有しやすいような部分を大切にしていきたいと考えております。","voiceIndex":77,"id":"exchange-025"}]},{"id":"topic-04","title":"その他","agenda":"その他","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"その結果があれば伺いたいのと、最初のときは４部屋で発見されたということですけれども、その後、増えているのかどうか、伺いたいと思います。その児童は結局眠れなかったと書かれておりました。こうした児童の不安な気持ち、怖い気持ちというのはよく分かりますので、なぜそうなってしまったのかと思うのですけれども、今後、そうしたことがないようにしていただきたいと思いますが、いかがでしょうか。","respondent":"石井学務課長","answer":"そういった中では、今後も、自然の中で宿泊行事を行うものなので、やはり虫が出ることは当然出てきますけれども、そういった中で様々な状況が発生するということで、現場の職員がきちんと子どもたちの声に耳を傾けながら。","voiceIndex":88,"id":"exchange-026"},{"speaker":"のだて委員","kind":"質問・要望","question":"記事の状況だと、たくさんいたというような感じだったので、それは配慮すべきだったと思いますので、今後そうしたことがないようにしていただきたいと思います。今回、行けなかった学校というのは何校あったのか伺いたいのと、楽しみにしていた子どもたちがいると思いますので、今後の代替策というのを考えていただきたいと思うのですけれども、いかがでしょうか。","respondent":"石井学務課長","answer":"一方で、トコジラミ、近年はやってありますけれども、それに対してどのような形で管理体制が取り得るか、そういったこともきちんと検討してまいらねばならないので、当然、子どもたちの体験の確保、そして、その中でどうやって安全が確保できるか。","voiceIndex":90,"id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ今後、代替策を考えていくに当たって、子どもたちの意見も聞いていただいて、一緒にどうやったらできるのかを考えていっていただきたいと思います。まだ３回目の駆除の報告が来ていないということなので、どういう状況か分かりませんけれども、９月の６年生の移動教室の実施がしっかりできるような形で対応していただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":92,"id":"exchange-028"},{"speaker":"筒井副委員長","kind":"質問","question":"殺虫剤も効きにくく、駆除が難しい害虫ですと書かれておりまして、３回目の結果待ちということですけれども、駆除し切れるのか。今後も対症療法的にずっとそのたびに駆除していくおつもりなのかと、また、トコジラミが発生した原因というのは、建物の老朽化とか、そういったこともあるのかと思っているのですけれども、発生した原因というのは、区としてはどうご判断されているのでしょうか。","respondent":"つる委員長、石井学務課長","answer":"一応、建物の部分とかは区民委員会の所管でやっているので、共有されている中で分かるところでお答えになっていただければと思います。ですので、この発生につきましては様々な要因が考えられるのですけれども、なかなか原因の特定については難しいと考えています。","voiceIndex":94,"id":"exchange-029"},{"speaker":"筒井副委員長","kind":"質問・要望","question":"数か月かかるというお話もありましたし、先ほどお話のあったとおり、ぜひお子さんの体験確保のために、光林荘にこだわらず、代替策の検討を積極的に進めていただきたいと思います。よろしくお願いします。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-030"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"この駆除の費用はどのようにするのですかと聞こうと思ったのですけれども、区民委員会のほうだからやめて、先ほどの代替の話ですけれども、６年生ができたと仮定して、そうすると、残り僅かの秋の期間に１７校が行けるように何とかしていただきたいというのが１つ。それと、ただ、行事が詰まっていますので、行ける学校と行けない学校が出てくる可能性がある。","respondent":"石井学務課長","answer":"一方で、例えば、学校によっては実施が可能だという学校もあれば、そうでない学校も出てくる可能性もあります。","voiceIndex":99,"id":"exchange-031"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"なかなか仮定の質問で申し訳なかったのですけれども、ほかの委員からもありましたが、何とかそういう経験をする機会をつくっていただきたい。日帰りでどこか別のところとか、あるいは、コロナのときの屋形船ではないですけれども、そういった方法とか、何らかの方策をぜひ検討していただきたいと思います。もちろん駆除するというのが大前提で、これは要望でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":101,"id":"exchange-032"},{"speaker":"若林委員","kind":"質問・要望","question":"中身については、様々意見、各委員の質疑で確認させていただきました。これだけの質疑をその他の事項でやる項目ではないですよね。これは教育委員会として、本当に委員会への報告事項として、重々反省していただきたいというのが、聞いていた思いです。３６校中１７校が中止、または一部できないと。教育委員会にとって、夏休みの５年生にとっても最も大きなトピックではないですか。意見だけ申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-033"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7137#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":25269,"voices":109}},{"id":"r07-20250825-5","meetingId":"r07-cm08","date":"2025年8月25日","dateIso":"2025-08-25","committee":"総務委員会","time":"午後 １時００分～午後 ３時３２分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和７年度都区財政調整交付金当初算定結果","agenda":"令和７年度都区財政調整交付金当初算定結果","exchanges":[{"speaker":"西本委員","kind":"質問","question":"これが結構な額のところがあるということが１点、これもう少し説明してほしいということと、それから交付金の総額というところなのですけれども、例えば市町村民税法人分とあって１２.２％など、結構プラスになっているところがあるのですが、今税収からすると、バブルだと言われるぐらい税収があるのではないかと言われる部分があるのですけれども、今全体的にですが、どのような状況になっていて。","respondent":"加島財政課長","answer":"ちなみに、今日２０億円増という動きは、令和６年度当初予算も同様の動きをしておりましたので、今後最終補正で対応してまいりたいと考えております。","voiceIndex":5,"id":"exchange-001"},{"speaker":"西本委員","kind":"質問","question":"大体概要が、全体像が見えてまいりました。というものを教えてほしいのです。なぜかというと、品川区の最近の政策の決め方が、例えば学校給食が分かりやすいと思うので、それを挙げると、初めやりましたと。自分たちやりたくてもお金がないから、補助金があったとしてもできないのだなどというようなことが起きているのではないかなと想像するのですが、その辺はいかがでしょうか。","respondent":"加島財政課長","answer":"品川区全体といたしまして、予算ベースでのお伝えになりますけれども、学校給食食材費というものは約１７億円の予算を持っています。それに対して、特定財源のほうが７億円ほど入ってまいります。","voiceIndex":7,"id":"exchange-002"},{"speaker":"西本委員","kind":"質問・要望","question":"でもお金のないところはなかなか困るよねという、そのようなやり取りというものは結構あるのではないかなと思うのですけれども、それは主に区長会、議長会等々であるとは思うのですが、その辺の考え方というか、要望の仕方などというものは、動向的にはどうなのでしょうか。","respondent":"加島財政課長","answer":"その中でこれだけ都区や特別区全体での実施事業の数や、実施している区の数などということ、そのほか財政負担等を鑑みて、当初算定のほうに今回融通させていただいたもので、決して品川区だけが反映すればいいという考え方の下で、この財調算定に臨んでいるわけではありませんし。","voiceIndex":9,"id":"exchange-003"},{"speaker":"須貝委員","kind":"質問","question":"高層マンションも建って、あと地価が相当上がってきている。そして、先ほど交付金の割合ですか、これが今まで５５.１％から５６％に増えた、これは児童相談所創設していくだろうということで、あらかじめ増えているのですが、新聞報道によると、児童相談所の設立を辞退する、やめる区というものが増えていると我々聞いているのですけれども、そうすると、これはまた元へ戻ってしまうということですか。","respondent":"加島財政課長","answer":"これは設置区は、現在１０区ですけれども、令和７年度、令和８年度に開設予定の１２区分までを見込んだ財源規模をカバーできるものとなっておりますので、仮にこの後、例えばＡ区が児童相談所の設置を計画していましたけれどもやめましたというようなことになったとしても。","voiceIndex":12,"id":"exchange-004"},{"speaker":"須貝委員","kind":"質問・要望","question":"何かそのような方たちに対しても、やはり品川区は長く安心して住みやすいまちになるように、その辺は私は考えていただきたいと思います。片やこのように入ってくるから、こちらはいっぱい使っても、いくら使ってもいいのだという気持ちではなくて、やはりそれを多くの区民の方に区民サービスとして回せるような努力をしていただきたいと私は思うのですが、その辺について、ご見解をお聞かせください。","respondent":"加島財政課長","answer":"それから新庁舎建設等を踏まえて、財政負担等を見据えた財政運営をというところですけれども、新庁舎建設につきましては、庁舎整備基金と、それから起債によって、財源を調達する方針を令和７年度予算の中で提出させていただいたところになります。","voiceIndex":14,"id":"exchange-005"},{"speaker":"須貝委員","kind":"質問・要望","question":"質問が悪かったと思うのですが、ちょっと意見だけ言わせていただきます。恐らくこれからもっともっと、新庁舎に関しては費用が増えていくと思うのです。何ですか、インフレスライドで、私はどんどん上げていってしまうと思うのですが、そういうと、もうやはり財政課としても、経理課と一緒になって、できるだけ費用のかからないような、そのような仕組みに目を光らせてやっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":16,"id":"exchange-006"},{"speaker":"石田（ち）委員","kind":"質問","question":"品川区はそこをどう考えているのかということと、あと再開発の補助金が入ってくるわけで、４年間にわたって品川区に入ってくるというか、戻ってくるというか、そのような形になってくると思うのです。ですから、それというものはこの表で見られるところはあるのか、どこの部分になってくるのかということがあるのか伺いたいと思うのですけれども、お願いします。","respondent":"加島財政課長","answer":"それから財調のほうの、再開発を行った際の財調での引き当て分というところですけれども、このフレームの中で直接的に表されているものはございません。全て基準財政需要額の概算値の中で算定を行っているところです。","voiceIndex":17,"id":"exchange-007"},{"speaker":"石田（ち）委員","kind":"意見","question":"分かりました。ということにもなりかねないので、そういったところからも見直していく、一旦立ち止まる、そういった視点が必要なのではないかなと思いますので、ぜひ区のほうでもそうした視点を持っていただければなと思っています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":19,"id":"exchange-008"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。今回この都区財政調整交付金に、品川区から算定項目で要望していった項目という、品川区として要望した項目として、何か特徴的なものなど、こういったものを要望しているのですなどというものがあれば教えていただきたいと思います。それで、全体何項目ぐらい出されて、その中でどのように要望が通ったのかという状況が分かれば教えていただきたいと思います。","respondent":"加島財政課長","answer":"申し訳ございません。品川区の個別提案というところは今資料を持ち合わせていないのですけれども、特別区全体の状況としてお答えさせていただければと思います。最終的な提案数といたしまして、区側のほうからは７４項目の提案を行ったところです。","voiceIndex":20,"id":"exchange-009"},{"speaker":"山本委員","kind":"提案","question":"項目数のところの確認になるのですけれども、７４項目の提案とおっしゃっていただいたものは、品川区ではなく２３区全体ということなのですね。分かりました。過去の委員会で品川区として提案していた数などが質疑になっていたので、知りたかったのですけれども、また別途確認させていただきたいと思いました。","respondent":"加島財政課長","answer":"つまり、設置していない区についてはそこの算定はゼロになりますので、それで図られているような形になります。","voiceIndex":22,"id":"exchange-010"},{"speaker":"山本委員","kind":"質問・要望","question":"ご説明ありがとうございました。調整がなされているということで理解しました。この調整の機会で、都と区での調整だけではなくて、２３区横並びで合理的で平等な関係を進めていただきたいと思うということと、区民に身近な基礎自治体、現場により近い水準で財源配分が行われるよう、今後も配分がさらに充実を、区側の配分が充実したものとなるよう取り組んでいただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-011"}]},{"id":"topic-02","title":"しながわ中央公園ナイター照明ＬＥＤ化その他電気設備工事請負契約","agenda":"しながわ中央公園ナイター照明ＬＥＤ化その他電気設備工事請負契約","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"毎回申し上げてしまいますが、１億五、六千万円の電気工事に対してＪＶを使わなければいけない、２社共同企業体という形を取っているのですが、この程度の規模でこれだけのＪＶを使ってまで入札しなければいけないぐらい、品川区で入札している企業というものは、何といったらいいのか、力がないというか、対応できない、それだけの規模なのですか。教えてください。","respondent":"佐藤経理課長","answer":"本件につきましても、もちろん１社でも受けるところはあろうかと思いますけれども、今申し上げたとおりですので、そのような形で発注しております。","voiceIndex":35,"id":"exchange-012"},{"speaker":"須貝委員","kind":"意見","question":"毎回同じことを申し上げて恐縮ですが、もう育成というものは、いつも同じような会社名が載っているわけです。経理課として、ＪＶでできるだけ門戸を広げるということも分かりますけれども、やはりある程度規模に応じてＪＶを立ち上げるとか、入札に入ってもらうとか、やはりそのような考え方というものは私は持つべきではないかなと思います。これは意見だけです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":37,"id":"exchange-013"},{"speaker":"西本委員","kind":"質問","question":"今回は、今使っているものが老朽化なので変えるよという話、そしてそれを変えるに当たってＬＥＤという形だということなのですけれども、これＬＥＤにすることによっての、いわゆるコストというものは変わってくる、ランニングコストなどというものは変わってくると思うのですが、これの計算というものはどのような形でされていますか。かなり省エネ化されるのか、どうなのでしょうか。","respondent":"佐藤経理課長","answer":"所管から聞いているというところでお答えいたしますけれども、ＬＥＤ化照明にするによって、従前から電気料は低減されると。それに伴って経費のほうも低減するというように聞いておりまして、今回この工事におきましては、率にして４３％ほど低減するというように聞いております。","voiceIndex":38,"id":"exchange-014"},{"speaker":"西本委員","kind":"質問","question":"もちろん、今後ＬＥＤ化にしていかなければならないという決まりがあるので、いずれにしても変えなければいけないということではあるのですけれども、これ、すみません、少し離れるかもしれないのですが、かなりこのＬＥＤ化も施設全部に対して進んでいると思うのですけれども、ちょっと本題から外れたら申し訳ないのですが、どのぐらい進んでいるのか、かなり削減ができているものなのか。","respondent":"佐藤経理課長","answer":"今回の件は公園の件なので、そちらのほうで聞いている限りということでお答えいたします。公園灯全体におきましては、ほぼ９５％程度進んでおりまして、あと５％程度というように聞いております。","voiceIndex":40,"id":"exchange-015"}]},{"id":"topic-03","title":"デジタルプラットフォームの実施","agenda":"デジタルプラットフォームの実施","exchanges":[{"speaker":"澤田委員","kind":"質問","question":"対面式のワークショップも行われるということで、ＬＩＮＥなども少し苦手だな、見るのはいいけれども打つのは苦手だなという方でも、高齢者の方にも優しいというか、参加しやすかったりするのかなとは思うのですが、それでも、やはり今後、そのようなＤｅｃｉｄｉｍを活用していくこと考えると、デジタルデバイドというか、高齢者の方が多いと思うのですけれども。","respondent":"與那嶺戦略広報課長","answer":"今回これはちょっとこのしながわ防災区民憲章の個別の対応にはなるのですけれども、防災課のほうで非常に多くの方から意見を取りたいという要望を持っているので、これデジタルでやるのですが、紙での意見募集も一応並行してできるようにはしていて。","voiceIndex":46,"id":"exchange-016"},{"speaker":"澤田委員","kind":"質問","question":"スマホだったり、パソコンを持っているということが前提になるかと思うのですけれども、小学生や中学生などの意見は取っていくおつもりはあるのか、お考えはあるのかなということをまず聞きたいということと、もし取っていこうというのであれば、今品川区だったらｉＰａｄを皆１人１台持っているので。","respondent":"與那嶺戦略広報課長","answer":"まさにおっしゃるとおりで、小学生については区立学校でｉＰａｄが配付されているであるとか、今小・中学生の、そういったスマートフォンなどの利用の比率というものは相当高いというようには認識しています。もちろんあらゆる世代のため、若い世代を含めて区政に参加してもらう。","voiceIndex":48,"id":"exchange-017"},{"speaker":"澤田委員","kind":"質問","question":"すみません。ｉＰａｄを利用するということは今のところ考えていないという感じなのですか。","respondent":"與那嶺戦略広報課長","answer":"失礼いたしました。こちら利用するに当たっては、ｉＰａｄからインターネットを経由してできます。当然のように、これが使うことを前提として考えています。","voiceIndex":50,"id":"exchange-018"},{"speaker":"山本委員","kind":"質問・要望","question":"これがいいというところに決まったという、その選定理由を教えていただきたいと思います。それから、今回ワークショップも融合してやっていくということで、これはよいことかなと思っているのですけれども、具体的にはどのように指名ということを考えていらっしゃるか、分かっていれば教えていただきたいと思います。","respondent":"與那嶺戦略広報課長","answer":"ワークショップのやり方といいますか、そういったところについては、今まさに事業所管である防災課と考え方をまとめているところなのですけれども、いわゆるグルーピングといいますか、世代に分けたり、学校の単位など、そういったところでまず話をしてみるであるとか。","voiceIndex":54,"id":"exchange-019"},{"speaker":"山本委員","kind":"質問・要望","question":"今回、様々周知しながら回答数を増やしていくということで、先ほどの澤田委員からのご質問などもありましたけれども、目標としては何件ぐらいを目指していらっしゃるかというところ、あと、今調査、意見募集の結果についてもより多くの方々に知っていただきたいというところもあるのですが、その出し方のところなど、お考えがあれば教えてください。","respondent":"與那嶺戦略広報課長","answer":"こちらの過程については、この取組であるとか、ワークショップの実施経過などをレポートに最後まとめますので、そういったところをこのデジタルプラットフォーム上か、または区ホームページなどでご報告できるという形で進めていこうと考えています。","voiceIndex":56,"id":"exchange-020"},{"speaker":"山本委員","kind":"質問","question":"成果物についても多くの方々に知ってもらって、認知してもらうということはすごく大事かなと考えています。最後に個別テーマの検討ですけれども、既に次に何かお考え、予定しているものなどがあれば教えていただければと思います。","respondent":"與那嶺戦略広報課長","answer":"個別のテーマについては、内部ではいろいろな候補が挙がっているところではあるのですけれども、まだそこがご報告できるほど煮詰まっていないということが正直なところですので、機を見て改めてご報告をさせていただければと思っています。","voiceIndex":58,"id":"exchange-021"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですが、やはりますますといったらいいのですか、高齢者も増えて、ＩＴ弱者を含めた方がやはり増えている。やることは、準備段階としては私は必要だと思うのですけれども、やはりその前に一歩立ち止まって、どうしたらもっと多くの方の意見が聞けるということを考えていただきたいと思いますが、ご見解をお聞かせください。一生懸命職員の方がやっていることも分かります。","respondent":"與那嶺戦略広報課長","answer":"全区民向けのアンケート、これも１つの手段だとは思うのですけれども、こちらは一昨年度実施をいたしまして、当然それも１つの成果を生んだとは思っておりますが、やはり、なかなか費用や、あと作業負荷など、非常にマンパワーも含めて大変な業務であるというところも。","voiceIndex":61,"id":"exchange-022"},{"speaker":"須貝委員","kind":"質問・要望","question":"ですけれども、課長もお若いですから分からないと思うのですが、打ち込むのにやはり小さいのです。それで皆さん、パッと見ることはいい。だからその辺は、私は考えていただきたいと思います。私たち区議会議員は、やはりご年配の方、それから、例えば３０代、４０代の保護者の方、それからお子さんのご意見など、そのようなものに接する機会があるので、いろいろな層の方とお話ししています。回答はいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":63,"id":"exchange-023"},{"speaker":"西本委員","kind":"確認","question":"去年も何か使って、いろいろご意見聞いていると思うのですけれども、１つはマイナーな意見などが出てきた場合や、あとは炎上するなど、そのようなことはあり得るのでしょうか。これだけ見ると、パブリックコメントをもらって、来年３月１１日に整備するよというように書いてあるのだけれども、まさかこれだけで、このプラットフォームだけでこれを決めるのではないですよねということを確認させてください。","respondent":"與那嶺戦略広報課長","answer":"それについては、議論に立ち上がるまでの準備段階ですか、まずどういった目的でこれを行っていて、ここのテーマに対して意見をいただきますというところを一定程度丁寧に説明した上で参加をしていただくというようなプロセスでいきますので。","voiceIndex":64,"id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"炎上するような内容はほかの自治体ではないということは、逆を言えば、それだけ利用されていないということもあるのではないですか。とてもいいことなのです。このデジタルプラットフォームは１つの意見の場だということで理解しました。皆でつくるというか、たたき台はあるにせよ、納得する形でつくっていただきたいという思いがありますので、その辺はよろしくお願いしたいと思いますが、いかがでしょうか。","respondent":"與那嶺戦略広報課長","answer":"最初の炎上対策のところ、改めましては、こちらのほうでも投稿された内容であるとか、随時確認、チェックはしてまいりますので、もちろんリスクマネジメントという観点もありますし、そこはしっかりと運営していきたいなと考えています。もう一つＳＭＳ対応での広告です。","voiceIndex":66,"id":"exchange-025"},{"speaker":"西本委員","kind":"意見","question":"割とそれほどお金をかけなくてもできると思いますので、これは私も自分で言っていいのかどうかという、プラスになるのか、マイナスになってしまうのか、ちょっと分からないのですけれども、でもチャレンジすることはいいのかなと思っているので、ぜひ検討をしていただいて、金額等々も含めて、費用対効果も含めて、検討していただければと思います。意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":68,"id":"exchange-026"},{"speaker":"松本委員","kind":"確認","question":"いないですから、被選挙権を持っている人は。ですから、そこの、まず本人確認を含めた投稿する人の特定の仕方を、今回はどこまで考えていらっしゃるのかというところが１点です。２点目が、先ほど実際に危ない投稿があった場合には削除するというような話がありました。事前の規約のところです。そこが大事ではないかと思っているので、今回はどのように考えていらっしゃるのか伺えればと思います。","respondent":"與那嶺戦略広報課長","answer":"というのも、個人情報をあまりにも取得してしまうと、それはそれで様々なリスクが増すというところであるとか、あまりにもこれが、いわゆる情報収集をしているというように取られてしまった際に、やはり自由な議論ができないのではないかという観点で。","voiceIndex":69,"id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"提案","question":"ですから、やはり周知の方法というものを、今様々ありましたけれども、ほかの皆さんからの提案が。だからそういったところも思い切っていかないと、なかなか広くいかないのではないかなという思いはあります。それで、先ほど課長も、そうした自分の出した意見が区政に取り入れられているという実感を持ってもらうと。","respondent":"與那嶺戦略広報課長","answer":"今回のワークショップの回数なのですけれども、まだ確定はしておりませんが、複数回実施する想定で、今相談をしている形です。これが、今後将来に向けてセットになるのかですけれども、それはマストでないとは思っています。","voiceIndex":71,"id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ですから、そのようなことなしのこの品川区で、こういったデジタルプラットフォームを使ってやっていくというところでは、本当に浸透させることがなかなか大変なのではないかなということは思いますので、ぜひ、私たちも広げていても分かるのですが、区としても様々な工夫をしていただきたいなと。それで今後のパブコメ、パブリックコメントなどもぜひ取れるような工夫も考えていただきたいなとは思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":73,"id":"exchange-029"},{"speaker":"塚本副委員長","kind":"質問","question":"ですかち、きちんとこのように皆様の意見が集約をして、結論としては防災区民憲章にこのような形で反映したというか、手続しましたというフィードバックを、せっかく集まって意見を収集して、いろいろな議論のようなところも起こってくるのであれば、そういったフィードバックするということも、今後これを発展させていく上でも、多くの方に関心を持っていただく上でも。","respondent":"與那嶺戦略広報課長","answer":"それはまた区民の皆さんにお返しするということで、参加の結果を見えるようにしていきたいと考えております。","voiceIndex":74,"id":"exchange-030"}]},{"id":"topic-04","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"西本委員","kind":"質問","question":"何でもかんでもというようにはいかないだろうなと思うのですけれども、行政側としての決め手というか、考え方はあるのですか。取りあえずいろいろなところから、ここで協定組んでください、ここで支援をやりたいですというようなものなのか、それとも全体像があって、いろいろな市区町村ありますが、このようなときには協定を結んでという何か目安的な考え方など、そのようなものはあるのでしょうか。","respondent":"野口官民共創担当課長","answer":"いろいろな自治体と結ばせていただいている中では、特に最近、令和７年結んだ自治体などは、品川区には、今おっしゃられたように、品川区には、早川町や山北町にも自然ありますけれども、品川区にない自然というところで、大多喜町、茨城町であったり、長柄町、矢祭町であったり。","voiceIndex":83,"id":"exchange-031"},{"speaker":"西本委員","kind":"質問","question":"少し弱いなという。私の出身を宣伝するわけではないですが、矢祭町は非常にいろいろ面白い場所がいっぱいありますので、ぜひ区民の方々への特別優遇措置など、多少あそこに行くのだったら少しお金を出しますというようなところでも、そのような何か、自分でいろいろなってしまいますけれども、そのようなところはいっぱいあると思うので、ぜひお願いしたいなと思いますが、いかがでしょうか。","respondent":"野口官民共創担当課長","answer":"そして検討しつつ、今なかなか、先ほど委員おっしゃられましたように、地域の方を巻き込んでいかないと広がりがないのではないかということもいただきましたので、その点も踏まえて内部で検討しつつ、今回いろいろなお祭が縁になってなど、きっかけがありますので。","voiceIndex":85,"id":"exchange-032"},{"speaker":"須貝委員","kind":"質問・要望","question":"実際連携事業をしているということならば、今よく多くの人が移住先として捉えていたり、あとその移住先で、住居や仕事があるのかどうかなど、そのような連携もされておるのかについてお聞かせください。今回答すると、これだけ多々の自治体があるので、一遍にはできないと思うのですが、要望としてそのような資料をいただけるとありがたいなと思います。終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-033"},{"speaker":"山本委員","kind":"質問・要望","question":"今回このご説明いただいたことで、品川区も多くの自治体とのつながりがあるということを改めて理解をいたしました。私も、この多くの他自治体と交流を深める、関わりを増やすということはとてもよいことだと思っておりまして、もっと進めてほしいなと考えています。知ってもらうこと、それから相手をつなぐことを考えたらと思うのですけれども、いかがでしょうか。","respondent":"野口官民共創担当課長","answer":"それを進めていく上で、企業との連携を図っていくためということも改めて検討できればと考えています。","voiceIndex":88,"id":"exchange-034"},{"speaker":"山本委員","kind":"提案","question":"所管が異なる災害などもありますけれども、ぜひ横串を通して、同じように区民からしてみると、そのような連携しているというところで同じだったり、企業の方々からしてみると、そういった同じように捉えられるところもありますので、ぜひそのような見やすく、分かりやすく、区民やメンバーの方から民間の皆様にご提案いただきたいということと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":90,"id":"exchange-035"},{"speaker":"松本委員","kind":"質問","question":"ですから、そうした災害のときを念頭に置いた所管課の連携というところも意識をしていただけるといいのかなというところと、あともう１点は、今災害の連携の協定、幾つかの自治体とやっていただいているのですが、それで足りるのかどうなのかというところが、やはり考えていかなければいけないのかなと思って。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-036"},{"speaker":"塚本副委員長","kind":"質問","question":"具体的にここの自治体とはこのような物資の交換をするとか、この自治体とは具体的に何かの物資の提供をし合うとか、あるいは、この自治体とは職員等を援助し合うとか、あまり個別具体のことはそれほど書いていないと思うのです。この協定そのものについては。そもそも災害でお互いに連携し合って、災害時に支援し合いましょうというパターンというものもあるのかということを最初にお伺いしたいと思います。","respondent":"野口官民共創担当課長","answer":"そうですね。この資料の１枚目にもありますように、高知県や坂井市、山北町、早川町に関しては、災害時が先ではなくて、交流協定が先であったり、高知県、坂井市に関しては包括的な協定が先にあると。","voiceIndex":92,"id":"exchange-037"},{"speaker":"塚本副委員長","kind":"意見","question":"そのようなことですと、恐らくたくさん災害時援助協定を結んだから、何か予算がその分たくさんかかるとあまり、発災したときは別ですけれども、ふだん的にはあまりないのかなとは思うのですが、そのようなことを考えると、基本的には結べる自治体があればどんどん結んでいきたいという姿勢に区としてはなっているのか、やはりある程度、これぐらいの数だよね、災害援助協定というものはということを。","respondent":"野口官民共創担当課長","answer":"なかなか私が所管というところではないので難しいところはあるのですけれども、以前の災害対策担当部長の答弁などを見ますと、区としては、首都直下型地震の際には被災していない自治体への広域的な避難ニーズが高まることを踏まえて。","voiceIndex":94,"id":"exchange-038"},{"speaker":"塚本副委員長","kind":"質問","question":"そうなのです。所管でないとそこまではちょっと分からないですね。個別については。今後の、だから災害援助が最近は大変多いのですけれども、災害に応じて。災害が中心になるだろうということでの展開なのか、災害は災害として、それ以上の、取りあえず災害で結んだところとも、いろいろな形で交流を進めていきたいというようなことでの思いを持っていらっしゃるのか、そのようなところはいかがでしょうか。","respondent":"野口官民共創担当課長","answer":"これまでの事例などを見ますと、災害時協定が最初にあって、その後イベントというものを進めていることが実際というか、実績としてありますので、そのような災害時協定というものは大事なものでありますので、そのようなものを１つの契機として。","voiceIndex":96,"id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問","question":"だからこそ、では言われたからやるではなかなか通らないだろうなと私も思って、それが、ではなぜなのかなということは、明確な基準的なものは本当にないのですかということを聞かせてください。","respondent":"野口官民共創担当課長","answer":"自治体それぞれいろいろな魅力がありますので、何か１つの基準をつくるということはなかなか難しいので、なかなかそこの点は難しいということが実情です。","voiceIndex":98,"id":"exchange-040"},{"speaker":"石田（ち）委員","kind":"質問","question":"分かりました。基準はなかなか難しいということで、今のこの協定を締結する自治体という数でいうと、ほかの区と比べて、数的には多いのか少ないのか。だけれども、この上の包括的な協定や交流協定というものは、もう少しあってもいいのではないかなと思うのですが、これ２３区で見たとき、品川区というものはどのような感じなのか、分かれば教えてください。","respondent":"野口官民共創担当課長","answer":"２３区の実績の数字を持ち合わせておりませんで、お答えはできないところではあるのですけれども、やはり災害協定だったり、そのようなものを結ぶ中で、いろいろな事業を進めていく中で、お互いにとってメリットがあると思えば。","voiceIndex":100,"id":"exchange-041"},{"speaker":"石田（秀）委員長","kind":"質問・要望","question":"坂井市などは市長の考えもあるから、すごいではないですか。それが一番いい例がエコルとごしではないですか。だからそのように交流があるわけではないですか。貸し農園だってあれだけあったけれども、人が減ってきて、もう農園１つ借りるのが抽せんのようなものだった頃から、今なんか２個でも３個でも、どうぞやってくださいという感じではないですか。これではどうかなということもあるではないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":102,"id":"exchange-042"}]},{"id":"topic-05","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"須貝委員","kind":"意見","question":"前回も申し上げたとおり、このたびは辞退します。ただ、勉強会は職員の方が資料を作ってくださるということなので、それについては一緒に参加させていただけるなら、これは一緒に、この委員会の場で参加したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":104,"id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7143#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":50117,"voices":107}},{"id":"r07-20250826-21","meetingId":"r07-cm08","date":"2025年8月26日","dateIso":"2025-08-26","committee":"子ども若者支援・共生社会推進特別委員会","time":"午後 １時００分～午後 ２時１６分","status":"正式会議録","sourceType":"formal","overview":"子ども若者支援・共生社会推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を30件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"鈴木委員","kind":"質問","question":"保育園のあり方ということなので、本当に幅広いことにいろいろな分野から検討していかなければならないなと思っていまして、質問は多岐にわたるのですけれども、まず、２ページの認可保育園の施設数という図表の下のところに、「区立保育園には公設民営保育園を含む」ということで書かれているのですけれども、公設民営保育園というのは、５園を民営化していくという方針になっていたと思うのですけれども。","respondent":"芝野保育入園調整課長、染谷保育施設運営課長","answer":"何点かご質問いただきました。私のほうで答えられるものを答えさせていただきたいと思います。公設民営の保育園、５園ですが、令和７年４月に大井保育園が公設民営化になりましたので、これが５園目になります。それまでは４園です。実際に公設民営の園で働く保育士の待遇ですが、毎年それぞれの園の定員に応じまして、委託料を算定しているという状況の中で、そこで勤務される保育士の方の対応については。","voiceIndex":9,"id":"exchange-001"},{"speaker":"鈴木委員","kind":"質問・要望","question":"区立の保育士の待遇との差というか、そこら辺のところというのは実際どうなのかということを伺いたいのと、社会福祉法人と株式会社の両方あるということなのですけれども、５園のうち社会福祉法人と株式会社が何園ずつなのかというのも教えてください。ここに書かれている3)の区立保育園の民営化というのは、現在の５園のほかに新たに民営化していくという方向なのか、その点を教えてください。","respondent":"染谷保育施設運営課長、芝野保育入園調整課長","answer":"区立の保育士との給与面、待遇の差ですけれども、実際に委託料として支出している金額、それから区立保育園の運営にかかる費用、人件費も含めて、基本的には遜色ない金額といいますか、同様の金額をお支払いしている中で。公設民営のこれからの方向性ですが、民営化ガイドラインには５園を示していますが、今後の保育需要等々を鑑みながら、また改築等の契機を検証しながら、今後公設民営化の検討も併せて進めていくという形になってあります。","voiceIndex":12,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"確認","question":"検証の結果というのはどこかに報告されるのか、取りあえず今のところは５園というふうなことで、その後のさらに幾つ民営化していくという方向というのは、まだ検討中で出されていないということで、そこのところを確認させていただいていいかというのをお願いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"現在公設民営化されている園の進め方ですが、公設民営化が始まったのが令和２年ぐらいからになっていますので、毎年進めてきたということもありますので、５年たった段階で検証して、民設民営化のほうの検討を進めていくですので、５園を一遍にということではございません。","voiceIndex":15,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点でいえば、３月１日の段階になれば、９３％とか９４％まで来ているので、区立・私立保育園ともに、特に１・２歳児は、そして全体としても充足率がかなり高い状況になっているのではないかなと思ってこれを見させていただいたのですが、区としては、そこら辺のところの認識はどう考えられているのか、その点についても伺いたいと思います。","respondent":"芝野保育入園調整課長","answer":"ただし、最新の人口推計によりますと、品川区こども計画で計画している推計とは若干乖離も生じてきていますので、この計画上で何園つくるというのが示されている中で、今後の人口の推計も踏まえまして。","voiceIndex":17,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"６ページのところに、２０園が５０年以上経過していて、今後改築が必要だというふうなことが出されているのですけれども、仮施設を確保して、順次改築をしていくというような方針が書かれていたと思うのです。先ほども説明があったと思うのですけれども、改築に当たっての仮施設というのはどういうふうに確保するということで考えられているのか、その点についても伺います。","respondent":"芝野保育入園調整課長","answer":"品川区保育園等あり方基本方針の前提が変わったことによって、品川区保育園等あり方基本方針の方針自体が変わってしまうのかというようなご質問ですが、品川区保育園等あり方基本方針は基本的には。","voiceIndex":19,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問","question":"それと、縮小するような統廃合というのも、品川区保育園等あり方基本方針の中ではそういう方向になっていくというのが示されていたと思ったのですけれども、人口推計が変化したことによって統廃合のほうは、その推計に合わせて見直していくというふうなことで捉えていいのか、その点を伺いたいと思います。","respondent":"染谷保育施設運営課長、芝野保育入園調整課長","answer":"そういった意味で、拠点としての役割というのは継続して担っていく中で、今後統括園、サポーター園というものをどういう形で運営していくかというところについては、引き続き基本方針の具体化をしていく中で。私からは、統廃合をどういうふうに進めていくかです。品川区保育園等あり方基本方針の中にあります統廃合を含めた再整備は、人口推計を見ながら、慎重に検討してまいりたいというふうに考えております。","voiceIndex":21,"id":"exchange-006"},{"speaker":"鈴木委員","kind":"質問・要望","question":"民営化のところも、次の民営化を打ち出すときに、検証の結果を報告というのではなく、検証の結果をまず報告していただきたいと思いますし、これ以上民営化の方向というのは進めないでいただきたいということも、意見として申し上げておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":24,"id":"exchange-007"},{"speaker":"澤田委員","kind":"確認","question":"幾つかお聞きしたいことがあるのですが、まずお伺いしたいのが、区立園であれば、障害児の受入れというのはマストだと思うのですけれども、私立保育園については、受け入れない園というのもあるのかというのを一度確認させていただいてもよろしいでしょうか。","respondent":"佐藤保育事業担当課長","answer":"特別な支援が必要なお子様に関して、私立保育園で受け入れないということができるのかについてですけれども、新制度に移行して以降、応諾の義務がありますので、入園調整をさせていただいた結果、選ばれた園に関しましては、原則としてお受けいただいているというふうな認識です。","voiceIndex":25,"id":"exchange-008"},{"speaker":"澤田委員","kind":"質問","question":"新制度移行の私立保育園についてはという話だったのですけれども、新制度移行していないところについては選べるというか、その園の考え方によってはというところなのですか。","respondent":"佐藤保育事業担当課長","answer":"私立の認可保育園につきましては、全ての園で受入れをしていただいているというものでございまして、認可外の施設におきましては、様々な園の考え方や保護者の方の希望というのを併せながら、入園されていらっしゃるのではないかなというふうに考えております。","voiceIndex":27,"id":"exchange-009"},{"speaker":"澤田委員","kind":"質問・要望","question":"よく分かりました。そうなったときにゼロ歳児を預かれる区立園というのが現在何園あるのかというのを教えていただきたいのと、私立園もどのくらいあるのかというのが分かれば教えていただきたいです。","respondent":"染谷保育施設運営課長、佐藤保育事業担当課長","answer":"ゼロ歳児園です。区立園で３２園あります。私立保育園につきましても、ほぼ全ての園でゼロ歳児からお受けいただいておりまして、４園のみ１歳児からの園というふうになっております。","voiceIndex":29,"id":"exchange-010"},{"speaker":"澤田委員","kind":"意見","question":"区立保育園のほうは、ぎりぎりオーバーしていないのですけれども、定員３３４名に対して、ゼロ歳児は、卒園時には３３０名いるというところで、かなりぎりぎりだなというのがあって、今後園児自体も増えていく中で、ゼロ歳児の受入れというのを区立・私立ともに増やしていこうと思っていらっしゃるのかどうなのか、その辺の考えを聞かせていただければと思います。","respondent":"佐藤保育事業担当課長、芝野保育入園調整課長","answer":"今お示しいただきましたのは図表、区立・私立保育園における利用者数の推移からだと思っているのですけれども、こちらは確かに定員を超えた人数をお預かりいただいているということがありますが、これは弾力化というものがございまして。区立保育園の件ですが、区立保育園は、定員ぎりぎりですが、こちらのほうは維持させていただき、また全体の定員の見直しの中で検討させていただきたいというふうに考えております。","voiceIndex":32,"id":"exchange-011"},{"speaker":"せらく委員","kind":"質問・要望","question":"確保方策について質問していきたいと思うのですけれども、品川区こども計画を見させていただいていると、結構細かく地域ごとに確保体制、提供体制が示されているのを確認しました。","respondent":"芝野保育入園調整課長","answer":"大崎地区の状況ですが、品川区こども計画上ではマイナスが生じたりしていますが、これは地区をまたいでお預けになっている方も多々おりますので、近隣の全体では十分満たしているというふうに考えておりまして、この計画が今つくられているところです。","voiceIndex":36,"id":"exchange-012"},{"speaker":"せらく委員","kind":"質問","question":"近隣の地区に入れているような形ですね。分かりました。そうなると、大崎地区で３歳から５歳児に対する今後の対策というのは特に考えていらっしゃらないということでしょうか。","respondent":"芝野保育入園調整課長","answer":"何か大崎地区特有の施策というか、対策というのは考えておりませんが、例えば周りの地域も含めて、保育需要が高まって、大崎地域の需要を吸収できないというようなことが試算された場合には、しっかりとその対応をしていきたいというふうに考えております。","voiceIndex":38,"id":"exchange-013"},{"speaker":"せらく委員","kind":"質問","question":"本日の資料の６ページの区立保育園の再整備というところなのですけれども、その前の部分に、病児保育などの特別保育への人員の確保体制の充実というのが書かれておりまして、例えば今後、区立保育園の改築が発生したりするときに、病児保育の確保というのがこれまでもいろいろ話題になってきたと思うのですけれども、そういった部分の確保などもしていくような予定はありますでしょうか。","respondent":"染谷保育施設運営課長","answer":"現状におきましては、ニーズと供給量の関係で見た場合、量というところに関していうと、合計６施設になりますので、一定そこでカバーできるかなと見込んでいるところですけれども、施設を増やしていく中でも、地域偏在についても一定解消される部分はありますけれども。","voiceIndex":40,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"６ページのところで、２０園の保育園が５０年以上たっているということで一覧表になっていますけれども、この改築計画というのは具体化されていないのでしょうか。検討委員会のメンバーについて、どんなメンバーになっているのかも教えてください。","respondent":"芝野保育入園調整課長","answer":"先ほども申し上げましたとおり、改築するに当たっては、仮設園舎を建てる敷地がどうしても必要だですので、こちらについては、先ほども申し上げましたとおり、区有地の跡地の再整備を敏感に捉えて、その跡地の有効活用させていただきながら。","voiceIndex":43,"id":"exchange-015"},{"speaker":"澤田委員","kind":"質問","question":"そういうとき、どうしたらいいのかなというのがあるのですけれども、その場合は、ゼロ歳児の人数がきつきつだと、定員数とそんなに幅がないとやっぱりつらいのかなというのがあるのですけれども、その辺についてはどうお考えでしょうか。","respondent":"芝野保育入園調整課長","answer":"通えないような園というのは、なかなか書かないというか、記載されないので、おおむねご了解いただきながら入園のほうが進んでいるのかなというふうに考えております。","voiceIndex":45,"id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"今後、保育園、また設置も含めて、区有施設の再整備が進んでいく中で、活用もということでお話をしていただいて、今５０年以上の保育園が２０件あるというところで、この建て替え跡地を探しているというところで、これは区内の区有施設もそうなのですけれども、例えば、都とか国の土地とか、施設といったところへのアプローチというか、聞き取りというか、保育園の老朽化に伴う建て替えが必要なので。","respondent":"芝野保育入園調整課長","answer":"交渉なんかも企画のほうがやっているところですので、跡地が見つかるということでございましたら、企画部と連携を取りまして、働きかけを行っていきたいというふうに考えております。","voiceIndex":48,"id":"exchange-017"},{"speaker":"大倉委員","kind":"提案","question":"連携してしっかりと行っていっていただければと思います。こういうのは敷地も園ごとに違うということなのですが、園ごとの敷地がどのくらい必要かというのは、そういう意味ではデータとして全部出ていて、ある程度把握しながら交渉しないといけないというところでは、しっかり分かって捉えながらやっているということでいいのでしょうかという確認をお願いします。","respondent":"芝野保育入園調整課長","answer":"各園の敷地面積等々についてはしっかりと把握していますので、老朽度に応じてその敷地が賄えるかどうかというのはしっかり確認しながら、交渉のほうを進めていきたいというふうに考えております。","voiceIndex":50,"id":"exchange-018"},{"speaker":"大倉委員","kind":"意見","question":"国も都も併せて、様々な使い方をされているところがあるのかなと思いますので、敷地をどう捉えるかなのですけれども、ぜひ柔軟に捉えていただいて、活用できそうな、しっかりと法令に基づいてというと、なかなか難しい土地の場合もあると思うので、そういうところも併せて柔軟に交渉していって、確保していただけるといいのかなというふうに思いました。これは意見です。よろしくお願いします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":52,"id":"exchange-019"},{"speaker":"ゆきた副委員長","kind":"質問","question":"ここの休日保育についての需要が賄い切れているのか、現在利用している方々の実際の現場の声などを把握しているようであれば、お聞きできればと思います。","respondent":"染谷保育施設運営課長","answer":"現状休日保育のほうを実施している園については、ニーズというか、必要数については、不足しているというお声は聞いておりませんで、そこは充足しているものと今認識しています。","voiceIndex":53,"id":"exchange-020"},{"speaker":"ゆきた副委員長","kind":"質問・要望","question":"こちらは要望で終わりたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":55,"id":"exchange-021"},{"speaker":"つる委員","kind":"確認","question":"先ほど鈴木委員のところでもちょっと確認があった公設民営の保育園ということで５園、今後の先の検討とかの最初の園が５年を迎えるのは何年後ですか。","respondent":"芝野保育入園調整課長","answer":"公設民営化園と今ご説明を進めておりますが、最初の園が、三ツ木保育園がちょうど今５年目になっていますので、来年４月に６年目になるかなというような状況です。","voiceIndex":56,"id":"exchange-022"},{"speaker":"つる委員","kind":"質問","question":"大きい考え方としては、運営状況等、効果検証の上、民設民営保育園へということになるわけですけれども、ちょっと分からないところもあるので教えていただきながら、設置者を民間にするというときに、施設の整備だ何だというのは、これまでは区が見ていますとかあるだけではなくて、民設にする際に、民間事業者から、社会福祉法人とか株式会社、現状の１社、４社から、区に何か入ってくるというか。","respondent":"芝野保育入園調整課長","answer":"公設民営から民設民営に当たっての件ですが、今、区のほうで民設民営を検討させていただいているところでは、公私連携型の保育所制度というのを活用する。これは児童福祉法にあるのですが、こちらのほうを活用させていただきたいなというふうには今考えているところです。","voiceIndex":58,"id":"exchange-023"},{"speaker":"つる委員","kind":"質問","question":"ただ、設備的なところについては、今言っていただいたような形で、ただ土地については無償ないし「低廉な」とありましたね。ただ、そういう制度上なのか分からないけれども、ほかの区の持っている土地とかというのは、定期借地とかいろいろあったりすると思うのですけれども、この辺りは、土地については制度の関係でどういうようなものができるのか教えてください。","respondent":"芝野保育入園調整課長","answer":"もう一つの方策としては、非常に安いお金でお貸しするですが、この辺どちらのほうがメリットがあるか、デメリットがあるのかというのは今後検討して、またしかるべき時期にご報告させていただきたいというふうに考えております。","voiceIndex":60,"id":"exchange-024"},{"speaker":"つる委員","kind":"質問","question":"無償提供となってしまうと、そこはもうそれで事業者というふうになっていくと思うのですけれども、先ほど保育だけのニーズ的な議論等々あるわけですけれども、保育園のあり方という観点で見るならば、視野というか、ウイングをもう少し広げて、保育に関わる区のニーズというか、事業で見たときには、当然この方針にも記載があるわけですけれども。","respondent":"芝野保育入園調整課長","answer":"逆に賃貸借という形になると、一定の制約が出てきますので、今は検討の段階ですが、すぐにお返しいただくというのはなかなか難しいのかなというふうに捉えているところです。","voiceIndex":62,"id":"exchange-025"},{"speaker":"つる委員","kind":"質問","question":"ただ、大きいニーズで見たときには土地の扱い、そう考えたときには先ほどのご答弁では、すぐ返してねとやりやすい、どちらかというと地主側が強いケースの契約のやりようだと思うのですけれども、もう一方だと、これは事業者にとってのメリット・デメリットでいうと、逆に言うと、民法上の使用貸借だったら、事業者がなかなかそこには行かないとかというハードルになってしまうということなのでしょうか。","respondent":"芝野保育入園調整課長","answer":"民法上の使用貸借の件ですが、保育園ですので、もちろん大前提として利用者がおりますので、「すぐに閉園、返してくれ」というのはなかなか難しいかなと。これは使用貸借であれ、賃貸借であれ同じ考え方かなというふうに思います。","voiceIndex":64,"id":"exchange-026"},{"speaker":"つる委員","kind":"質問","question":"認可のときだったか、認証のときだったか、園庭がなくてもいいですよとかというところで、とにかく量を増やしていこうというタイミングの質疑の中で、保育園の事業者が、民間事業者ですけれども、民間事業者が保育園をそこに公営していただいて、通年で見たときどのぐらいで分岐点というか、要するに、損益分岐点、投資額を回収できるのですかというのは。","respondent":"芝野保育入園調整課長","answer":"その事業者はほかにも園を数園持っていますので、多分そちらと全体の損益を計算に入れながら交渉の場に臨んでくるのかなというふうには考えているところで、今ご説明がありましたとおり、単独ではなかなか計れないかなというのが現状です。","voiceIndex":66,"id":"exchange-027"},{"speaker":"つる委員","kind":"質問","question":"さっき５年ごとで見ていってその先、それは事業者のタイミングもあるし、人口推計はもちろんあるのですけれども、そうすると、当然保育だけではないその他のものに活用していくというところでは、１０年とか、１５年、２０年という、別に区切りが何かということではないのですけれども、どういうスケジュール感で見ているものなのでしょうか。","respondent":"芝野保育入園調整課長","answer":"見直しのスケジュール感ですが、一番は保育需要がどこまで継続して、今後も必要なのかというところを、人口推計などを見ながら、量の見込みと確保方策をきっちりと整備させていただき、その中で、行政需要がもう見込まれないということであれば。","voiceIndex":68,"id":"exchange-028"},{"speaker":"澤田委員","kind":"質問","question":"単独で園があることがほとんどだと思うのですけれども、その中でここは複合施設というところのメリットがすごくいい形で表れているところかなと思っていて、広さだったり、いろいろな条件はあると思うのですけれども、今後例えば保育園の方向として、複合施設というか、複合化とかというのは、区としてはどうお考えなのかなというのをちょっとお伺いしたいと思います。","respondent":"芝野保育入園調整課長","answer":"保育園と他施設との複合化の件ですが、もちろんその検討は進めていくという中で、土地の広さとか建物の大きさとか、その辺も複合化になると結構広めの土地、建物が必要になってくると思いますので、そちらも併せて、あと行政ニーズ、その地域のニーズをしっかりと捉えながら。","voiceIndex":70,"id":"exchange-029"},{"speaker":"澤田委員","kind":"質問・要望","question":"今言ったのは高齢者施設で、ニーズというのももちろん大事だと思うのですけれども、高齢者の方にとっても、小さなお子さんと触れ合うことは生きがいになったり、元気の源だったり、認知症を遅らせるとかいろいろなメリットもありますし、小さなお子さんからしても、近くにおじいちゃん、おばあちゃんがいない子たち、なかなか会えないという中で、高齢者との触れ合いの中で。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":72,"id":"exchange-030"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7145#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=21&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":21362,"voices":73}},{"id":"r07-20250826-20","meetingId":"r07-cm08","date":"2025年8月26日","dateIso":"2025-08-26","committee":"ＳＤＧｓ推進・行財政改革特別委員会","time":"午後 １時００分～午後 ３時１５分","status":"正式会議録","sourceType":"formal","overview":"ＳＤＧｓ推進・行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を40件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"かなり多岐にわたるので、幾つか質問をします。５ページです。身近なところ、地域でやりたいという話があって、シルバーセンターやゆうゆうプラザで、ぜひＷｉ－Ｆｉを使えるようにしてほしいという要望が届いています。状況というか、実際にどれぐらいついているのかが分かったら教えていただきたいということが１つです。今後の展開なのですけれども、１年に１個ぐらいのテーマがベースになるのでしょうか。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"現在、東品川、大崎、平塚橋、平塚、北品川のゆうゆうプラザ、計５か所に設置しております。シルバーセンターがゆうゆうプラザに移るタイミングで、Ｗｉ－Ｆｉを設置しています。国と連携した通信キャリアのスマホ教室の実績です。もう１つのテーマは、これから検討というところです。プラットフォームも決まったので、それに合わせて、これから検討していくことになっております。続きまして、７ページ目のデータ活用に関する地域課題解決の推進になります。","voiceIndex":6,"id":"exchange-001"},{"speaker":"安藤委員","kind":"質問・要望","question":"８ページです。教職員向けの生成ＡＩ活用研修なのですけれども、区としては、どのような観点で、どのような研修をしているのかをお伺いしたい。これが８ページです。標準化するのにかかる経費が１００とすると、どれぐらいを国が持ってくれて、品川区はどれぐらいの持ち出しをしなくてはいけないのかという割合、金額などといったことをお伺いしたいと思います。そこら辺を伺いたいと思います。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"ＡＩの研修についてです。教職員向けのＡＩ研修については、まず昨日と今日で実施しておりまして、実際、学校の先生に来ていただいて、庁内で実施しております。そのため、特定の限られた方が使用する場所というのは、今のところ公共性が低いという判断で、今、シルバーセンターは設置していない状況ですが、今後の設置については、所管部署も含めて研究していきたいと考えています。","voiceIndex":9,"id":"exchange-002"},{"speaker":"安藤委員","kind":"質問・要望","question":"最後２つなのですが、１１ページです。研修関係なのですが、勉強不足で申し訳ないですけれども、１１ページ、９番の資料で、２の今回の事例を含め、改めてセキュリティ等の注意喚起ということで、今回の事例は何かを教えていただきたい。１２ページです。仮に今年度からの取組だとしたら、現時点でもいいのですけれども、現場の反応や課題はどのような感じになっているのかを伺いたいと思います。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"メールの基本的なところでありますＴｏ、ＣＣ、ＢＣＣとは何か、区からメールを送信するときに、チェック画面というものがあるので、そのチェック画面をちゃんと見ましょうですとか、１回送信ボタンを押して。そこをもう一歩踏み込んで、やはり業務と連動するところを意識して、今年度から実施していくものになっております。説明としては、各部から１つの課で３名以上となって、全部の課ではないことをご認識ください。","voiceIndex":12,"id":"exchange-003"},{"speaker":"安藤委員","kind":"質問","question":"すごく日進月歩の世界なので、難しい面もあると思うのですが、かなりトライアルのこともやりながらＤＸを進めているということは分かりました。大事なことだと思うのですけれども、やはり進める上では、実は職員の方々の現場の声をしっかり伺いながら、進めていっていただければと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":15,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"内容については、昨日の総務委員会でも説明があったのですか。それに対しての意見を求めることが目的だと思うので、そこの設定が非常に難しいと思うのですけれども、そこに関しては所管課に全て任せるということなのか。それはどなたなのか。教えていただきたいです。１３ページのＥＢＰＭの推進のところで、おそらく、前期に私は同じ質問をしたと思います。その辺りを教えていただければと思います。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"こちらに関してですが、おっしゃるとおり、今回、防災区民憲章で実施していくのすが、その中で、やはりワークショップも予定しております。私からＣＩＳＯとＣＩＯについてお答えいたします。どちらも、新井副区長が責任者になっています。最後、１つお答えできていなかった別紙２のデジタルツールの特徴の一番下に書かれている生成ＡＩを用いた。","voiceIndex":17,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"そこについては、先ほどの３課でやるということで分かりました。今回初めてということなので、それだけではないという説明も受けましたけれども、やはり最初の設定がうまくいかないと、繰り返しになってしまいますが、有益なというか、有効な求めている意見が上がってこないということを一番懸念しています。新しい質問です。新しい質問を幾つかさせていただいたので、もう少し確認をさせてください。","respondent":"西澤ＤＸ戦略担当課長、横田デジタル推進課長","answer":"そのように作業の効率化を進めておりまして、所管課がやって、今年は去年多かった質問などをまた追加していて、そのようなやり方で実施しております。デジタル推進課を担任の副区長がやっていることが多いです。ただ一方でデジタルにすごい力を入れている区ですと、外部から招き入れているというところが、３区か４区あったように記憶しております。","voiceIndex":21,"id":"exchange-006"},{"speaker":"筒井委員","kind":"質問","question":"私からは住民参加型デジタルプラットフォームについてお聞きします。実際に現物を見ないと、確かに分からないところがあるのですけれども、令和８年度中に別テーマの実証を並行して検討中とあります。総務委員会の資料では令和７年度中と書いてありました。現時点で別テーマの選定、例えばどのようなものを考えられているのか。現在分かる範囲で教えていただけると幸いです。","respondent":"西澤ＤＸ戦略担当課長","answer":"２つ目のテーマですけれども、今、所管課で、各所管等を含めて検討中というところです。先ほどの答弁と重なるのですが、まだテーマを選定中になります。現時点では、まだこれといったものは挙げられません。","voiceIndex":25,"id":"exchange-007"},{"speaker":"筒井委員","kind":"質問","question":"今までのパブリックコメントなどは、区のホームページから受付をしていたと思うのですけれども、今後そのようなパブリックコメントの意見聴取もデジタルプラットフォームでやっていく予定があるのかということと、今までの電子アンケートなどとどう違っているのか。その辺りを教えてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"デジタルプラットフォームで、先ほどＤｅｃｉｄｉｍ（デシディム）の説明のところにありましたが、区民の意見をほかの人がリアルタイムで確認できる、それに対して返信ができる、それに対して反応ができますので、これまでのパブリックコメントよりもリアルタイム性が高く。","voiceIndex":27,"id":"exchange-008"},{"speaker":"筒井委員","kind":"確認","question":"分かりました。リアルタイムで確認など、「いいね」等のレコメンドもできると書いてありますけれども、すごくいいシステムだと思っています。ある一定のテーマで、このデジタルプラットフォームも使おうとしたときに、やはりその一定のテーマに関わるイベントに、ある程度アナログ的に周知をしていくといったことも考えていかれるのでしょうか。その点を今後どのようにお考えでしょうか。","respondent":"西澤ＤＸ戦略担当課長","answer":"周知の方法です。やはり区のホームページ、Ｘなどでの周知は、予定をしております。そのようなところから周知して、若い方からお年寄りの方まで募集をできたらと考えています。","voiceIndex":29,"id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"様々なＤＸが日々すごく進んでいるということを、この書面の中からは確認ができました。いわゆるデジタルプラットフォームというのは何かと言われたときに、簡単に説明をすると、どのように説明をすればよろしいのでしょうか。ここからも入っていけるようになるのかというところです。そこの確認をさせていただきたいと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"公式ＬＩＮＥについては、こちらの機能としては公式ＬＩＮＥにも掲載できるようになっているのですが、こちらはもう９月１日から始めることもありまして、初回は少し難しいかもしれないですけれども、こちらでもアップできるように検討していきたいと考えております。","voiceIndex":32,"id":"exchange-010"},{"speaker":"新妻委員","kind":"質問・要望","question":"双方向のやり取りができるということですかね。皆さんに挙げていただいた意見のやり取りの中で、その渦中に区が何か返していくということは、途中経過の中ではあるのでしょうか。子どもたちの教育の意見もすごく斬新な意見が上がってくると思うので、教育部門との連携をしながら子どもたちの意見を聞く場にもなってほしいとも思うのですが、そこら辺の考え方もまた教えていただければと思います。","respondent":"西澤ＤＸ戦略担当課長","answer":"もちろん意見を聞くというのもありますが、やはり区の方針、政策、財政の状況などもありますので、全部を全部聞くのではなくて、やはり一緒につくり上げていくといったところがあると考えております。次が公式ＬＩＮＥです。","voiceIndex":34,"id":"exchange-011"},{"speaker":"新妻委員","kind":"質問","question":"先ほどのやり取りがありますと、いろいろな区民の方から意見が上がってきますと、それに対して、その中で上がってくる途中過程での返しは、これが全部終わった段階で区が何を取り入れるかではなくて、途中過程の意見の中に対して区がどう反応するのかなのですけれども、もしそのような途中があれば、教えてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"今回のデジタル化は、そのような機能も有しておりますので、検討に入れながら実施していくことになっています。やはりデジタル共創プラットフォーム自体が区民との対話をしながら行政を進めていくというところがありますので、そのようなところも実施していくと考えております。","voiceIndex":36,"id":"exchange-012"},{"speaker":"こしば委員","kind":"質問","question":"その一方で、どうしても情報弱者の方々が能力というわけではないですけれども、追いついていけない。そこで、今、要請や相談が実際に数として増えてきていることは、地域の区民の利益にもつながってくると思います。当たり前だと思いますけれども、そのような認識でよろしいでしょうか。ＤＸ人材の研修に入っているのでしょうけれども、その辺りを教えていただければと思います。","respondent":"横田デジタル推進課長","answer":"対区民となってきますと、スマホ教室、スマホよろず相談、総務省と連携した通信キャリアに委託してスマホ教室で取り上げてもらったり、東京都と連携して、そのようなスマホ教室をやったりといったところになってまいります。","voiceIndex":39,"id":"exchange-013"},{"speaker":"こしば委員","kind":"質問・要望","question":"委託もあるかと思いますけれども、ユーザーテストというわけではないですけれども、多分その情報を伝える方は、どうしても当たり前にやられていると思います。そこで教えてもらっても、なかなかうまくのみ込めなくて活用ができないという方も、やはり実際に地域の中には多数いらっしゃると思います。その考えについて伺います。","respondent":"横田デジタル推進課長","answer":"ＤＸの推進の一方で、誰ひとり取り残されないという側面もありますので、そのような方の支援も含めて、各地域センターと連携しながら、いろいろなＤＸを推進していきたいと考えております。","voiceIndex":41,"id":"exchange-014"},{"speaker":"山本委員","kind":"質問・要望","question":"私からも何点かお伺いします。この中で何点かお伺いします。なされている場合は、その満足度が高いのかどうかを確認します。質問の中で拾い切れない質問があったときに、最終的にオペレーターにつながるといったところも、もしかしたら必要なのかもしれないと思うのですけれども、要はその辺りのチャットボットで拾い切れているのか確認は、できるかを教えてください。","respondent":"横田デジタル推進課長、西澤ＤＸ戦略担当課長","answer":"ただ複数にわたって、この事業が実施されていますので、効果はあると考えております。ただ、どうやってこの辺りを検証していくかということは、今後、研究していきたいと考えております。このような質問に対して、よかったか、参考になったか、参考にならなかったかというような機能を持った製品も確かにあるので、今後の利用については検討していきたいと考えています。","voiceIndex":44,"id":"exchange-015"},{"speaker":"山本委員","kind":"質問・要望","question":"申込数はお聞きできなかったですけれども、それぐらい埋まっているのは引き続き必要性があるということですので、さらに継続および拡充をしていっていただきたいです。ＡＩチャットボットの満足度の確認ですけれども、これは機能として追加できると思いますので、これを機に進めていただきたいと思います。次にさらにお伺いします。１３ページのＥＢＰＭの推進もぜひ進めていただきたいと考えています。","respondent":"西澤ＤＸ戦略担当課長","answer":"ＢＩツールを配っている所管課は複数ありまして、その中でもイベントのアンケート結果や人口データの可視化などを主にやっておりまして、そこから統計的に取って、イベントアンケートなどは次回のイベントに対して、どのような施策を打ったほうがいいか。","voiceIndex":47,"id":"exchange-016"},{"speaker":"山本委員","kind":"質問","question":"ＥＢＰＭの推進のところでいうと、ＢＩツールを活用した分析８件、多分８件はそれぞれエントリーがあると思っていまして、どのような項目かをお伺いします。難しいようでしたら、結構です。","respondent":"西澤ＤＸ戦略担当課長","answer":"１つ例を挙げるとすると、地域産業振興課で施設利用状況の可視化などといったところを実施しております。文化観光戦略課だと、イベントのアンケートの実施になります。例としては、以上になります。","voiceIndex":49,"id":"exchange-017"},{"speaker":"山本委員","kind":"質問・要望","question":"せっかくなので、もしそれぞれどのようなことを進められるかが分かればと思ったのですが、またの機会でお伺いできればと思います。前後しますけれども、ＤＸａｗａｒｄが１３件あるということで、試行錯誤をしながらということだと思うのですけれども、ぜひサポートアップしていただき、それぞれの部や課でのこのような使い方をまさに前に進めていただきたいと考えています。なければ結構です。","respondent":"西澤ＤＸ戦略担当課長","answer":"そのような公開の方向をどのような施策に反映させたのかは、今後、実施していく予定になっております。","voiceIndex":51,"id":"exchange-018"},{"speaker":"筒井委員","kind":"質問","question":"すみません、２回目です。ＥＢＰＭの推進についてです。この表の見方で、下段の真ん中のところで、（２）オープンデータの可視化、（３）アンケート分析、ツールの活用とあるのですけれども、これは左の仮説立案の（２）、（３）と対応しているということでしょうか。括弧をしていないから、どうなのか。","respondent":"西澤ＤＸ戦略担当課長","answer":"こちらについては、特に意味のないものです。（２）、（３）は誤植で何も意味を持たないものになっています。すみません、失礼しました。","voiceIndex":54,"id":"exchange-019"},{"speaker":"筒井委員","kind":"質問","question":"真ん中の（２）、（３）は、意味がないということですか。ＢＩツールとアンケート分析ツールがあるのですけれども、調べてみますと、いろいろと様々な種類があると思います。データアナリストは、先ほど地域にお強い方というお話もあったと思います。具体的に何か外部委託をされていると思うのですけれども、外部委託先について教えてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"データアナリストについては、区でデータアナリストとして、東京都市大学の大学院生の方を雇っております。去年からこの方を雇っておりまして、それで実施している状況になっています。","voiceIndex":56,"id":"exchange-020"},{"speaker":"筒井委員","kind":"確認","question":"分かりました。データアナリストとの協業では、政策活用する案件の所管と検討中と書いてあるのですけれども、これはまだ現時点で具体的にこれをやっていこうなどというのはないのか。データ活用についてです。先ほどの住民参加型プラットフォーム、しなトークで得られたデータも、当然、今後のＥＢＰＭに活用するデータになるのか確認をさせてください。","respondent":"西澤ＤＸ戦略担当課長","answer":"もう１つのＤｅｃｉｄｉｍ（デシディム）でやっているものも、ものによっては検討になるかと考えています。","voiceIndex":58,"id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"最新の年度で５９.６億円が年間に流出するということなのですが、制度が始まってからの累計流出額がもし分かれば教えていただきたいのが１つです。世田谷区が全国で２番目に流出額が多いということで、区長が廃止を含めた見直しを国に要請しています。他区と比べてもかなり流出しているということで、その要因は何だと考えていらっしゃるのかを伺いたいと思います。","respondent":"宮澤税務課長","answer":"世田谷区も含めて、やはり２３区の伸び率が非常に高まってきておりますので、品川区だけが特出して高まっているとは捉えておりませんけれども、やはり各区の流出額が増えているので、特別区を併せて区民の皆様に現状を説明しているところです。","voiceIndex":64,"id":"exchange-022"},{"speaker":"安藤委員","kind":"質問・要望","question":"かなりの額がこれまでの累計で流出していると思います。実際にそうだと思うのです。品川区民の所得や収入階層別にどれぐらいふるさと納税の寄附をしているのか相関関係は把握しているのでしょうか。それを伺いたいということが１点です。もう１つは、一方で、返礼品の様々なご説明もありましたけれども、なおかつ中間事業者への業務委託開始という話もありました。そこら辺を教えていただきたいと思います。","respondent":"宮澤税務課長","answer":"それとは別に、今回、中間事業者に業務委託をしておりまして、いわゆる寄附者対応等々を含めた先ほど申し上げた業務内容は、寄附額に応じて約６％かかります。１つの寄附に対して、返礼品の調達費用が約３割になります。","voiceIndex":66,"id":"exchange-023"},{"speaker":"安藤委員","kind":"質問・要望","question":"令和７年度の目標額が１.２億円なので、そのうちの５割が返礼品とそれ以外のということになると、経費は６,０００万円ぐらいなのか。区長なのですけれども、２３区長会では、廃止を含めた見直しをということで言っていると思うのですが、品川区長としては、例えば記者会見なども含めて、このような単独で廃止を含めた見直しを求めたことがあるのかどうかを伺いたいと思います。","respondent":"宮澤税務課長","answer":"今年度、今後の取組としては、１０月を予定しておりますけれども、広報しながわで特集号を組みまして、そのような現状を改めて区民に発信するので、区としての考えを発信するです。","voiceIndex":68,"id":"exchange-024"},{"speaker":"安藤委員","kind":"提案","question":"今度は１０月１日に特集号を組むということではありますけれども、ぜひ品川区として、その場でもいいのですけれども、廃止を含む見直しを強く求めていくことを区民にも発信していただきたいですし、ひいては国、総務省にメッセージとして発信していっていただきたいと要望したいと思います。そのようにしていただきたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":70,"id":"exchange-025"},{"speaker":"あくつ委員","kind":"質問","question":"１ページ目のふるさと納税の月額寄附額を見ると、令和６年度で１,６６９万５,３７８円と、１,７００万円弱に対して、令和７年度が目標額１.２億円ということで、１０倍まではいかないですけれども、かなり高い目標額の設定をされています。この積算根拠というか……。積算根拠を教えてください。","respondent":"宮澤税務課長","answer":"１.２億円の内訳です。体験型の返礼品を５,０００万円、商品型を４,５００万円、しながわ団体応援寄附を５００万円で、残りの２,０００万円はクラウドファンディングでやっております。その根拠です。","voiceIndex":72,"id":"exchange-026"},{"speaker":"あくつ委員","kind":"質問","question":"この１.２億円というものは、他区の状況も見ながらということ、今までのいろいろな状況を見ながらということです。これから獲得する寄附金額の上がり具合、割合としては、同じぐらいだと考えているのかということが１つです。品川区として、直近で国に対してどういう動きをしているのか。国に対して働きかけをしているのか。特別区長会の動き、議長会の動き等も含めて教えていただければと思います。","respondent":"宮澤税務課長","answer":"国に対する動きです。直近の動きとしましては、先ほど説明で言いました８月７日に区長会としまして、特別区の主張をまとめたところです。品川区としてそれも受けまして、ホームページやＳＮＳでの発信をしたところです。","voiceIndex":74,"id":"exchange-027"},{"speaker":"あくつ委員","kind":"質問・要望","question":"ほかの４区のうち３区が同じような特設サイトを設けて、１０億円ぐらい集めているというところです。私も情報収集不足で、もし差し支えなければ、その３区はどこなのかを教えていただきたいということが１つ。この制度の在り方の変更についての働きかけを、ぜひより一層強くしていただきたいと思います。前段の部分だけ教えてください。","respondent":"宮澤税務課長","answer":"他区の部分です。毎年、総務省がふるさと納税の流出・流入額を調査しておりまして、これは総務省のホームページでも公表されております。世田谷区、新宿区、渋谷区になっております。","voiceIndex":76,"id":"exchange-028"},{"speaker":"山本委員","kind":"質問・要望","question":"増加の要因をどう見ているか。要はどこからの寄附のルートが多いかなどといった分析等があれば教えていただきたいということです。現地決済型ふるさと納税の取組についてもいい取組であると思っているのですけれども、ご説明で店舗数４２店舗ということで、これは少し少ないのか、もっと増えていったらいいと思っているので、その辺り増やす方策などで考えていることがあれば教えていただきたいと思います。","respondent":"宮澤税務課長","answer":"ただ、先ほど説明で申し上げましたドウシシャの製品は、寄附額１万９,０００円で、やはり比較的手の届きやすい金額帯は、寄附件数が伸びているところです。一方で高額なものも一定数あるところです。現地決済型です。","voiceIndex":79,"id":"exchange-029"},{"speaker":"山本委員","kind":"提案","question":"それぞれ理解をいたしました。お聞きして、やはりいろいろ進めていくと、分かってくることがあると思った次第です。いろいろと手間はかかるところですけれども、いろいろな方々のアイデアや工夫をお聞きいただいて、取り入れて、拡充を図りつつ、地道にはなりますけれども、寄附額の受入れ増大に向けて取り組んでいただければと思います。１つご提案になります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-030"},{"speaker":"筒井委員","kind":"提案","question":"ドウシシャの製品もやはり手が届きやすい価格ということで、そうした商品、価格も、恐らくボールペンやグッズだったら、より手が届きやすい価格になると思いますので、そのような今回の品川区のＹａｙ Ｙａｙ Ｓｈｉｎａｇａｗａ ２０２５の岡部志士さんの作品を活かした商品を開発して、返礼品にしてみてはいかがかと思うのですけれども、区としては、その辺りをいかがお考えでしょうか。","respondent":"宮澤税務課長","answer":"そのような基準を満たして、今、返礼品に用意できないか検討しています。","voiceIndex":83,"id":"exchange-031"},{"speaker":"筒井委員","kind":"質問","question":"分かりました。先に一般販売をすればいいということですね。ある程度時間がかかるかもしれないですけれども、一般販売できる体制を整えてから、それを返礼品に使うということでよろしいでしょうか。","respondent":"宮澤税務課長","answer":"基準の中に細かくありまして、一般販売している価格と同等数に抑える必要があることになっております。つまり一般販売を１００すれば、返礼品は１００の用意という形になっておりますので、そのようなところもあって、どうできるか検討してきたところです。","voiceIndex":85,"id":"exchange-032"},{"speaker":"筒井委員","kind":"質問・要望","question":"そのような規制というか基準があることも、非常におかしな制度と思いますけれども、承知しました。先ほど私が申しました区民の団体もグッズを作ってほしいという声もありましたので、そうしたところと連動して、しっかり進めていっていただきたいと思います。ぜひその辺りよろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":87,"id":"exchange-033"},{"speaker":"まつざわ委員","kind":"質問","question":"しながわ団体応援付寄附金は、学校法人がメインになっています。結局これは、これ以上にこれから先に例えば社会福祉団体、文化事業の団体といった対象の拡大という可能性はあるのか。お伺いします。","respondent":"宮澤税務課長","answer":"いわゆる条例で指定されている税額控除の団体の中には、委員ご指摘のように社会福祉法人、一般社団法人等々があります。そこら辺の拡大に関しましては、今回、学校法人で始めさせていただきまして、実績、動向を注視しながら拡大するかどうかは検討していきたいと考えています。","voiceIndex":89,"id":"exchange-034"},{"speaker":"まつざわ委員","kind":"質問","question":"分かりました。例えばもし仮に３０億円があったら、このようなことができますみたいに、そのような周知がいいだろうと話もさせていただいたことがあります。要は先ほど返礼品目的ではないという話もありましたけれども、やはり地元を応援させる、そのような気持ちを高める工夫というのでしょうか。郷土にどう愛着を持たせていくのかという区の考えを教えてください。","respondent":"宮澤税務課長","answer":"そのような取組をしていますというのは、先ほど説明いたしました広報の特集号でもＰＲしていきたいと考えていますし、今後、特設サイトでもそのようなことを充実させていって、区民の皆さんにお伝えできればです。","voiceIndex":91,"id":"exchange-035"},{"speaker":"まつざわ委員","kind":"質問・要望","question":"やはり広報はとても大事で、特集号もやっていただいて、すごいです。勝手なイメージですと、広報は、ご年配の方がよく見られる。ご年配の方は、そのようなことにあまり知識がないのか。勝手にこのようなことを言ったら、怒られるかもしれません。それだけではなくて、ＳＮＳなど広報の種類はいろいろあると思うのですけれども、いろいろなやり方でぜひ応援額の拡充を図っていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":93,"id":"exchange-036"},{"speaker":"新妻委員","kind":"質問・要望","question":"今、まつざわ委員からありました品川区民ができる品川区のふるさと納税について、もう一歩のアピールが必要かと思っています。今ありましたけれども、品川区民ができるふるさと納税のやり方は何があるのか、いま一度教えていただきたいと思います。","respondent":"宮澤税務課長","answer":"ただ、先ほどのとおり返礼品を伴うものはできないのですが、返礼品を伴わない単純な区に対する寄附であったり、例えばクラウドファンディングであったり、今回用意していますしながわ団体応援寄附は、ふるさと納税として２,０００円を超える部分は。","voiceIndex":95,"id":"exchange-037"},{"speaker":"新妻委員","kind":"質問・要望","question":"そこをもう一歩、評価をしていただきたいという思いがあります。チラシ１枚にしても、たしか区内の団体事業者、企業などに対するふるさと納税のご案内はあったと思います。個人に対する品川区にできるふるさと納税のアピールチラシのようなものも、ぜひ作成をしていただきながら、あらゆるところで品川区を応援してもらいたいという発信の強化をしていただきたいと思いますが、いかがでしょうか。","respondent":"宮澤税務課長","answer":"今年度のクラウドファンディングは、９月１日より、例年行っている子どもの未来を応援するクラウドファンディングを実施していくということで、チラシも作成し、区民に向けて配布していると聞いております。","voiceIndex":97,"id":"exchange-038"},{"speaker":"新妻委員","kind":"意見","question":"しながわ団体応援寄附についてのサイトには、赤文字で品川区在住の方も寄附いただくことが可能ですと書かれておりますので、この一文を目立つように工夫をしていただきながら、品川区民が品川区のために応援をしたいという思いで、そのような寄附をしてくださる方が多くなりますように工夫をお願いしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-039"},{"speaker":"こしば委員","kind":"質問・要望","question":"確認したいのですけれども、去年の１２月の件数が約４００件と、突然上がっておるのですけれども、時期に着目した取組が何か行われていたのか。今年１.２億円の非常に大きな目標を立てる中で、残り８か月、これは時期に着目して取り組むものはおありなのかどうかを教えていただきたいと思います。","respondent":"宮澤税務課長","answer":"昨年、令和６年度の１２月の寄附件数額が伸びている要因は２つございまして、１つは体験型の返礼品でセガサミーと連携しましたセガサミーのプロのダンスチームのファンミーティングを返礼品として、商品を展開したのがちょうど１２月で。","voiceIndex":101,"id":"exchange-040"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7147#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=20&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":39348,"voices":107}},{"id":"r07-20250827-22","meetingId":"r07-cm08","date":"2025年8月27日","dateIso":"2025-08-27","committee":"まちづくり・公共交通推進特別委員会","time":"午後 １時００分～午後 ２時２０分","status":"正式会議録","sourceType":"formal","overview":"まちづくり・公共交通推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"えのした委員","kind":"質問・要望","question":"私も地元で交通量調査、ビーコンというのですか、かなり設置して、数か月にわたって行われたことがありました。例えば学校では人工芝の上で飲物も水以外駄目とか、食べ物を食べてはいけないとか、ジュースを飲めないとかとあるのですけれども、キッチンカーとかが来たときに、その辺はもう学校とは全く違う人工芝の取扱いなのか、その辺を詳しく教えていただけますでしょうか。","respondent":"中道都市開発課長","answer":"今回地元とお話ししている中では、毎日かどうかは分かりませんけれども、高圧洗浄機で定期的に洗わないと、そこではどうしても食べ物の残り物というのが問題になると考えていますので、対応していきたいと考えています。","voiceIndex":5,"id":"exchange-001"},{"speaker":"えのした委員","kind":"確認","question":"先日の神田神保町の視察も行かせていただきましたが、そちらを踏まえて、今度、「なんだかんだ」という取組で、９月１日に防災を絡めたイベントがあるというので、私も行きたいなと思っていたのですけれども、こういった中で、これからだと思うのですけれども、防災に関した何か取組というのはお考えいただいていますでしょうか。","respondent":"中道都市開発課長","answer":"今回の社会実験の中では防災という形ではなくて、先ほどのウォーカブルという形での居心地のよさというところに特化して調査を行っていきたいと考えています。","voiceIndex":7,"id":"exchange-002"},{"speaker":"えのした委員","kind":"質問・要望","question":"これからですけれども、ぜひそういった防災に関することも取り組んでいただければと、こちらは要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":9,"id":"exchange-003"},{"speaker":"松本委員","kind":"質問","question":"１つは自転車の動線との関係という話であったかと思います。というのも、今回だとこの通り全体の歩道が増えるというよりも、一部分だけ今回は飛び出した形になっているかと思うのですけれども、これはやってみてでないとなかなか分からないところかもしれませんが、将来像としては、行政としては今、どのように考えていらっしゃるのか伺えればと思います。","respondent":"中道都市開発課長","answer":"検討中ですけれども、基本的にやはり自転車は車道を走るものですので、今回、イメージとしては今、赤枠で飛び出している部分の外側、いわゆる灰色の道路の部分を自転車に通っていただくということを考えています。","voiceIndex":10,"id":"exchange-004"},{"speaker":"松本委員","kind":"質問","question":"自転車については、最近自転車に加えてＬＵＵＰですか、あちらもいろいろと問題になっています。そういう意味では、車道のところで自転車とかそうしたものが通行できるほどの幅が確保できるのかというところで、車がいて自転車がいても一応十分な幅が確保できるというお見込みなのかというところを改めてお伺いいたします。この辺りの工夫はどのように、今、考えていらっしゃるのか伺います。","respondent":"中道都市開発課長","answer":"工夫といたしましては、入り口部分に板を貼るとか、看板を貼るとかして、人の動線が分かりやすいような形で取り組んでいきたいと考えています。","voiceIndex":12,"id":"exchange-005"},{"speaker":"田中委員","kind":"質問・要望","question":"何点かお伺いをしたいと思います。公の事業なのでいろいろなところへの配慮が必要かと思います。その観点からお伺いしたいのですが、にぎわいを創出することを目的にこういう設置をするわけですから、キッチンカーなども呼んでということであります。多く人が集まればもちろんいい一方で、やはりこの沿道には既存のコンビニですとかうどん屋さんとかいろいろな飲食店もあります。","respondent":"中道都市開発課長","answer":"土日とか、休日につきましては、もちろんキッチンカーとかもあるのですけれども、どちらかというと物産展みたいな、イベントみたいな形を今、計画していたりとか、ちょっと何かここでそういったイベントをやってみたり、歩道を拡幅することを検討しています。","voiceIndex":15,"id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"人が、人数が集まったらそれはよしとするのか、あるいは周辺の商店も含めた、あるいは地元の方の意見等々も評価の対象にするのかとか、あるいは先ほど言ったように、トラックスが開業前の１回目の実験なので、開業後のことも踏まえるとまだまだ第１弾としての実験になるのかな、今後はトラックス開業後の期待を踏まえて継続をするという考えなのか、その辺をお聞かせいただきたいと思います。","respondent":"中道都市開発課長","answer":"実験の継続ですが、まず今回、今年、今年度実験を行いまして、そういった評価を踏まえて、また区のほうで今後どうするかというのは検討していくというものにはなるかと思いますけれども、やはり数回やることによってより効果が出るのかなとは所管としては今、考えている状況です。","voiceIndex":17,"id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"要望で終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":19,"id":"exchange-008"},{"speaker":"藤原委員","kind":"質問","question":"改めてお伺いします。このコインパーキングはもうなくなってしまうということでいいのでしょうか。その辺についていかがですかと。〔同日後刻に「先ほど補助２０５号線と言ったのですけれども、補助１６３号線でした」と発言訂正あり〕 あと、ＡＩカメラで、今、人の流れはＡＩカメラで分かると思うのですけれども、顔の表情から利用者の感情も分析と、そこまで今のＡＩカメラというのはできるのですか。","respondent":"中道都市開発課長","answer":"おおむねＡＩカメラで表情分析したものと、人が口頭で楽しかったよとかと回答したものが一致しているということも確認しておりますので、一定程度精度の高い分析ができると判断しています。","voiceIndex":20,"id":"exchange-009"},{"speaker":"藤原委員","kind":"確認","question":"一番最初に質問したみたいに、まずはやってみようということなので、これで決定で、大井町駅前中央通りがこういう形になりますということで、まだ地域の方には実験ですからというようなお話をしていいですねという確認です。この社会実験ですと、社会実験の分析の結果、施策として本格的に進めていくか考えていくということで地域の方にお答えしていいのですよねという、再度の確認の質問です。","respondent":"中道都市開発課長","answer":"今回はあくまで実験というところで、地域の方にご説明していただければと思います。","voiceIndex":22,"id":"exchange-010"},{"speaker":"塚本委員","kind":"確認","question":"どんたくのイベントとかすごく人が出ているので、そういうことを指しているのかなと思いますけれども、日常的に訪れる場所にしたい、日常的に人通りが多い道になってほしい、これはいわゆる大井町駅前中央通りのことを指しての発言ということだと思っているのですけれども、ここに日常的に人が今以上にたくさん通行するということを望まれる意図というのは。","respondent":"中道都市開発課長","answer":"地域の意見ですけれども、今回検討会をやるに当たって、町会の方々、商店街の方を中心に検討会を行いました。そうした中で、様々な意見があったのですけれども、まずは人通りについて。","voiceIndex":25,"id":"exchange-011"},{"speaker":"塚本委員","kind":"確認","question":"駐車場という話が出てきていますけれども、もし将来的な選択肢の中には、ここは本当に道路１車線にして、片道１車線にして、もっと人のウォーカブルな道路にしていこうというようなことも選択肢としてはあるのかなと今までの質疑で伺いましたけれども、駐車場をなくすという、１時間３００円の駐車場のことですけれども、これに対してのなくした場合の影響、どれぐらいのことが考えられるのかとか。","respondent":"中道都市開発課長","answer":"大井町トラックスができるとそちらのほうにも大型駐車場ができますので、こういった継続して社会実験をやることで、そこの大井町トラックスの駐車場のほうの利用率みたいなものも上がれば特段影響がないのかもしれませんので、そういったことも確認していきたいと考えております。","voiceIndex":27,"id":"exchange-012"},{"speaker":"塚本委員","kind":"提案","question":"今の駐車場の件でもう１つ確認です。もしかしたら所管が違うのかな。一応分かる範囲で。そういう空間の創出ということに至ったのは、この実証実験されたところのからの提案というか、そういう話があったのかというところもあるかとは思うのですが、区として空間の創出というところを念頭に置いている、その考えについてのもうちょっと詳しい見解を伺いたいと思います。","respondent":"中道都市開発課長","answer":"そこでやはり一番大事なのは、地域の方が継続してこういったにぎわいの取組というのをやっていただけるかどうかというところが非常に重要かなと考えていますので、それのいわゆる考え方というのを今回の実験で具体に地域の方にお見せして、そういった。","voiceIndex":29,"id":"exchange-013"},{"speaker":"塚本委員","kind":"質問・要望","question":"ご説明ありがとうございました。かなり地元の方々のやはり意向というのは、これまでの話も出ていましたけれども、そういった中で大井町トラックスのいわゆる波及効果みたいなことをしっかりとこっちの地域のにぎわいにつなげていきたいというところの狙いはよく分かりますので、実証実験をまずはしっかりと注視させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-014","title":"議員研修会の内容"},{"speaker":"若林委員","kind":"確認","question":"スケジュールですが、この実証実験は秋もしくは春かに、二、三週間ということです。そうすると、大井町トラックスは来年３月末の開業ということで、この開業後の二、三週間という意味か、それとは別ですよと、もう今年の秋にやってしまいますよという意味なのか、そこを確認をさせてください。","respondent":"中道都市開発課長","answer":"開催時期なのですけれども、すみません、資料を作成しているときはまだ具体に決まっていなかったということでこういう書き方をしたのですけれども、今、実験の時期は、この秋のハロウィンが１０月下旬にありますので、それをスタートとして、今。","voiceIndex":34,"id":"exchange-015","title":"議員研修会の内容"},{"speaker":"若林委員","kind":"質問","question":"すなわち、一つ目に書かれているように大井町トラックスにいらした方々の来訪が予想されると。区道も、あと都道とかもあるのですか、国道はないですよね、あそこら辺は。ないですね。今回は藤原委員がおっしゃった、何でどんたく通りの行き止まりまでではないのですかというところ。いや、来年度予算では、みたいな話だといけないと思うので、現在の見解は伺いたいと思います。関連性はいかがなのでしょうか。","respondent":"中道都市開発課長","answer":"大きい計画というところで、２０２０年に大井町駅周辺地域まちづくり方針というものを策定しています。その中に、大井町駅前中央通りについても記載をしています。","voiceIndex":38,"id":"exchange-016","title":"議員研修会の内容"},{"speaker":"石田（秀）副委員長","kind":"質問・要望","question":"１点だけお願いだけしておきます。ぜひやっていただきたいのですが、２週間なら２週間、３週間なら３週間でもいいのですけれども、土曜から始めて日曜日で終わる、だから２週間だったら３回土日があるというようにして社会実験をやっていく、３週間なら４回あると、そういうやり方をぜひ、休みのデータを多く取ったほうがいいのかなと思っているので、それだけお願いしておきます。そうなるのかな。","respondent":"中道都市開発課長","answer":"期間については警察との協議の中で決定したものもありますので、また前向きに検討させていただければと思います。","voiceIndex":41,"id":"exchange-017"},{"speaker":"のだて委員長","kind":"質問","question":"ほかにないでしょうか。品川では目的に照らしていろいろアンケートですとかＡＩカメラによる検証をやるということですけれども、効果検証がそれでしっかりできるのかどうかというところを伺いたいと思います。今回の社会実験を同様のものにしてはいけないと思いますので、今回の社会実験が超高層の再開発につながっていくものなのかどうか伺いたいと思います。","respondent":"中道都市開発課長、高梨都市計画課長","answer":"どんたく通りでいわゆるにぎわいを創出する。憩いの空間といったものに取り組んでいく。地域の皆様の活動を継続的に行えるように、実験も取り組んでいきたいといったことが目的です。右上２段目、民間施設のライトアップは、ライトアップ空間の充実のため、現在実施されている民間施設のライトアップと連携した検討などを行ってまいります。","voiceIndex":43,"id":"exchange-018"},{"speaker":"藤原委員","kind":"意見","question":"これは課長のご答弁ではないかもしれないけれども、観光という意味において、ライトアップにどういうイメージを抱いているのか。ライトアップされると明るくなっていいよねだけではないと思うので、その後どういう形で人を呼び込むとか、その辺の大きなイメージでいいのですけれども、こういうふうに変わるのですよとか、こういう戦略があるのですよというようなことを説明していただけますか。","respondent":"関根河川下水道課長","answer":"今、ご質問いただきましたライトアップについてお答えします。冒頭の説明の中でも、今後新たな演出等の検討と述べさせていただきましたけれども、まさしくどういったライトアップをすればより魅力的なライトアップになるかという検討を今年度から実施していく予定です。","voiceIndex":48,"id":"exchange-019"},{"speaker":"藤原委員","kind":"質問","question":"課長、ワクワクしていいのですよね。ライトアップは結構お金がかかるではないですか、電気代も含め。例えばここだったら競馬場のライトアップだとか、そういう意味でいろいろ循環というか、回遊していくような、八潮・勝島というまちづくりをしてほしい。課長、ワクワクするかしないか最初に答えていただいて、その後した質問において答えていただけますか。","respondent":"関根河川下水道課長","answer":"それからもう１点、ご指摘された費用のところもまさにご指摘のとおりですので、今回の検討の中では、併せて持続可能なライトアップを目指しまして、維持管理等についてもどのようにすれば効率的に実施できるか、そういった検討も併せて行う予定としています。","voiceIndex":50,"id":"exchange-020"},{"speaker":"藤原委員","kind":"質問・要望","question":"せっかくこれをやるわけですから、他自治体の方も見に来てくださって、すごくきれいだったねと感動してワクワクして帰っていっていただきたいと思っていますので、ぱっとライトをつけただけで終わらせないようにしていただきたい。せっかくやるわけですから、何か所も、本当に観光施策の一つとしても活用していっていただきたいと考えていますので、改めて期待しておりますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":52,"id":"exchange-021"},{"speaker":"田中委員","kind":"質問・要望","question":"下水道の関連の施設とかもあったりするので、こういうところは回遊性を求められないのでしょうけれども、例えば船着場とか、あるいは今お話があったライトアップの話とか、あるいは今後できる人道橋とか、こういったものをつなげることで面としてのまちづくりにつなげていく必要があると思うのですけれども、それは今後のまちづくりガイドラインではなくて、まちづくりの視点で出てくるということで。","respondent":"高梨都市計画課長","answer":"今回説明させていただいたポイントの中でも、やはり勝島運河を取り巻く、今ご紹介がありましたけれども人道橋やしながわ花海道の修景工事、それと浜川公園の再整備、また、東京都が行っている勝島運河周辺の各種事業等々を有機的につないでいく。","voiceIndex":54,"id":"exchange-022"},{"speaker":"田中委員","kind":"質問・要望","question":"場内の話なので、行政、品川区として、まちづくりビジョンも踏まえつつ、周辺のまちと競馬場との関係性はなかなかその関連性は見いだせないのかもしれないのですが、劇場のシアターＨができ、競馬場を取り巻く周辺の環境も変化があり、いわゆるまちづくりビジョンを具体的に進める中で、競馬場の皆さんとのまちづくりという視点での連携といいますか、意見交換。","respondent":"高梨都市計画課長","answer":"今年度の意見交換会もまさしく今、日程調整中で、やりましょうねというような話になっていますので、刻々と変化していくこのまちの状況の変化を捉えながら、東京都競馬、それと競馬行政、品川区としても、まちづくりビジョンも踏まえつつ、等も含めながら。","voiceIndex":56,"id":"exchange-023"},{"speaker":"田中委員","kind":"質問・要望","question":"ぜひ連携を深めていただいて、まちづくりに対する協力もいただきながら、また、共ににぎわいの創出につなげていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":58,"id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7149#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=22&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":24153,"voices":62}},{"id":"r07-20250828-10","meetingId":"r07-cm08","date":"2025年8月28日","dateIso":"2025-08-28","committee":"議会運営委員会","time":"午後 １時００分～午後 １時２８分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を9件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"令和８年度予算（議会費）","agenda":"令和８年度予算（議会費）","exchanges":[{"speaker":"安藤委員","kind":"提案","question":"事務局職員の拡充も併せて要望したいという副議長からの提案でしたけれど、そちらについては歓迎したいと思っているところです。昨年の質疑では、これ以上早くするのであれば予算を増やす必要があるという旨の答弁が事務局長からもあったところですので、皆様と議長・副議長におかれましては、ぜひ現状をご理解いただいて、予算化していただきたいなと重ねて要望したいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":11,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"確認","question":"ご説明ありがとうございました。会派に持って帰って説明しなければいけないので、もう一回確認したいのですが、先ほどの４つというのは、もう一回、各会派から出ているものというとどこに当たるのかというのをお示しいただきながら教えていただけると助かります。","respondent":"大澤区議会事務局長","answer":"裏面に行きまして、公明が、２番の定例会の開催通知チラシについてということで、増額。３番の区民と議会の交流会議の茶菓の購入費用。４番のオンラインについては、先ほどの説明と同様になります。共産は、９番の海外調査は予算計上しないというところです。","voiceIndex":13,"id":"exchange-002"},{"speaker":"あくつ委員","kind":"質問・要望","question":"様々会派からの要望を尊重していただいてありがとうございました。その議論の過程の中で伺いたいんですけれども、うちの会派から出している開催通知チラシのところの費用計上というのは、これ、そもそもふれあい掲示板等にというところでの増額ということを求めているのですが、これを含んでの内容ということでよろしいでしょうか。","respondent":"大澤区議会事務局長","answer":"議長から指示を受けまして、ふれあい掲示板に掲示分の増刷や配布の委託の経費等の要望はしていく予定です。","voiceIndex":15,"id":"exchange-003"}]},{"id":"topic-02","title":"広報会議からの報告事項","agenda":"広報会議からの報告事項","exchanges":[{"speaker":"せお委員","kind":"確認","question":"今年２月の議運で確認されておりますとおり、今年度は議会広報関連で区議会だより表紙等リニューアル、区議会定例会開催ポスター、区議会ホームページトップページ等リニューアルの３つの事業を行うこととなっており、これまで広報会議で検討を進めてまいりました。これら３つの項目について、ご報告します。デザインの決定を受けまして、現在本番移行に向け、動作確認作業を進めております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-004"},{"speaker":"安藤委員","kind":"質問・要望","question":"表紙のデザインなどは、私も個人的にはすばらしいのではないかなと思っていますが、インタビューページなど新たなページを検討すると伺っていますが、その際、全体のページ数は増やさないようにするということです。一般質問の部分を削ろうという話も出ているとちょっと伺いました。そちらはやめていただきたいなということをこの場をお借りしまして、ご意見として述べさせていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-005"},{"speaker":"あくつ委員","kind":"質問・要望","question":"女性が何かを持っている写真がばーんと表向きに出ていたから、これからは人物を載せるのかなと思ったのですが、先ほど、今後も公募写真を載せるとご説明があったと思いますが、そういうことでよかったのかどうかということと、これまでの公募の写真を使った表紙と比べて、どこがどう変わるのか、インパクトがあるのかというところを教えていただきたいというのが１点です。確認させてください。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":31,"id":"exchange-006"},{"speaker":"せお委員","kind":"意見","question":"表紙には引き続き公募写真を使っていくのですが、それは例えば開いてすぐのページに特集ページができたらなということを今検討していますが、その特集ページに関する写真を使っていきたいとは考えていますが、今のところまだ検討段階です。今、応募いただいている写真もたくさんありますし、まずはそちらを使っていく。写真に関しては、そちらも今後の検討かなという形にはなっています。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":32,"id":"exchange-007"},{"speaker":"せお委員","kind":"質問","question":"そうです。でも、今回の２定号の裏表紙に注意事項ではないですけれど、縦長にしてくださいということを書かせていただいています。先ほどの一般質問を削るといったところですが、ページ数はやはり増やせないので、もし特集ページを組んでいくのであればどこかしらをちょっと削るという検討はしていかないといけません。そこは皆さんと見て、意見を出し合いながら、今後検討していきたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":34,"id":"exchange-008"},{"speaker":"あくつ委員","kind":"質問","question":"それと、一般質問・代表質問に限らず全体を見直すということで、どこに何をするかというところです。どういう議論が今あるか私も詳細なところは分かりませんし、会派で検討したわけではありませんが、今、安藤委員の言いぶりを聞いていても、特に一般質問に触るというのは私もちょっと危険だなと。私はここがやはり区議会だよりの命だと思っているので、それはどうなのかなというところです。私の意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":35,"id":"exchange-009"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7151#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":8852,"voices":43}},{"id":"r07-20250917-10","meetingId":"r07-cm09","date":"2025年9月17日","dateIso":"2025-09-17","committee":"議会運営委員会","time":"午前１０時３０分～午前１１時３０分","status":"正式会議録","sourceType":"formal","overview":"議会運営委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を11件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"の常任・議運・特別委員会の構成","agenda":"の常任・議運・特別委員会の構成","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"以前、陳情が出されたこともあるのですが、今回、ドント方式だと思うのですが、未来が増えたということで１増と、維新が減ということになりましたけれども、私は、ドント方式は基本にすべきだと思うのですけれども、議会運営委員会ですので、やはり全ての会派から参加するということが第一優先であるべきだと思いますので、私たちとしましては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":26,"id":"exchange-001"},{"speaker":"松永委員","kind":"質問・要望","question":"今、特別委員会のところなのですが、木村議員が体調不良のため、私たちの会派のおぎの議員と交代させていただきたいと考えていますので、その辺のほどどうぞよろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":29,"id":"exchange-002"}]},{"id":"topic-02","title":"決算特別委員会","agenda":"決算特別委員会","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"すみません、(4)ですが、毎回要望させていただいて恐縮ですが、原稿提出ですけれども、１０月２０日というのは総括質疑の最終日だと思うのですが、その日のうちに提出となりますと、様々、その直前の質疑などを反映するのもなかなか大変だということもありますし、議会事務局の皆さんも夜中までかかってしまうということで、大変ご苦労もかけてしまうということもありまして。","respondent":"大澤区議会事務局長","answer":"区議会だよりのできるだけ早い発行を目指しておりますので、どうしても間に合わないということであれば、個別にご相談いただきたいと思います。","voiceIndex":58,"id":"exchange-003"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"安藤委員","kind":"質問・要望","question":"最後のところは、議員として現場に直接赴くということ自体は、必ずしも悪いことではないなと思うのですが、様々緊急対応というのはやはりまた違うところもありますので、最後、議長もおっしゃいましたように、様々これからどういうふうなルールづくりをしていくかとか、どういうふうに確認していくかというのは、よく議員の意見を聞いて、みんなで決めていっていただきたいなと思っているところです。","respondent":"渡辺議長","answer":"それに対してのやり方は、今日の今日ではなく、もう一度状況も踏まえたり皆さんの意見を聞いて、対応を議長として、あるいは議運の皆さんとも相談しながらという思いで発言をしました。","voiceIndex":76,"id":"exchange-004"},{"speaker":"あくつ委員","kind":"質問・要望","question":"我々区議、私どもの会派も７名、地元をその日も回りましたし、次の日も回りましたし、その次の日もまた回って現状を確認させていただいた中で、区の職員等が非常に現場で奮闘されている様子も拝見していて、正直、普通の感覚として、その中で本部に足を運ぶということが、私にはちょっと想像ができないというか、ごめんなさい、正直ベースで話しています。率直な気持ちとして申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":80,"id":"exchange-005"},{"speaker":"せお委員","kind":"意見","question":"私も今、あくつ委員がおっしゃったように本当に理解ができないですけれども、災害時の対応のところで、せっかく今、やなぎさわ議員ご本人がいらっしゃるので、状況が分からないところもありますし、Ｘに載せられていたので大体は分かるのですが、ぜひご本人に発言いただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":82,"id":"exchange-006"},{"speaker":"せお委員","kind":"質問","question":"ご発言、ありがとうあります。１点だけ気になったのが、今、ルールを失念していたというお話だったのですけれども、私が聞いている限りでは、事務局がこういうルールがありますよと言って止めたにもかかわらず、行かれたというお話を聞いているのですけれども、そちらに関してはどうなのですか。","respondent":"やなぎさわ議員、大澤区議会事務局長","answer":"申し訳ございません。そういったやり取りは、私はなかったと記憶しております。具体的にもしどの方がそういったことを指摘されたのかというのがあれば、教えていただきたいです。私が職員から報告を受けている範囲では、ルール云々という言葉は発言していないかもしれませんが、職員からは、本部は関係者のみであること、現場は混乱している状況が想定されるため。","voiceIndex":88,"id":"exchange-007"},{"speaker":"せお委員","kind":"意見","question":"そこで言った言わないとかは、ここでの問題ではないと思うので、今回に関してではないですが、私が把握している限りでは、ルール違反も何回かされていて、あと、私がリーダーである広報会議でも、そこは規定なのかマナーなのか分かりませんけれども、区議会だよりのところの要約などでも、少しマナー違反というか、そういったところが見られたこともありまして、本当に、今日は特に議長からも。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":93,"id":"exchange-008"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"こういうことも含めて、これはというのがあるのだとするならば、我々もうわさ程度の話であるのであれば、これをやはりきっかけとして、我々も、こういううわさがあるけど、こういうのはどうなっているのだとかというのは、しっかりそれはご本人にも確認をしていく機会を設けてもらわないと、何でもありということではないので、それは委員長にもお願いをして、ぜひ、今日で結論が出る話ではないと思うので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":95,"id":"exchange-009"},{"speaker":"松永委員","kind":"質問・要望","question":"私の知る限りは多分３回目ぐらいかなとは思うのですが、その中で、ぜひルールを守っていただいて、品川区議会議員であるので、そうした品格や品位を守っていただきたいと改めて思っています。意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-010"},{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ確認していいですか。今、災害対策本部へ行くというのを確かに言ったときに、その職員の方でも、ルールがあるわけですよ。行かないということになっているわけだから、ルールとしては、議員が個人で行かないというルールになっているわけですから、そのときに、個人で行くのならどうぞとか、何も言わなかったのか、そこは失念というのは、それは失念ではない。そこだけははっきりしてほしい。","respondent":"やなぎさわ議員、大澤区議会事務局長","answer":"なので、別に拒否もされないし、行くなら、では私がご案内しますという感じで、職員の方に付き添っていただいたというところですので、もしかしたら職員が行くというので、ルール上知っていても、職員の方は、行けないですと。それで、２３時半頃、本部の前に一緒に行って、職員が先に本部の職員に、やなぎさわ議員が話を聞きたいとおっしゃっていますが対応が可能ですかということの確認を取っていたところ、既に後ろにやなぎさわ議員がいらっしゃったので。","voiceIndex":107,"id":"exchange-011"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7159#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=10&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":20690,"voices":119}},{"id":"r07-20250919-4","meetingId":"r07-c-settlement","date":"2025年9月19日","dateIso":"2025-09-19","committee":"決算特別委員会","time":"午後 ２時１１分～午後 ２時１９分","status":"正式会議録","sourceType":"formal","overview":"決算特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を1件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"若林副委員長","kind":"質問","question":"委員長からご指名いただきました若林ひろきです。別にこだわっていませんけれども、いずれにしてもいい質問か悪い質問かは別に、皆さんのご判断ですので、理事者に分かりやすい、語尾も含めて、そういう質問でないと少しまた矢が飛ぶかもしれませんので、そこら辺はお互いに重々気をつけて円滑な委員会運営にご協力いただければと思いますので、よろしくお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":11,"id":"exchange-001"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7249#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=4&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":2139,"voices":16}},{"id":"r07-20250922-6","meetingId":"r07-cm09","date":"2025年9月22日","dateIso":"2025-09-22","committee":"区民委員会","time":"午前１０時００分～午前１１時１７分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を28件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議案審査に入らせていただきます。 (1)第１０４号議案、品川区印鑑条例の一部を改正する条例","agenda":"議案審査に入らせていただきます。 (1)第１０４号議案、品川区印鑑条例の一部を改正する条例","exchanges":[{"speaker":"こんの委員","kind":"確認","question":"施行期日なのですけれども、まず確認ですが、公布の日から施行するということですから、最終本会議でこれが議決されて、翌日からということか、施行期日というのはいつになるのかというのを、まず１点確認させていただいて、もう１点が、ご本人確認で、この手続を行うときに、資格確認書を使うという場面で関連してお聞きしたいのですけれども、ご本人が手続に来られない場合。","respondent":"築山戸籍住民課長","answer":"３点目のホームページでのアップデートですが、これは施行日に合わせてホームページにアップデートをする予定です。","voiceIndex":20,"id":"exchange-001"},{"speaker":"こんの委員","kind":"確認","question":"ありがとうございました。代理人のところだけ、もう一度お聞きしたいのですけれども、今、流れをご説明していただいて、ありがとうございました。要するに、委任状を持ってきて、代理人の方の本人確認も必要だと。そのときに、この確認は資格確認書でよろしいのですよねという確認だけでした。これで代理人の方の本人確認ができるのですかというところを確認をさせていただきたかったというところです。","respondent":"築山戸籍住民課長","answer":"代理人の本人確認についてですけれども、１枚で確認できる顔写真つきのものがあれば、それ１枚でいいのですけれども、資格確認書の場合は顔写真がありませんので、そうした場合、２種類の書類が必要になってきますので、資格確認書のほか、その他、例えば年金手帳だったり。","voiceIndex":22,"id":"exchange-002"},{"speaker":"こしば委員","kind":"確認","question":"確認したいのですけれども、今回、保険証の新規発行の停止に伴って、保険証自体はまだ１年間の経過措置がありますけれども、マイナンバーカードを持ってはいるのだけれども保険証にひもづけていない方もいらっしゃるかと思います。","respondent":"築山戸籍住民課長","answer":"マイナンバーカード自体は、現在７８％が今年６月末の保有率になっております。しかしながら、保険証とのひもづけをしていない方の割合については所管外になっておりまして、戸籍住民課では把握していないところです。","voiceIndex":25,"id":"exchange-003"},{"speaker":"こしば委員","kind":"質問・要望","question":"所管外ということで、確かにそうなのですけれども、できる限りは、所管外ではありつつ、横串を刺して、やはり数字も上昇といいますか、マイナンバーカードを持っている方に等しく健康保険証もひもづけていただけるような、それが結果的には医療行政の進歩にもつながってくると思いますので、その辺は柔軟に取り組んでいただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":27,"id":"exchange-004"}]},{"id":"topic-02","title":"第１０１号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","agenda":"第１０１号議案、令和７年度品川区一般会計補正予算（歳出 区民委員会所管分）","exchanges":[{"speaker":"おぎの委員","kind":"質問","question":"目的のところで、ここのところ、闇バイトが関係すると思われる強盗事件等が発生する中でということで、非常に治安の悪化を懸念してということだと思われますが、実際、今、品川区の区内では、そういった強盗事件等が起きているのかということが１点と、今回、集合住宅にまで拡充したということで、集合住宅ですので、マンションの管理組合等から申請が来るのかなとは思いますが、申請を受けた後。","respondent":"澤邉生活安全担当課長","answer":"もちろんこれまで色々問合せ等ございまして、こういうのが当たるのかということで、事前にご相談いただくこともありますし、そういったところについては丁寧に説明をしています。","voiceIndex":39,"id":"exchange-005"},{"speaker":"おぎの委員","kind":"質問・要望","question":"区内では、まだそういった大きな事件が発生していないということで、少し安心しました。都のほうで予算を出してくれていますので、こちらをしっかり活用して、区民の方の安全に努めていただけたらと思います。流れなども、個人が購入して申請ということで、思っていたのと違って、より使いやすい制度だなと考えています。ぜひこちらのほうは広く告知をしていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":41,"id":"exchange-006"},{"speaker":"こんの委員","kind":"質問","question":"住まいの防犯対策のほうですけれども、助成額が上限４万円ということで、対象設備が１２品目にまでなったということで、これは、何個かつけたいですと。フィルムもつけたいし、カバーもつけたいしというふうに何個かチョイスをして、４万円以上費用がかかっても、４万円まで補助してくださいますという、こういう理解でいいですかというのが１点です。その辺をお聞きしたいと思います。","respondent":"澤邉生活安全担当課長","answer":"そうした場合は、オンラインが基本ですけれども、窓口のほうに来所していただければ、出し方だとかシンプルなやり方、紙ベースでのやり方も我々のほうでご説明を申し上げますので、そこのところは一つ一つ確認しながらやっていただきまして。","voiceIndex":43,"id":"exchange-007"},{"speaker":"こんの委員","kind":"確認","question":"設置したものが何個かあって、４万円以上は、それはご自分ですよと。４万円までは補助しますけれども、それを超した部分は自費ですよといったところを確認しました。何かございましたら、お願いします。続けて、地域見守り活動のほうですけれども、まず、申請期間ですが、５月で終わってしまったというのは、これは理由をお聞きしたいと思います。","respondent":"澤邉生活安全担当課長","answer":"締切以降につきまして、問合わせですけれども、そういった都の制度の仕組みもあって、５月末で終わりにしますけれども、そういったところにつきましては、来年度も本事業の継続の検討をしておりますので、そういったところをご案内させていただいたり。","voiceIndex":45,"id":"exchange-008"},{"speaker":"こんの委員","kind":"質問・要望","question":"地域見守りのほうですけれども、５月末の理由が分かりました。そうしたときに、急遽、防犯カメラをつけたいですみたいなことが起きてきた場合は、ぜひ区の裁量で、そうしたことへの対応もしていただけるような考え方を持っていていただきたいというところですけれども、その点はいかがでしょうか。","respondent":"澤邉生活安全担当課長","answer":"急遽そういった事案が発生した場合につきましては、仮の話はあれですけれども、例えばですけれども、都の助成金を使用しないような形だとか、そういったところも含めて検討していければと思います。","voiceIndex":47,"id":"exchange-009"},{"speaker":"こんの委員","kind":"確認","question":"色々なことを想定して、どこまでしておくのかというのは、ちょっと考えるところもあるとは思いますけれども、うまくというか、町会・自治会の方々がご自分たちで防犯を強めていきたいといったところには、できる限りお応えができる、サポートができる、支援ができる体制というのはありがたいかなと思いますので、予算として、財政として予算の限りはあるわけですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":49,"id":"exchange-010"},{"speaker":"おぎの委員","kind":"質問","question":"今、区も色々こういった伴走的な支援をされている窓口をつくっているという、それで年間４,０００件ほどご相談があるということをお伺いいたしました。国がということですが、どうでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"例えば、法人につきましては法務局のほうに登記をしていただく、個人事業主の方につきましては税務署のほうに開業届を出していただくといったような形をとっておりまして、特に区のほうに何か品川区で事業をしますということで届出をするというものがないものですから。","voiceIndex":62,"id":"exchange-011"},{"speaker":"おぎの委員","kind":"意見","question":"そうしますと、事業者が出される開業届とかは国ですし納税とかは税務署なので、実際、どれだけの数の事業者が区内にいるという母数を把握するのが、まず区としては難しいということですね。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"大体の数につきましては、それこそ国勢調査ですとか経済センサス等で把握しているところですけれども、全体の実態というのは、正確なところが難しいといったところと、今回論点になっているインボイスに関しましては、免税事業者といって。","voiceIndex":64,"id":"exchange-012"},{"speaker":"おぎの委員","kind":"質問・要望","question":"そういった現状把握が難しい中だとは思うのですけれども、やはり一番身近に寄り添う小回りがきくのは地方自治体ですので、できるだけそういった現状に寄り添っていただきたいとは思うのです。特に２割特例が、令和８年９月に切れますので、それまでに区としてできることなどを考えていただきたいと思うのですが、そういったことはいかがでしょうか。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"そういったことを踏まえて、国が今回やっている調査も踏まえて、国のほうで、２割特例の終了に当たって、どのような動きをしていくのかということも併せてきちんと国の動きも見ながら、そして、日々の相談の中で、特例が終わるに近づけて、多分。","voiceIndex":66,"id":"exchange-013"},{"speaker":"おぎの委員","kind":"質問・要望","question":"難しい中だとは思いますが、なるべく区としてできるようなことは考えていただきたいと思います。区のホームページやメルマガ、広報紙など、色々なツールを使って広報をされているとは思うのですが、それでも届いてない方とかに模索していただきたいというのと、区の商連などがあると思うのですが、そういったものに入るメリットというのはあるのか。一緒にお願いします。","respondent":"小林地域産業振興課長","answer":"我々としても、個別の商店街と区との関係ということでいきますと、もちろん１対１の関係もありますけれども、商連に入っていただくことを通じまして、区の取組ですとか区の助成金、あるいは東京都の制度なども一緒にメリットをご説明するような形にしております。","voiceIndex":68,"id":"exchange-014"},{"speaker":"おぎの委員","kind":"質問","question":"商店街とか、区とつながる商連とかもあった、メリットを今聞かせていただいたのですが、実店舗を持っていないフリーランスの方とかも入れるのでしょうか。","respondent":"小林地域産業振興課長","answer":"商店街については、例えばですけれども、エリアに、その周りに例えば商店街という形で複数の店舗がない場合でも商連に入っていただくとか、あるいはプレミアム付商品券の事業に私も参加したいと、例えば１人だけ、この店舗だけなのですけれどもとか。","voiceIndex":70,"id":"exchange-015"},{"speaker":"高橋（伸）委員","kind":"質問","question":"まさにおっしゃるとおりなのだけど、すごくこれは難しいと思うのです。もう１点、実態調査で、先ほど課長が、今、国が再調査をやっていますというお話がありましたけれども、その結果はいつ頃出るのですか。その１点だけ教えてください。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"ただ、調査の締切を見ますと、８月１日までとなっていたので、今、集計されて、秋冬ぐらいには公表されるのではないかと見込んでいるところです。","voiceIndex":75,"id":"exchange-016"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"分かりました。では、それは分かり次第、またお知らせをしていただいて、フリーランスの方にも手厚く知っていただくというのも今後進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":77,"id":"exchange-017"},{"speaker":"こんの委員","kind":"質問","question":"今の高橋伸明委員に少し関連する内容というか、少し重なる部分もあるのですけれども、まず、プッシュ型のほうの話ですけれども、プッシュ型ということは、個々につながってないと、なかなかプッシュって難しいかなと想像するのですけれども、その辺、プッシュ型となると、現実どういうふうに考えられるのでしょうかというところが１点。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"それで中小企業センターの相談窓口ですとか、創業支援施設にまずはお越しいただく。それから、冬からは、今年度はウェブ相談も実施する予定ですので、まずは区役所に来庁されなくても気軽にご相談できるという、そういった仕組みを整えているところです。","voiceIndex":79,"id":"exchange-018"},{"speaker":"こんの委員","kind":"意見","question":"それがないことにはプッシュもできないと思うので、そこら辺のところのご努力を引き続きお願いしたいと感じました。もう１点の実態調査のほうは、国での調査という、調査項目を今ご説明いただきましたけれども、この調査で、ある程度というか、免税事業者、フリーランス、個人事業主の実態調査の中身で見えてくるものというのはとても参考になるのだろうと、今聞いていて思いました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":81,"id":"exchange-019"},{"speaker":"こしば委員","kind":"質問・要望","question":"そうは言っても、実際、免税事業者の方が取引先から排除されるとか、そういった声も実際に聞いているところもありまして、そういった取引の排除だとか不公正な取引があった場合への対応、国だと思いますけれども、どういったものがあるのかというのを教えていただきたいと思います。","respondent":"栗原創業・スタートアップ支援担当課長","answer":"国のほうでは、下請法などがありますので、そういったところをご相談いただきましたら、例えば国のほうで、発注者側のほうに対応を是正するですとか、罰則をするですとか、例えば立ち入り検査をするとか、そういった権限は国のほうが持っておりますので。","voiceIndex":83,"id":"exchange-020"},{"speaker":"おぎの委員","kind":"質問・要望","question":"ですが、事務作業軽減のＤＸ導入助成金とか、まだ使える助成金があるのに、制度を知らないまま困っている事業者には、やはり何とかつながって届けてあげていただきたいですし、２割特例の適用期間が切れる令和８年９月までには、もしそのときにインボイス制度が廃止になっていなければ、区として何らかの救済策を考えていただきたいと強くお願いいたします。よろしくお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":89,"id":"exchange-021"},{"speaker":"こんの委員","kind":"質問","question":"本日結論を出すでお願いします。先ほども質問させていただきました。区としては色々な媒体で、色々とつながる努力をされている最中だということですので、それがないことにはプッシュもまだ行かないのだろうなというところで不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":90,"id":"exchange-022"},{"speaker":"せらく委員","kind":"質問・要望","question":"本日結論を出すでお願いします。今回、プッシュ型支援の導入を求めるということなのですけれども、困っている人がちゃんと利用できるような状況になっているかとか、必要な人に知られているかなど、問合せの際の情報提供だとか、必要な情報にたどり着けるような工夫というのは、引き続きお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":91,"id":"exchange-023"},{"speaker":"こしば委員","kind":"質問","question":"理由としましては、先ほども触れましたけれども、本来であれば、このインボイス制度というよりは、経営難に陥っているフリーランスの方を含めた、そういった方々への支援策、実際にもう区のほうでもされて、また国のほうでもあるということですので、そこに着目をすべきではないのかなと。今の現状だと、区のほうで実態調査をするには詳細な情報をとることが難しいということですので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":96,"id":"exchange-024"},{"speaker":"おぎの委員","kind":"質問・要望","question":"本日結論を出すでお願いします。先日の９月１１日の豪雨が明けて区内を回ったときに、長年区内で飲食業を営んでいた事業者の方からも、水害は今回だけだから頑張って片づけるけれども、何とかするけど、もうインボイスは、あれだけは何とかしてくれという声を、やっぱり幾つか聞いたのです。特定の業種に偏った結果も出る事態も考えられますということで、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":97,"id":"exchange-025"},{"speaker":"こんの委員","kind":"意見","question":"本日結論を出すでお願いいたします。そこで、なかなか区として把握がしきれない事業者へ、国が今、再度やっていることも１つ参考になるものでありますので、まずはその結果を見ながら、引き続きフリーランスの方や個人事業主の方に寄り添っていただきながら、あらゆるご相談にまたつながる努力をお願いをされていますので、引き続きお願いしたいということで、本請願については不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":98,"id":"exchange-026"},{"speaker":"せらく委員","kind":"意見","question":"本日結論を出すでお願いいたします。この制度については、所属政党の考えなどで反対するものではないのですけれども、やはりこれだけ叫ばれている中、区として区内の事業者の思いだったり実態を把握してもらいたいと思っています。国での調査の結果を待ちながらということではありますが、区での独自実態調査も反対するものではないというふうに考えまして、採択にしたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-027"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"藤原副委員長","kind":"質問・要望","question":"明日でなくても、今日、要望だけしたいのですけど、せらく議員の質問の中で、五反田の件が出ましたよね。だけど、私の個人的な考えかもしれないのですけれども、民間の人が客引きの方に、「それはいけないんじゃないですか」とか言うのって、すごく恐怖心があると思うのです。それで、課長、これは要望なのですけれども、やはり条例がある以上は条例を守ってもらわないと困るじゃないですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":105,"id":"exchange-028"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7165#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":23147,"voices":107}},{"id":"r07-20250922-7","meetingId":"r07-cm09","date":"2025年9月22日","dateIso":"2025-09-22","committee":"厚生委員会","time":"午前１０時００分～午後 ６時００分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を141件抜き出しています。","hasFullText":true,"topics":[{"id":"topic-01","title":"議題に入ります前に、進行","agenda":"議題に入ります前に、進行","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"ご説明ありがとうございました。そのほかの議案、今回は８件ということで共通しているのだと思うのですけれども、選考基準の評価項目・配点のところを確認したいのですけれども、１００点満点の基準で、最後に別添で評価項目と配点というのがあるのですけれども、それが、選考委員が４名いらっしゃるから、掛ける４００点満点ということでいいのかどうかということ。以上、３点です。","respondent":"菅野高齢者福祉課長","answer":"３点ご質問を頂きましたので、順番にお答えします。評価の点のところですが、委員ご指摘のとおり、１人１００点満点で、評価項目はそれぞれ配点させていただいて、つけさせてもらっております。審査員が４人いますので、４００点満点ということになります。","voiceIndex":5,"id":"exchange-001"},{"speaker":"あくつ委員","kind":"提案","question":"先程１者というか、１つの団体が手を挙げたとおっしゃっていたので、そういうところもありますが、そういう中で１つしか選ばざるを得ないという環境もあるということもあるとは思うし、私も別に異論はないのですけれども、各施設、一生懸命やっていただいていて、恐らくそんなに区民からの不満というものは私のところには上がってきていないので、高評価なのだとは思うのですけれども。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":7,"id":"exchange-002"},{"speaker":"鈴木委員","kind":"提案","question":"全てこれまでの事業者で、その枠で長い間受託していただいている一定大きな社会福祉法人というところに、また引き続いてやっていただくということでの提案になっていると思うのですけれども、これまでの事業者しか応募がないということに対しては、制度の趣旨からして、区としてはどう捉えているのか、改善が必要ということで考えられているのか、その点を１点伺いたいと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":9,"id":"exchange-003"},{"speaker":"鈴木委員","kind":"提案","question":"１０人という小規模であるにもかかわらず１,０００万円を超える赤字という状況で、報告書の中でも財務状況というのがここに出ていまして、４０点満点のところ、２６点ですか。そういう低い財務状況になっているのですけれども、ここはどう考えられて、改善というのはどういうふうに対策が提案されているのか、その点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"公募の期間はおおむね２週間程度を設けさせていただいて、周知しています。その結果、説明会には、１事業者以外にも参加された事業者もいたのですけれども、最終的には、現に指定管理をしている事業者のみが応募したという結果となっているというところです。","voiceIndex":13,"id":"exchange-004"},{"speaker":"鈴木委員","kind":"質問","question":"訪問介護のステーションと、何というのですか、倒産件数なども、訪問介護のヘルパーステーションに次いで、デイサービスの倒産件数が多くて、そういうところで経営が厳しい状況というのもあると思うのですけれども、報酬の部分というのに問題があるのではないかと私は思いますし、また総合事業で、デイサービスと訪問介護が、要支援が総合事業ということで。","respondent":"菅野高齢者福祉課長","answer":"１事業者のみの提案というところと、あとデイサービスの赤字が多いという構造上の体質というのですか、そういった部分についてのご指摘だとは思います。確かに国の福祉医療機構の調査等も見しますと、デイサービスの４割が赤字だというような結果も出ているとは捉えております。","voiceIndex":15,"id":"exchange-005"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に構造的な大本は、国の介護報酬の引き下げというところが大本の憂いになっているとは思うのですけれども、そういうところも含めて、私は区から、こういう実態ということも、課長会や全国の市長会など、いろいろあると思いますので、ぜひ声を上げていただいて、成り立つ事業というところにも声を上げていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":17,"id":"exchange-006"},{"speaker":"吉田委員","kind":"質問","question":"評価の中に、財務についての評価は当然入っているのですけれども、生活者ネットワークとしてはずっとこういうところに、働く人への、労務管理と言ってしまっていいのか、働く人への管理になりますか、働く方への方針というか、働く方たちがこのような形で働きやすい体制を取っているという評価点が、そもそも入っていないように思ったのですけれども。","respondent":"菅野高齢者福祉課長","answer":"実際に働いている方の労務管理につきましては、指定管理者の制度の中で労務環境調査というのを、指定管理者３年目に実施していますので、その中の資料等も見ますと、現指定管理者においては良好な労務環境であるという評価は出ておりますので。","voiceIndex":19,"id":"exchange-007"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。ちゃんと労務管理もきちんとされているし、報酬についても適正であるという、どうしてもそれは財務状況と関連しますけれども、そのような視点での評価を私はしたいと思いますし、それは今後されるべきではないかと思いますので、その点についての資料の作り方等も、ぜひ今後は工夫していただきたいと思います。もし何か見解があったら伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"その辺りは今後、研究してまいりたいと思っているところです。","voiceIndex":21,"id":"exchange-008"},{"speaker":"やなぎさわ委員","kind":"質問","question":"先ほども議論があって、ほかの委員の方もおっしゃっていましたけれども、やはり通所介護事業所というのは４割近くが赤字ということで、手を挙げる法人も少ないのかなと思いますので、その辺は本当に課題だと改めて感じております。今回の指定管理の選定の中で、処遇改善加算の取得に関して評価というか、基準として入っているのかどうか、お伺いしたいのですが、いかがでしょうか。","respondent":"菅野高齢者福祉課長","answer":"処遇改善加算につきましては、具体的には加算を取られていますかというような、そこの部分についての確認等はしてはいないのですけれども、その辺りは、離職率などといったところの全体的なバランスを見ながら、評価をさせていただいているというところになります。","voiceIndex":24,"id":"exchange-009"},{"speaker":"やなぎさわ委員","kind":"確認","question":"やはり当然、品川区としても恐らく、処遇改善加算Ｉを取るような取組というか、されていらっしゃったかなと思いますし、要は職員の報酬というか、お給料を上げるためにも、やはりそれは大前提になってくると思いますし、民間の普通にやっているデイサービスではなくて、こういう指定を受けてやっているところであれば、その辺はより厳格にするべきだと思いますので、ぜひそういった指定に関して。","respondent":"菅野高齢者福祉課長","answer":"区内法人でもありますので、ご指摘の所得改善加算については、今後積極的に取っていただくような働きかけ等をしてまいりたいとは思っております。","voiceIndex":26,"id":"exchange-010"},{"speaker":"やなぎさわ委員","kind":"確認","question":"開設したときから変わっていないみたいなところもあって、正直、そんなに多くの人が福ナビの情報を見ているとは思わないけれども、そういったこともあって更新していない事業所というのは、全ての事業を含めてあるのですけれども、指定を受けているというところになると、それなりのやはり体制はしっかり整えていかないと、区としても指定を与えているわけですから。","respondent":"菅野高齢者福祉課長","answer":"福ナビの部分につきましては、私も確認等はさせていただきたいと思っているところですが、これも東京都でやっているプラットフォームというか、そういった形でいろいろご覧になられる方もいらっしゃるのかなというところで、事業者には、ぜひ活用してくださいというところで。","voiceIndex":28,"id":"exchange-011"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そうですね。数は多くないとはいえ、やはり自分の地域でどういったデイサービスがあるのかなど、福祉資源を探すときに、検索して出てくるところだと思うので、これは非常に利用者が利用につながる入り口になると思うので、この辺は、東京都でやっているものではありますけれども、区としてもしっかり、指定を与えている事業所に関しては注意して見ていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":30,"id":"exchange-012"},{"speaker":"鈴木委員","kind":"確認","question":"赤字の状況で、やはりこれも令和６年度は１,４００万円からの赤字という状況になっているのですけれども、その辺のところが、報告書の中でも、品川区全体なのかもしれないのですけれども、財務評価というところが、過半数の拠点が赤字となっていて、直近の事業活動収益が黒字から赤字状態になっていて、継続的な資金の取崩しが確認されるなど、財務状態の悪化に対する注意が必要であるということで。","respondent":"菅野高齢者福祉課長","answer":"理由は様々だと思うのですが、今、ニーズの調査もして、転倒予防のためのプログラムというところで新しい試みをしているというところなので、その良さをもっと分かってもらうために、パンフレット等を刷新して、関係機関、在宅介護支援センターや居宅介護支援事業所等に周知して。","voiceIndex":49,"id":"exchange-013"},{"speaker":"鈴木委員","kind":"質問","question":"これは継続という、公募によらないというあれですけれども、これもまた三徳会が引き続いての指定管理者になるわけですけれども、三徳会は結構いつも人材確保が課題というのが毎回出てきていると思うのですけれども、選定理由のところに、「単発ワークシェアリングなどの人材確保に一定の成果があり着実な運営を見込むことができる」ということが書かれていましたので。","respondent":"菅野高齢者福祉課長","answer":"ただ、そういった派遣や、あとは単発のワークシェアリングに頼るというところは、永続的には決していいものではないかなとは捉えておりますので、少しでも採用の努力をしていただいてというところで、その辺の工夫も、おそらく、明後日のモニタリングでもお話ししますが。","voiceIndex":68,"id":"exchange-014"},{"speaker":"鈴木委員","kind":"質問","question":"ここで、先ほどの慢性的な人手不足にという指摘には、「財政状態は良好だが」と書かれているのですけれども、ここの施設別評価というところで、４００点満点で何点というのは書かれているのですけれども、前のところで、どこかでは、財務状況というのが４０点満点のうち何点みたいなのが書かれているところもあったのですけれども、平塚橋特別養護老人ホームなどの財務状況。","respondent":"菅野高齢者福祉課長","answer":"その中の文言等、こちらの報告書の「財務評価について」というところで表現させていただいているという次第になっておりますので、こちらについて「財政状態は良好だが」という評価を一定程度、頂いているというところではあります。","voiceIndex":70,"id":"exchange-015"},{"speaker":"鈴木委員","kind":"確認","question":"ほかのところの指標では４０点満点のうち何点みたいなのが出ていたのですけれども、点数はつけてはいないけれども財務状況は良好だという評価だというところで、点数はつけていないということなのか、その点の確認だけお願いします。","respondent":"菅野高齢者福祉課長","answer":"こちらの報告書の点数が２６点というところのお話だと思うのですけれども、「収支計画に具体性、実現性があるか」という、財務評価のところのお話ですか。","voiceIndex":72,"id":"exchange-016"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ほかのどこだったか。今までの議案の中には財務評価というのが出てきていた、４０点満点のうち何点というのが出てきていた議案があったのですけれども、平塚橋特別養護老人ホームでは財務評価何点などというのは書かれていなかったので、もしもつけているのであればお聞かせいただきたいということです。","respondent":"菅野高齢者福祉課長","answer":"大変失礼いたしました。６ページの、「公の施設の管理を安定して行う物的能力および人的能力を有しているものであること」の項目の中に、「福祉サービスを安定的に提供できる経営基盤を有しているか」との部分があります。","voiceIndex":74,"id":"exchange-017"},{"speaker":"鈴木委員","kind":"質問・要望","question":"その点数が分かるようであれば、何点だったのかというのを教えていただきたいということで聞いていました。","respondent":"菅野高齢者福祉課長","answer":"今回の報告書の中では、あくまでも指定管理者の指定の結果報告書についての報告様式等は、区の中での統一した報告様式となっておりますので、その中で点数は総合得点で示すこととなっておりますので、項目ごとについては差し控えします。","voiceIndex":76,"id":"exchange-018"},{"speaker":"吉田委員","kind":"質問・要望","question":"すみません。この辺のワークシェアリングの活用というのを、もう少し詳しく教えていただきたい。なぜなら、もしいい制度であるならば、本来あるべき姿ではないかもしれないけれども、本当に人手不足の解消ということになるのであれば、もう少し制度としてきちんとしていくということも考えられるのかなと思って伺うので、ぜひ教えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"ただ、その中には手数料が取られたり、あとは単発だったりするので、すごくいい方が来る場合もあれば、そうではない場合もあったり、いろいろと不確かなところもありますので、区としては、法人にその中で工夫していただくのには、とてもいいとは思っているのですけれども。","voiceIndex":79,"id":"exchange-019"},{"speaker":"吉田委員","kind":"質問","question":"分かりました。おっしゃる趣旨はとてもよく分かります。よく分かりました。それで、財務評価のところにある「慢性的な人手不足に伴う派遣職員比率の増加」というのは、そういう制度を使うことが結局、財政上の圧迫につながっているという理解でよろしいでしょうか。","respondent":"菅野高齢者福祉課長","answer":"委員がおっしゃるとおりです。やはり派遣職員等の比率が上がると、どうしても手数料等が取られるなどといった、本来の常勤職員として雇うのとはまた別の部分の費用がかかるので、どうしても費用が、そこの部分でかさんでくるとは捉えています。","voiceIndex":81,"id":"exchange-020"},{"speaker":"鈴木委員","kind":"提案","question":"先ほどの財務状況評価についてなのですけれども、小山在宅サービスセンターのほうは、提案内容評価と財務状況評価というのに分かれていて、同じくこれは三徳会なのですけれども、そこのところでの選考基準に基づく採点での財務状況評価が、４０点満点で２６点とかなり低い状況になっているのですけれども、これは、在宅サービスセンターの財務状況評価ということなのか、三徳会全体のということなのか。","respondent":"菅野高齢者福祉課長","answer":"ご指摘の、先ほどご説明させていただいた小山在宅サービスセンターにつきましての採点結果のところです。","voiceIndex":84,"id":"exchange-021"},{"speaker":"鈴木委員","kind":"質問","question":"ということは、財務状況評価というのは、単独のサービスに対しての財務状況というよりは、法人に対しての財務状況評価というところで捉えていいのか、その点も伺います。","respondent":"菅野高齢者福祉課長","answer":"今、訂正を一部させていただきたいのですが、財務状況評価というのは法人ごとにさせていただいているのですけれども、今回の財務状況評価というのは、経営分析は法人ごとなのですが、そこに、施設ごとに収支の状況や。","voiceIndex":86,"id":"exchange-022"},{"speaker":"鈴木委員","kind":"確認","question":"ということは、きちんと黒字でやっていけますというところであれば、財務状況評価というのも高くなるし、法人全体としては大変であっても、サービスごとに財務状況評価というのは評価されて点数になるということでいいのかの確認だけお願いします。","respondent":"菅野高齢者福祉課長","answer":"もちろん財務状況がサービスの提供には大きく影響はすると思うのですが、中には、例えば施設長に、しっかりとサービスの提供についていろいろと思いを語っていただく、計画的なものを示していただくなど、お話を聞くことによって。","voiceIndex":88,"id":"exchange-023"},{"speaker":"やなぎさわ委員","kind":"確認","question":"というところで、これは意見なのですけれども。それで次です。今回の評価の中で、第三者評価のアンケートを、アンケート結果を参考にされているかどうかをお伺いしたいのですけれども、いわゆる３年に１回行っている第三者評価なのですけれども、そういったところを、今回、私は平塚橋特別養護老人ホームの直近の令和４年度を確認したのですけれども、そういったところは評価基準に入っていますでしょうか。","respondent":"菅野高齢者福祉課長","answer":"その中での利用者に対するアンケート結果等も、こちらは今回の、もちろん既存の現行の指定管理事業者にお願いするということになりますので、当然、そちらの辺りのアンケート結果等も加味しながら、今回は継続をお願いするという結果に至りました。","voiceIndex":91,"id":"exchange-024"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"すみません。個別の計画作成時に、利用者や家族の状況や要望を聞かれているかという質問に、「はい」が１０％、「いいえ」が９０％。「はい」が１０％、「いいえ」が９０％。これは、「いいえ」が１００％なのです。入所者の方に対するアンケート結果ですけれども。この辺は今回の評価に関わっているのかなという質問ではあったのですけれども、改めて、アンケート結果の存在を含めて確認させてください。","respondent":"菅野高齢者福祉課長","answer":"ちなみに、指定管理の制度の中で、５年間のうちの１回、利用者調査というのを区でも行っておりまして、そちらについては回答者が５４名というところで、要望、相談、苦情などを気軽に職員に話せるような雰囲気がありますかというところでは、「大いに満足」１５％。","voiceIndex":93,"id":"exchange-025"},{"speaker":"やなぎさわ委員","kind":"質問","question":"ちなみに、その調査の方式というか、対面なのか記述なのか、その辺を伺います。","respondent":"菅野高齢者福祉課長","answer":"こちらについては、指定管理者制度の中で実施していますが、対面なのか書面なのかというのは確認させていただきたいところではありますが、実際に施設で一定、ヒアリング等もしているとは聞いておりますので、確認事項はありますが、一定の信頼度はある評価だとは捉えております。","voiceIndex":95,"id":"exchange-026"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"施設が行っている調査として、あり得ると思うのですけれども、やはり様々な調査結果を踏まえて、それこそ苦情の窓口相談の案内が誰もされていませんという、１０人中１０人されていないとか、計画の説明が９割の方がされていないということに関しては、どうしてそうなっているのかというのは、やはり区が指定を出すというところに関して、それこそ事業所から聞き取ってみるなどといった。","respondent":"菅野高齢者福祉課長","answer":"今回、公募によらずで、こちらの平塚橋特別養護老人ホームを同じく三徳会にお願いするというふうに至った、まず理由としまして、これまでの実績もありますし、利用者と施設の顔なじみの関係もある、利用者や家族のニーズを丁寧にくみ取り、食事や面会。","voiceIndex":97,"id":"exchange-027"},{"speaker":"やなぎさわ委員","kind":"意見","question":"分かりました。私の見た第三者評価は、もし評価どおりであれば、かなり候補者選定の理由にいろいろ述べられているところと乖離してしまうのかなと思いますので、ぜひ注視していただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":99,"id":"exchange-028"}]},{"id":"topic-02","title":"第１０１号議案、令和７年度品川区一般会計補正予算（歳出等 厚生委員会所管分）","agenda":"第１０１号議案、令和７年度品川区一般会計補正予算（歳出等 厚生委員会所管分）","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"行きたい方が行けなくなってしまったというご説明があるのですけれども、一応、念のため確認しますが、現在の区内の放課後等デイサービスの事業所が幾つあって、今後この１１月からですか、先ほど周知というか募集を始めるというお話がありましたけれども、品川区内で新規開設したいという見込み数というか、こういうインセンティブを出すことによって見込み数というものがあるのかどうかというところが１つ。","respondent":"東野福祉計画課長、佐藤障害者施策推進課長、松山障害者支援課長","answer":"すみません。相手の名前は記載がございませんでした。こちらにつきましては、周知の事実だというところで認識しておりましたので、記載しなかったものです。今後の見込みですが、今回、補正予算では３か所分の開設助成の費用を見込んでいるところではございまして。１８事業所にご対応いただいております。そして、新たな予算計上で、新規分として３事業所、計２１事業所を見込んでおります。","voiceIndex":119,"id":"exchange-029"},{"speaker":"あくつ委員","kind":"質問・要望","question":"すみません。それと、放課後等デイサービスについては、もうこれは各障害者の団体からたくさんご要望も頂いておりましたし、１つ、区の施策が、いい意味での、うれしい悲鳴ではないですけれども、やはり足りなくなってしまうという、うれしい悲鳴というか、サービスが利用できないというところでのお声を反映しての、すごく時宜を得た施策だと考えています。滞りなく進めていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":123,"id":"exchange-030"},{"speaker":"吉田委員","kind":"確認","question":"それで、調べたところによると、多分、２０２２年の改正建築物省エネ法で、２０２５年４月からは原則全ての建築物省エネ基準への適合が義務づけられたという、これでいいのか、これに基づいたものかという確認が１個。それと、この八潮の件の議案が提出されたのが２０２４年９月１９日なのです。それで、何で今、この補正に出てくるのかという確認をさせて……。","respondent":"東野福祉計画課長","answer":"申し訳ございません。詳細については分かりかねるところです。委員からご指摘いただいた法が当てはまるのかどうかというところにつきましては、現在、答えを持ち合わせておりません。詳細につきまして改めて確認した上で、委員会に追加で報告できればと思います。","voiceIndex":125,"id":"exchange-031"},{"speaker":"吉田委員","kind":"質問・要望","question":"放課後等デイサービスのことなのですけれども、これも、放課後等デイサービスの数が足りないということは、いろいろご意見も頂いておりますし、それと同時に質の確保というのもすごく重要になってくるかと思うのですけれども、１点質問で、私の理解が間違っていると困るので伺いますが、この第１０１号議案の説明の中の一番下の、臨海青海特別支援学校への送迎対応を行う事業所への車両リース料というのは。","respondent":"松山障害者支援課長","answer":"今後も臨海青海特別支援学校へ行く生徒が増えていく見込みがあることから、今回助成に踏み切ったものですので、吉田委員のおっしゃる、おそらく令和１１年度予定の建て替えに伴うということは、また今後の検討になるかと思われます。","voiceIndex":127,"id":"exchange-032"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。確かにこれは補正ですから、そういうことであれば、しっかり当初予算からつけなくてはいけないものだと思います。ただ、やはり現実、建て替えに伴う移動の結果、放課後等デイサービスはどうなるのかというのは、やはり皆さん、もう最初の建て替えの計画があったときから心配されるのは当然だと思うのです。最後は要望にとどめておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":129,"id":"exchange-033"},{"speaker":"鈴木委員","kind":"質問・要望","question":"東京都からの補助金でいろいろと創設する場合、増床型改修、いろいろあるのですけれども、これのところで、１床当たり幾らということで出る、どれに当たるのかというのを教えていただきたいのと、品川区は整備率が低いので、最も促進係数が高いというところになっていて、１.８倍出るということで、品川区はなっているのですけれども。","respondent":"東野福祉計画課長","answer":"すみません。補助金の総額が、こちらも全体がどの程度かというところは金額にもよってきますので、まだ総体的なところは決まっておりません。一定程度の工事費に伴ってというところで申請はしています。今言った１.８倍というところにつきましては、適用の予定となっております。","voiceIndex":131,"id":"exchange-034"},{"speaker":"鈴木委員","kind":"質問","question":"東京都の補助金の額を見ると、１床当たり幾らみたいな形になっているのですけれども、それ以外のところでもまた補助金が出るということで、何ベッドというのはもう決まっていると思うのですけれども、それでは計算できない何かがあるということなのか、その点を伺いたいと思います。その点についても伺いたいと思います。","respondent":"東野福祉計画課長、佐藤障害者施策推進課長","answer":"八潮南特別養護老人ホームにつきましては、特別養護老人ホームの関係等の補助、それからグループホームの関係の補助も入る予定となっております。放課後等デイサービスの関係の助成で幾つか質問を頂いたところで、まず必要量等の見込みというようなところですが、委員がおっしゃるとおり、先日ご報告しました昨年度のサービスの利用実績等につきましても。","voiceIndex":133,"id":"exchange-035"},{"speaker":"鈴木委員","kind":"質問・要望","question":"今回は中重度の方の受入れというところが、なかなかされないのだというのは、私たちも懇談のときに団体の皆さんからご要望いただいているところなのですけれども、愛の手帳１度～３度で、希望しても通所できないという方がどれぐらいいるかというのは、区として把握されているのかということと、それから、現状で送迎している放課後等デイサービスというのは何か所ぐらいあるのか、その点も教えてください。","respondent":"松山障害者支援課長","answer":"中重度に関わるご質問にお答えします。愛の手帳１度～３度、愛の手帳を所持している中で放課後等デイサービスが利用できない方は何割ぐらいというご質問ですけれども、大体１割ぐらいの方です。","voiceIndex":136,"id":"exchange-036"},{"speaker":"鈴木委員","kind":"意見","question":"中重度受入れの加算なのですけれども、裏のページで、加算を総額で出されているのですけれども、愛の手帳１・２度所持者への加算や３度の加算というのが、具体的にどれぐらいの加算になるのか、その点についてもお聞かせください。","respondent":"松山障害者支援課長","answer":"時間単価×時間×人数、そして１月の日数×月数という式により算出しています。","voiceIndex":138,"id":"exchange-037"},{"speaker":"鈴木委員","kind":"質問","question":"その促進助成というのは、期間は限定なく、ずっと出るということで考えていいのかということと、それからあとドライバーなのですけれども、人件費のドライバーというのは、１台当たり１か月１８万円出るということなのですけれども、これは運転専門のスタッフを雇うという場合のみが対象ということになるのか、その点について伺いたいと思います。","respondent":"松山障害者支援課長","answer":"それからもう一つは、ドライバー確保の人件費につきましては、特にドライバー専属でなくても、職員１名の方がどうしてもドライバーとして運転業務に関わらなければならないというような負担を考えまして、こちらの対象とするものです。","voiceIndex":140,"id":"exchange-038"},{"speaker":"鈴木委員","kind":"確認","question":"それから不妊治療のことなのですけれども、不妊治療で１,１４０件まで増やすということで、それはこれだけ需要があるということで、本当に必要なことだと思うのですけれども、対象者のところの、他の自治体から生殖補助医療に係る医療費助成を受けていない、または受ける予定がない方ということなのですけれども、これは東京都も、この助成はしていると思うのですけれども。","respondent":"勝亦健康課長","answer":"東京都で先進医療の助成等は行っておりまして、こちらは、保険適用外の先進医療の補助だと認識しています。今、区で適用しておりますのは保険適用されている部分ですけれども、それに助成を出すものということで、助成の対象は重複していない形になります。","voiceIndex":142,"id":"exchange-039"},{"speaker":"吉田委員","kind":"質問・要望","question":"先ほどから放課後等デイサービスの質の確保というところで、ほかの委員からもご意見が出ましたけれども、質の確保を具体的にどうやっているかというのも確認するのを忘れまして、例えば定期的に事業所に行って視察に入るとか、そういうことをやっていただきたいという方向で聞いているのですけれども、その点についてはどのような施策を取られているか、お伺いしたいと思います。","respondent":"佐藤障害者施策推進課長","answer":"この件に関しましてはというか、障害者福祉サービス全般に、適正な運営がされているかというところの確認で、指導検査ということで、区の職員等が事業者訪問も含めまして、職員体制や運営状況などの確認を行っているという意味では。","voiceIndex":146,"id":"exchange-040"},{"speaker":"吉田委員","kind":"質問・要望","question":"３年に１回かと、少し思ったのですけれども、やはり本当に質を確保するとなると、もう少し現場を見て、やはりお金を出す以上、変な言い方ですけれども、その辺はぜひ回数を、なるべく丁寧な点検をしていただきながら育成を図るということを目指していただきたいと思います。これは要望でとどめます。","respondent":"東野福祉計画課長","answer":"まだ全体の確定ではないのですが、現在、総整備費が９５億円余のところ、補助金額につきましては１２億５,０００万円の予定でおります。詳細につきましては、今後、契約変更等を加味して変わってくると思われます。","voiceIndex":148,"id":"exchange-041"},{"speaker":"やなぎさわ委員","kind":"確認","question":"放課後等デイサービスの助成事業なのですけれども、非常にすばらしいことなのですけれども、確認なのですが、今回の助成は新規開設の事業所に限るということでよろしいでしょうか。","respondent":"佐藤障害者施策推進課長","answer":"開設費用等助成に関しましては、区内の事業所を増やすところを目的にしておりますので、新規開設のところを対象にというところで予定しているものです。","voiceIndex":151,"id":"exchange-042"},{"speaker":"やなぎさわ委員","kind":"確認","question":"これも確認ですけれども、今回、物件の初期費用や賃料、駐車場の補助が新規開設のところで出るというところなのですけれども、既存の施設に対して類似の制度は品川区は何か設けていらっしゃったか確認したいのですが、いかがでしょうか。","respondent":"寺嶋福祉部長","answer":"それは、次年度に向けて引き続き検討させていただきたいとは思っておりますが、取りあえず今回の補正予算については新規開設に力を入れている。そういう理解でおります。","voiceIndex":153,"id":"exchange-043"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そうですね。既存の放課後等デイサービスも、やはり、それこそ家賃補助や駐車場の補助があると非常に喜ばしいと思いますので、ぜひ次年度お願いできればと思います。次なのですけれども、（２）中重度受入れの促進事業なのですが、そこの2)のウなのですが、車両リース料という記載がありますけれども、これは、いわゆるカーリースというのが対象なのでしょうか。説明をお願いしたいと思います。","respondent":"松山障害者支援課長","answer":"こちら、ウの車両のリース料についてのご質問です。こちらは、購入ではなくリースということで、月に５万円を見込んだものです。","voiceIndex":155,"id":"exchange-044"},{"speaker":"やなぎさわ委員","kind":"質問","question":"これは、送迎車を買うときに、リースではなくて一括購入の場合も当然あり得ると思うのですが、車両リースに限定したところには何か理由があるのでしょうか。","respondent":"松山障害者支援課長","answer":"購入ですと、今、購入してかなりの時間を要してしまいますので、リースでしたら比較的、早い時間で調達できるということがあります。そのため、補正ですので３月の間までにということを考えますと、やはりリースのほうが現実的であると考えたものです。","voiceIndex":157,"id":"exchange-045"},{"speaker":"やなぎさわ委員","kind":"確認","question":"来年の３月までというと、つまり先ほど話がありましたけれども、実質的には四、五か月半ぐらいになるということで、５か月だとして２５万円ぐらいが最大ですということで、その先についてはまた次年度ということになるという理解でよろしいか、確認です。","respondent":"松山障害者支援課長","answer":"ご指摘のとおりです。","voiceIndex":159,"id":"exchange-046"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"もしこれが継続的に次年度も続くのであれば相殺できるかもしれないけれども、２５万円ぐらいで単年度で終わったとして、その後いろいろ苦労される可能性もあるので、その辺もいろいろ、もしカーリースを利用されるなら、デメリットなどもきちんと啓発して、当然、選ぶ側も、事業所も調べることだと思うのですけれども、ミスリードにならないように気をつけていただきたいと思うのですが、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"委員のおっしゃる懸念点などということにつきましては、今後配慮して、事業所にも周知してまいりますし、来年度の予算につきましても、そういったことは配慮して検討してまいります。","voiceIndex":161,"id":"exchange-047"}]},{"id":"topic-03","title":"令和７年請願第１８号、国に対して次期改定を待つことなく介護報酬引き上げを求める意見書の提出を求める請願","agenda":"令和７年請願第１８号、国に対して次期改定を待つことなく介護報酬引き上げを求める意見書の提出を求める請願","exchanges":[{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところからすると、これまで訪問介護事業所の実態というのはお聞きしてきたのですけれども、品川区のデイサービスの経営状況というのがどうなっているのか、人材不足の状況ですとか、品川で閉鎖となったデイサービスの件数とかも、この５年間ぐらいで分かればお知らせいただきたいのと、その理由についてもお伺いしたいと思います。","respondent":"菅野高齢者福祉課長","answer":"その背景として、要支援の方のサービスというところで、総合事業のことをお話しされておりますが、国のほうの制度で、平成２７年から総合事業ができまして、区のほうで単価の設定ができるようになりました。","voiceIndex":179,"id":"exchange-048"},{"speaker":"鈴木委員","kind":"質問","question":"その中で処遇改善加算が０.９８％なので、本体の報酬は僅か０.６１％なのです。１％にもならないという状況で、私はここの介護報酬の引き上げというのがどうしても必要だというふうに思うのですけれども、その点を区としてどう考えるのか伺いたいと思います。介護保険は２０００年から始まりました。介護報酬の引き上げというのに対して、区としてどう考えるかという点についても伺いたいと思います。","respondent":"菅野高齢者福祉課長","answer":"先ほどのご説明の中でも少し触れさせていただきましたが、介護報酬自体が国の調査や制度の枠組みの中で行われております。その中で給付と負担のバランスを図りながら、改定率も国のほうが決定しているという流れがありますので、引き上げすることが正しいのかどうか。","voiceIndex":181,"id":"exchange-049"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういうところで言えば、ぜひそういう改悪、これに反対する有識者の方々も、史上最悪の介護保険改定ということで言われていますので、そういうのをさせないためにも、議会としてもぜひ意見書を上げていくというところで、議会も、区としてもそういうふうな立場で上げていくということが求められているのではないかというふうに私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":183,"id":"exchange-050"},{"speaker":"やなぎさわ委員","kind":"質問","question":"鈴木委員のおっしゃることはごもっともで、先ほど質疑の中で、区内のデイサービスの倒産件数の把握はされていないということではあったのですけれども、逆に新規の状況はいかがですか、もし分かれば。","respondent":"菅野高齢者福祉課長","answer":"デイサービスの指定自体が東京都の指定で、１８人以下の地域密着型の通所介護については、区の指定ということになります。","voiceIndex":185,"id":"exchange-051"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そのときに、請願に対して反対される委員の中に、ちょうど今、国が訪問介護の報酬を引き上げるような段取りを組んで、アンケートを取ったり、いろいろやっているから、議会が、品川区がいろいろ言わずに待つべきだと、そんなことをおっしゃられた方がいたと思うのですけれども、現状、区のほうで訪問介護を含めた介護報酬の引き上げについて何かしらのアクションが議論されているのかどうか。","respondent":"菅野高齢者福祉課長","answer":"区のほうとしては、訪問介護サービス事業所安定運営支援金というのを補正予算で組ませていただきまして、１０月からいよいよ受付を始めさせていただこうというところなのですが、こちらの背景としては、あくまでも国の介護報酬の調査をして、審議会の中で議論して。","voiceIndex":187,"id":"exchange-052"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その動向というのを、今現在どのように捉えていらっしゃるか教えてほしいです。","respondent":"菅野高齢者福祉課長","answer":"国の動向、審議会のほうで議論されているというところで、そちらについては、情報収集はさせていただいているのと、国のほうで全国市長会等も要望を出すなどして、適切な介護報酬の単価設定をしてくださいという形で、区として意見を上げていきたいというふうに思っております。","voiceIndex":189,"id":"exchange-053"},{"speaker":"やなぎさわ委員","kind":"提案","question":"そうなると、介護報酬を上げるということが一番手っ取り早く、介護事業所の収入も上がるし、最低賃金が上がった分をカバーできるということになると思うので、私自身は、そういう面でも早急に区議会からこういった現場の窮状をしっかりと国に対して、特に国も今のところリアクションが薄いと受け止めているので、もしほかの委員の方で、今国がこんなことを提案していて。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":191,"id":"exchange-054"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今のご意見についてですけれども、もし所管の課長がご存じならば教えていただきたいのですが、国としての動き、たしか６月の骨太の方針には、まさに目玉として介護報酬も含めた様々な、医療等の部分も含めて、引き上げを明確にうたっているはずなのです。その辺りについて、所管の課長、国の動きとして何かつかんでいるところがあれば、教えていただきたいと思います。","respondent":"菅野高齢者福祉課長","answer":"委員がご指摘のように、骨太の方針には確かに一部こういった文言が掲載されていると認識しておりますが、国のその後の介護給付費分科会や介護保険部会などの審議の内容等を見る限りですと、多分年末の予算交渉とか、そういった中で来年度どうするか、期中改定があるか。","voiceIndex":192,"id":"exchange-055"},{"speaker":"あくつ委員","kind":"確認","question":"骨太の方針で閣議決定されていて、それについて現段階では、期中改定があるのかどうかについては明確に示されていないということは確認させていただきました。意見については、後ほど述べたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":194,"id":"exchange-056"},{"speaker":"吉田委員","kind":"提案","question":"そのときにも要支援１・２を総合事業にしてしまったということが、私たちとしては当時からこれは本当に問題だというふうに思っていたのですけれども、提案としては、よさげな提案として、地域の方たちのボランタリー、お互いの助け合いの仕組みを区、自治体がつくっていくというような提案もあったようには思うのですけれども、それが結局品川区として地域に発信して。","respondent":"菅野高齢者福祉課長","answer":"区としての総合事業の評価というところは、どう捉えるべきかというところは難しいと思うのですけれども、例えばすけっとサービスなどは、ボランティアの生活援助のサービスを提供したり、そういった形で、専門の職種ではない人たちによって地域包括ケアシステムの中で。","voiceIndex":196,"id":"exchange-057"},{"speaker":"吉田委員","kind":"提案","question":"その評価が正しいかどうかは置いておくとして、基本的な介護保険の仕組みというのは、２０００年でしたっけ、介護を社会化するということで、みんなようやく介護サービスが社会化されるかということで、大歓迎だったのですけれども、なかなかうまくいかなくて、総合事業というのも提案されるようになって、自治体で、私もとてもうまくいっている事例も聞きました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":198,"id":"exchange-058"},{"speaker":"吉田委員","kind":"質問","question":"前に別の委員会でも言ったと思うのですけれども、区内の訪問介護事業所のヒアリングをしたときに、そこはれっきとした訪問介護事業所なのです。でも、総合事業の報酬単価の低いのも現実は引き受けているわけです。結果として赤字になっていくわけです。それでいいのですかというのがあります。だから、その辺の事業所への現状の聞き取りとか、状況把握はされているのか伺います。","respondent":"菅野高齢者福祉課長","answer":"やはり皆さん募集を出してもなかなか集まらないとか、募集を出すと、そこに紹介事業者がホームページに挟んでくるというか、まるで紹介事業者をクリックしないとそこに応募できないような仕掛けをされて、結局そこからの手数料を取られてしまうといった、すごく詳細な。","voiceIndex":202,"id":"exchange-059"},{"speaker":"吉田委員","kind":"意見","question":"そういうのは１事業所では対策できないと思うので、もし可能であれば、そういう専門性を持った方で、防御の仕組みみたいなものをつくれたらいいかなというふうに思っております。この請願からは少し外れるかもしれませんけれども、基本、介護保険の仕組みというのを維持するという方向は、一緒に考えていくべきだというふうに思っております。これは意見です。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":204,"id":"exchange-060"},{"speaker":"鈴木委員","kind":"提案","question":"共産党は国の負担割合を現在の２５％から３５％に引き上げて、公費負担を６割にするという提案をしているのですけれども、そういうことで介護報酬を上げても、介護保険料に行かないというところにできると思うのですけれども、これはかつて自民党も公明党も主張していまして、自民党は２０１０年の参議院選挙の公約で、公費負担の増加を図り、介護保険料の上昇を抑制するということを明記しているのです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":206,"id":"exchange-061"},{"speaker":"あくつ委員","kind":"質問","question":"以前、訪問介護のときにもお聞きしたのですけれども、財源をどうされるかというところで、そのときはたしか共産党とれいわ新選組のご主張というものを拝聴したのですが、財源はどうされるのですか。もう一度伺います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":207,"id":"exchange-062"},{"speaker":"鈴木委員","kind":"意見","question":"これは税金の使い方を変えるというふうなことなのですけれども、公明党自らが公約にも書かれていたことなので、そのときには財源があったけれども、今財源がないということではないと思います。それなので、何を大事にするかというふうなところだと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":208,"id":"exchange-063"},{"speaker":"あくつ委員","kind":"質問","question":"そのとき、そのときの議論というものがあると思うのです。共産党もかつて様々なことをおっしゃっていて、でも、そのことを言うと、多分水かけ論になってしまうと思うのです、いろいろ。２０１１年の公約ですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":209,"id":"exchange-064"},{"speaker":"あくつ委員","kind":"意見","question":"今ここで政党同士の公約ということを根拠にされるということ自体が、多分共産党も公約はいろいろ変わっていますよね。そのとき、そのときの情勢に合わせて、だから一致できるというのは牽強付会ではないかなと私自身は思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":213,"id":"exchange-065"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"先ほど吉田委員の質疑の中で、総合事業の話をされていて、訪問介護事業者の方たちが、単価の安い生活援助のほうを求められている、必要とされているから、割が合わないと分かっていても頑張ってやっていただいているというお話がありました。２割というのは売上げの２割で、利益の２割ではないのです。１６０万円の売上げで１８０万円の経費がかかるとマイナス２０万円になって、一気に赤字になってしまう。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":215,"id":"exchange-066"},{"speaker":"えのした副委員長","kind":"質問","question":"本日結論を出すで、不採択とします。理由としては、理事者のご説明にもありましたが、介護現場は厳しい状況にあると思います。区の事業者の実態も伺いました。現段階では国の方向性がはっきり示されていないということですので、今後も国の動向を注視して、情報の収集をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":218,"id":"exchange-067"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すで、態度については、不採択でお願いいたします。請願の、議会として国に意見書を求めるというところでありますが、この間、皆さんのお話をいろいろ伺っていましたが、国のほうでしっかりと考えていただくということがまず必要だというところで、今回の効率のいい訪問介護というところで、品川区の中では在宅がほとんどという中、かなり影響が出てしまった。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":219,"id":"exchange-068"},{"speaker":"あくつ委員","kind":"提案","question":"態度としては、本日結論を出すで、不採択です。先ほどもありましたけれども、公明党としてどういう考え方かと申しますと、５月の、先ほども質問させていただいた骨太の方針が出る直前に、私ども公明党からも国会議員から石破総理に対して、訪問介護も含む社会保障の分野についての報酬引き上げということについては、期中改定も含めて検討してくれということも申し入れているところです。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":220,"id":"exchange-069"},{"speaker":"鈴木委員","kind":"質問","question":"結論を出すで、採択でお願いしたいと思います。人材不足、それから経営困難というふうな状況になっていると思います。それから、使い方としても、防衛費とかはすさまじい勢いで増やしているわけですから、それよりも福祉、社会保障、そういうふうなところに充てるべきというのが私たち共産党としての考え方です。財源はそういうふうなことで十分生み出せるという考え方だということも述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":221,"id":"exchange-070"},{"speaker":"吉田委員","kind":"提案","question":"本日結論を出すで、採択を主張したいと思います。ですから、はっきり言えば、皆さんが介護を必要とされたときには、その制度はなくなっているかもしれないということです。もちろん否定するものではないのですけれども、介護の現場では人材が足りないということで、なかなか引退できなくて、７０代の方の介護に８０代のヘルパーがいらっしゃる。確かに具体的にここからという提案は、残念ながらできません。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":222,"id":"exchange-071"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"訪問介護の助成金に関しては、品川区が本当にすばらしい動きをしていただいたと思うのですけれども、これは訪問介護だけですから、今回の請願は介護報酬、介護業界全体のことですので、その辺をちょっと勘違いされているようなことをおっしゃっていた方もいらっしゃったかなと思いますが、全体ですので、ここは期中改定を含めて、早急に改善を求めるために。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":223,"id":"exchange-072"}]},{"id":"topic-04","title":"令和７年陳情第３１号、国民健康保険の区民に対する資格確認書の一斉交付に関する陳情","agenda":"令和７年陳情第３１号、国民健康保険の区民に対する資格確認書の一斉交付に関する陳情","exchanges":[{"speaker":"鈴木委員","kind":"確認","question":"今ご報告いただいた国民健康保険の加入者で、資格認証書を送られた方は２万７,０００人ということですと、全体の５８％がマイナ保険証を持っているということです。それで、マイナ保険証、マイナ保険証とあれだけ言ってきましたけれども、かなりマイナ保険証に登録していなくて、資格確認書で対応するという方がこれだけいるのだなというふうに思いました。お願いします。","respondent":"山下国保医療年金課長","answer":"本年４月からこの９月少し半ばぐらいまでになりますけれども、合計しますと、１００件を少し超えているような状況で、数として激増しているような状況ではございませんで、一定の推移をしているというような状況です。","voiceIndex":231,"id":"exchange-073"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう中で、今回資格確認書という形になったわけですけれども、資格確認書であれば、今までの保険証と全く変わりなく、そのまま使えるというふうなことなので、マイナ保険証を持ち歩きたくないという人は、取り消して資格確認書にできるということはしっかりと伝えていただきたい、周知をしていただきたいと思うのです。","respondent":"山下国保医療年金課長","answer":"利用登録の解除ということを主として、そこを推すような形での周知ということではございませんけれども、実際そういう対応が必要な方、そういうお求めがある方にはしっかりと内容が伝わるような形で引き続き周知に努めてまいります。","voiceIndex":233,"id":"exchange-074"},{"speaker":"鈴木委員","kind":"確認","question":"全くそのまま持ち続けられるということですか。あれからちょうど５年たつので、今年ぐらいからもう更新になって手続が必要ということで見たのですけれども、マイナ保検証の５年ごとの更新というのは必要ないということなのか、その点をもう一回お願いしたいのと、更新を忘れてしなかった場合というのは、資格確認書が自動的に届くということになるのかどうなのか、そこら辺のところも伺いたいと思ったのです。","respondent":"山下国保医療年金課長","answer":"マイナ保険証利用のメリットといたしまして、例えば転入・転出等があった場合にも、従前の資格が情報としてうまく残ることで、医療情報等がお手元でしっかりと把握できるというようなところがメリットとして挙げられてありますので、そういったところも含めて。","voiceIndex":235,"id":"exchange-075"},{"speaker":"やなぎさわ委員","kind":"確認","question":"すみません。最初の説明で聞き逃した部分があるので、確認なのですけれども、区として７月中旬頃に２万７,０００人の方に資格確認書を送付したと、３万４,０００人の方に何かお送りしたのでしたっけ。その辺を確認させてください。","respondent":"山下国保医療年金課長","answer":"他方で、マイナ保険証はまだ利用されていないという方、約２万７,０００人の方に対しましては、資格確認書をお送りしたところです。","voiceIndex":238,"id":"exchange-076"},{"speaker":"やなぎさわ委員","kind":"確認","question":"それで、お伺いしたいのですけれども、資格確認書と資格情報のお知らせというのは、機能としては何が違うのでしょうか。","respondent":"山下国保医療年金課長","answer":"他方で、そういったことを連続的にご利用いただくことは念頭にございませんので、まず、受診されて一度困ってしまったという状況は、そういった対応でできるのですが、次回以降お待ちいただけるものをお持ちいただくようにご案内をということで、周知されているところです。","voiceIndex":240,"id":"exchange-077"},{"speaker":"やなぎさわ委員","kind":"確認","question":"となると資格情報のお知らせは、その１枚では意味はないけれども、マイナ保険証が、機器のトラブルとか何かで使えないときのために、一応携帯しておくと、併せてセットで使えるということだと思います。そこで、一応確認なのですけれども、この陳情に書かれてある厚生労働委員会、福岡厚生労働大臣が最後は自治体の判断というふうに容認しているということに関して、これは間違いないでしょうか。","respondent":"山下国保医療年金課長","answer":"ご質問のございました福岡厚生労働大臣の発言の部分ですけれども、従前の委員会でもご説明申し上げたところかと思うのですが、あくまでも国として資格確認書を一斉に交付する必要があるとは考えていないところはあるけれども、自治事務であるので。","voiceIndex":242,"id":"exchange-078"},{"speaker":"吉田委員","kind":"確認","question":"ある弁護士で行政法の学者なのですけれども、品川区の現状をいろいろ教えてということで、その方が聞きたいことを、私は大分前に国保医療年金課長に伺ってしまいましたので、今の質疑でその復習をさせていただいたという感じです。１点、東京都後期高齢者医療広域連合では、後期高齢者である加入者に資格確認書を一斉交付する方針を示しています。ああ、そうか、前期高齢者には結局来るから大丈夫なのかな。","respondent":"山下国保医療年金課長","answer":"こちらにつきましては、社会保障審議会の医療保険部会でも、支部の代表の委員が、そういった問合せがあったから、国のほうで丁寧な周知をしてほしいということはご意見としておっしゃられていまして、区として非常に多くのご質問。","voiceIndex":245,"id":"exchange-079"},{"speaker":"えのした副委員長","kind":"確認","question":"理由としては、区民の方が混乱しないように様々周知もされているということで、理事者の方からも説明いただきましたけれども、区としては法令どおりに７月に資格情報のお知らせと資格確認書を郵送しているということです。業務負担増による相当な混乱や負担が生じるというのが中にはありますけれども、課長からは発行依頼など、現場も混乱はしていないということですので、不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":249,"id":"exchange-080"},{"speaker":"あくつ委員","kind":"確認","question":"本日結論を出す、不採択でお願いします。意見というか、区としては今、粛々と国の方針どおり行っているということも受け止めますし、現段階では資格確認書を一斉交付する必要はないのではないかと考えますので、不採択でお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":251,"id":"exchange-081"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そういう点からも、今までと全く同じ保険証として使える資格確認書が、後期高齢者医療制度では全員にというふうなことだったのですけれども、これをこれからもずっと続けていただきたいと思いますし、国民健康保険も資格確認書というのがそのまま全ての人に配布されたら、今までどおり使えるので、今までみんな不便ではなくて、便利に使っていて、変えてほしいというのは。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":252,"id":"exchange-082"},{"speaker":"吉田委員","kind":"確認","question":"１０秒ぐらいかかるのです。というか、１０秒で済むのですよ、マイナ保険証で、だから、そんなにトラブルはないと思ったのですけれども、私も資格確認書だったらもう目視で１秒なのですよ。そういうことですので、今のところトラブルが起きていなかったとしても、資格確認書の一斉送付というのは、そういうトラブルを起こさないための有効な手段だと思いますので、この陳情については、採択を主張いたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":253,"id":"exchange-083"},{"speaker":"やなぎさわ委員","kind":"確認","question":"本日結論を出すで、採択でお願いいたします。先ほど様々な質疑がありましたけれども、資格確認書というのは、保険証と同様に利用できるということで、非常に利便性もありますし、何が送られてくるか、同じ家族でも違ったりすると混乱にもなります。区としても国民健康保険の方には全員資格確認証を送るというふうにしたほうが、業務の効率的にも楽なのではないか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":254,"id":"exchange-084"}]},{"id":"topic-05","title":"の利用者に対し、自主的・先導的に独自の予算制度を創設し、所得の多寡に関わらず、財政措置を講じて","agenda":"の利用者に対し、自主的・先導的に独自の予算制度を創設し、所得の多寡に関わらず、財政措置を講じて","exchanges":[{"speaker":"鈴木委員","kind":"提案","question":"シルバーパスを７０歳以上の全員が１,０００円で購入できるようにという陳情ですけれども、先ほどご説明がありましたように、都が実施する事業ということで、本来と都が１,０００円で買えるようにやるべきということで、共産党の都議団は、シルバーパスを１,０００円で買える条例の提案をしているところですけれども、今回東京都がやっと引き下げはしましたけれども、１万２,０００円という状況なので。","respondent":"樫村高齢者地域支援課長","answer":"３点目の介護保険制度の１から７の支援区分というお話がございましたけれども、こちらにつきましては、すみませんが詳細を把握しておりません。細かい質問につきましては、東京都のバス協会のほうにお問い合わせいただくようなご案内をしています。","voiceIndex":262,"id":"exchange-085"},{"speaker":"鈴木委員","kind":"質問・要望","question":"２万５１０円というのは結構高いので、それもどれぐらいの人がその対象で、そこで買っている人数というのはどれくらいなのかというのは把握されていないのか教えてください。それから、１万１,０００円を区が助成するとなると、先ほど言われたように、８,８００万円の予算が必要だということで、改めて確認させていただきたいと思います。","respondent":"樫村高齢者地域支援課長","answer":"２点目のところです。８,８００万円と試算をしたですけれども、あくまで荒川区の予算編成を基に、品川区の人口で割り返して試算をしてみたです。","voiceIndex":264,"id":"exchange-086"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。東京都が公表していないということなのですね。品川区では今コミュニティバスを試験運行していますけれども、そこではシルバーパスが使えるようにしていると思うのですけれども、それはどのような政策判断なのかというのは、所管が違うから難しいかもしれないですけれども、もし分かったら、教えていただけたらと思います。","respondent":"樫村高齢者地域支援課長","answer":"コミュニティバスにおけるシルバーパスの運用につきましては、すみませんけれども、所管外なのでコメントは差し控えたいと思います。","voiceIndex":266,"id":"exchange-087"},{"speaker":"鈴木委員","kind":"質問","question":"分かりました。コミュニティバスも使える自治体と使えない自治体があると伺ったのですけれども、品川区はコミュニティバスでもシルバーパスが使えるようにしているというふうなところで、シルバーパスが１,０００で買えて、そのパスがあれば、お金がかからずにバスに乗ったり、地下鉄に乗ったりして外出が気軽にできるというところは、高齢者の社会参加というところで大きな役割を果たしていると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":268,"id":"exchange-088"},{"speaker":"えのした副委員長","kind":"質問","question":"本日結論を出すで、不採択とします。高齢者の外出支援を促進するための一つの手段として、否定をするわけではありませんが、あくまで東京都の事業であること、また、現時点において制度の見直しの途中であり、また今年度より大幅に価格が下げられることから、不採択とします。なお、理事者からの説明にもありましたが、都や他自治体の動向について、今後も引き続き積極的な情報収集をお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":271,"id":"exchange-089"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。そもそもこのシルバーパス制度ができてから、全員に配られていた時期があったかなというふうに思っております。その中から今みたいな一定の所得の制限を設けて配っていくというふうになっている過去からの流れも踏まえると、今実質１,０００円でというところは難しいのだろうというふうに思っているので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":272,"id":"exchange-090"},{"speaker":"あくつ委員","kind":"質問・要望","question":"今回、東京都のほうで、これは私どもの会派も含めて、都議会から要望もしてというところで、１０月から２万５１０円のパスが１万２,０００円となったというところなのですけれども、これから始まってくる中で、それは見極めなければいけない部分があるなと。荒川区とか、他のところで模索しているという状況もしっかり見極める必要があるという中で、現段階では不採択とします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":273,"id":"exchange-091"},{"speaker":"鈴木委員","kind":"提案","question":"結論を出すで、採択でお願いしたいと思います。都の事業ということなので、本来東京都がやるべきだというふうには思っています。共産党都議団としても、昨年１２月にも一律１,０００円の条例提案をしているところですけれども、様々な条例提案を何度もしてきているところですけれども、そういうのが今回の１万２,０００円に下がったということにもなってきていると思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":274,"id":"exchange-092"},{"speaker":"吉田委員","kind":"意見","question":"本日結論を出すで、採択でお願いいたします。個人的なことで思い出してしまうのですけれども、私の父もこのシルバーパスを活用して、ゲームみたいな、時間はたっぷりあるので、とにかく都バスと都営地下鉄だけで、都内で行きたいところにどうやっていくかというのをやっていたのを、もう大分前に亡くなりましたけれども、まだ元気な高齢者だったとき、そういう活用をしていたのを思い出します。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":275,"id":"exchange-093"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論を出すで、採択でお願いいたします。最後に一つだけ、荒川区が２３区の中で唯一シルバーパスを１,０００円で購入できるというのを実現しているところなのですけれども、これはもしかしたら地域事情があるのかもしれませんけれども、実は荒川区の公明党が推進しておられたという経緯があって、区長に対して要望書を提出して、シルバーパスの実質無償化を強く要望したと。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":276,"id":"exchange-094"}]},{"id":"topic-06","title":"令和７年陳情第３６号、障害者施設の利用調整を区に求める陳情","agenda":"令和７年陳情第３６号、障害者施設の利用調整を区に求める陳情","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"基本的な質問になりますけれども、課長の今の答弁によると、障害者施設の利用調整はしているということになりますか。卒業されるときの調整はあるということですけれども、全体としての利用調整について教えてください。","respondent":"松山障害者支援課長","answer":"ですから、個別に対応するという今の方式を変える予定はございません。","voiceIndex":285,"id":"exchange-095"},{"speaker":"吉田委員","kind":"確認","question":"その利用調整のイメージが保育園みたいに収入とかで点数を機械的につけ、機械的と言ってはいけないのかもしれないですが、点数をつけてなるべく全員が入れるようにするという利用調整とは違うけれども、要は多くの人がなるべくその人に合う施設を一緒に選んでいるというイメージで間違いないですかということが１つ確認です。それとも、そんなことはなかったのですか。","respondent":"松山障害者支援課長","answer":"ただ、点数化は難しいです。どちらかといいますと、１８歳の壁の対応もありまして、非常に個別性を品川区としては重視しています。","voiceIndex":287,"id":"exchange-096"},{"speaker":"吉田委員","kind":"確認","question":"利用調整という言葉の定義がずれていたのかなというふうに思います。多分、陳情者の方も点数化してどうのこうのという話ではなくて、キャパシティが決まっている中で多くの人が希望のところに行けるような仲立というのですか、調整をやってほしいという趣旨だと思います。私は、こういうことが多分地域拠点相談支援センターの役割ではないかと思っていたのですけれども、その点についても確認させてください。","respondent":"松山障害者支援課長","answer":"ほかの通所施設に異動を希望される場合、既に相談支援員がおそらくついている場合が多いですが、ただ、その相談支援員に相談してもなかなか事業者との調整が難しい場合は、委員がおっしゃられたとおり地域拠点相談支援センターがその役割を担っておりますので。","voiceIndex":289,"id":"exchange-097"},{"speaker":"吉田委員","kind":"質問・要望","question":"例えば、障害者支援課に行けば、基本的なそういう区内の情報ですから、もしくは相談支援センターが持っているべきだとかということであれば、その点についても教えていただきたいと思います。この陳情文の２ページ目にある区内生活介護事業所一覧は、区から情報提供されたものですというふうに伺いました。そういうような方法というのは考えられないでしょうか。","respondent":"松山障害者支援課長","answer":"こちらは情報提供させていただいたものだと思いますが、随時お問合せもいただければかなり空き状況については、例えば４月時点とかそういうことであれば区切るのですが、日々月ごとに変わってきたりとかしますと。","voiceIndex":291,"id":"exchange-098"},{"speaker":"吉田委員","kind":"質問・要望","question":"分かりました。この数は区から提供していただいた数ということですので。本当は今数を伺いたいのですが、金曜日にこの情報をいただいてそれで今日ですので、あらかじめお願いをしていないので、具体的な数字は今無理であれば直近で明後日の委員会とか、その後でも結構ですので、こういう数字についてはぜひ伺いたいというふうに思うのですけれども、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"事業所もかなり実際の利用者を目の前にして、どこまでその方の情報をオープンにするかという形では悩みどころではありますので、今回はこういう形で人数であればということで出させていただいたものです。明後日までにというのは、ちょっと難しいかと考えています。","voiceIndex":293,"id":"exchange-099"},{"speaker":"吉田委員","kind":"質問・要望","question":"要は、そこの施設の対応のキャパシティがどれくらい空いているのかということが分からないと、人数だけを伺ってもなかなかここに行きたいとかあそこは残念だけれども今は無理とかいう判断も難しいと思いますので、どこら辺まで表現するかはまたご相談ということですが、基礎的な情報としてぜひ教えていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":295,"id":"exchange-100"},{"speaker":"鈴木委員","kind":"質問","question":"グループホームだったら他区に入らざるを得ないという状況があると思うのですけれども、就労継続支援Ｂ型とか生活介護、それから利用調整をしているというところでは、世田谷区などは就労移行支援もそうですが、そういうところで品川区にそれぞれ他区でそういうサービスを受けているという方は何人くらいいるかということが分かったら教えていただけないでしょうか。","respondent":"松山障害者支援課長","answer":"今、その数字は持ち合わせてはおりません。","voiceIndex":297,"id":"exchange-101"},{"speaker":"鈴木委員","kind":"質問","question":"そこら辺のところを区としてはどう捉えられているのか、その点も伺いたいと思います。それから、先ほど卒業の方はほとんど一人一人に相談をしっかりと行いながら、卒業の方は皆さん希望の施設に通えているというふうに区としては捉えられているのか、その点についても伺いたいと思います。","respondent":"松山障害者支援課長","answer":"２つ目の希望施設、第１希望に入れるかということですけれども、全ての方が第１希望ということではございませんので、なかなかこの施設に入りたいと言っても、例えばかなり送迎に時間がかかってしまったり、あとは１８歳の壁にその施設が対応できるのか。","voiceIndex":299,"id":"exchange-102"},{"speaker":"鈴木委員","kind":"質問・要望","question":"そこのところも、この人が入るのだったら誰もが納得だなというふうな感じの状況ではなかったということが多分、皆さんもなかなか納得がいかないところだと思います。私は、そういう調整会議を行いながら、そういう基本方針、計画をぜひともつくって、施設の整備につなげていただきたいというふうに思っていますけれども、いかがでしょうか。","respondent":"松山障害者支援課長、佐藤障害者施策推進課長","answer":"品川区としましては、今は非常に個別に丁寧にきめ細かく調整をしておりますので、１８歳の壁対応も含めて本当にオーダーメイド的に調整をしています。なので、今の方法でそのまま利用方法については行っていきたいと考えております。必要量というところでは、令和９年度からの障害福祉計画に向けてということで、先般も基礎調査の実施等も報告をさせていただいたところですが、そういったところも踏まえて必要量ですとか。","voiceIndex":301,"id":"exchange-103"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私から、質問を１点だけ。世田谷区なんかはこの陳情で事例が出ていましたけれども、例えばさらにブラッシュアップさせるという意味で、他区のやっている取組を少し調査してみて品川区にいい部分を取り入れたり、そういった取組は過去にされているのか、今後する予定があるのか、もしあればお伺いしたいのですけれども、いかがでしょうか。","respondent":"松山障害者支援課長","answer":"ただ、今後他区で本当にいいような取組があれば、もちろん取り入れてはいきたいと考えております。","voiceIndex":305,"id":"exchange-104"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"そもそも施設の数が少ないという問題は当然あるのですけれども、それが前提ではあるのですが、やはり今品川区でやっている調整というか対応に対しては自信を持たれていると理解したのですけれども、さらにやはり高みを目指していただきたいという思いで、もしこういう議会からでも話が出たり、もしくは様々なところへ情報収集をして、他自治体のいい先進事例のうわさとかを聞くようでしたら。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":307,"id":"exchange-105"},{"speaker":"えのした副委員長","kind":"意見","question":"本日結論を出すで、不採択。理由としましては、各自治体で利用の手順の方法は異なるようですが、重要な役割として個別で品川区のほうは受入れの相談をしている。相談支援専門員、事業所と連携して細やかに対応しているということで、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":310,"id":"exchange-106"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。施設のところも入所率とかを見るとまだ空きがあるというところも少しそごがあるのかなというところもありますので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":311,"id":"exchange-107"},{"speaker":"あくつ委員","kind":"質問・要望","question":"本日結論を出すで、不採択でお願いいたします。１８歳の壁対応も丁寧に対応し、オーダーメイドでやっているという。先ほど自負という言葉もありましたか。パーセンテージで示された中で、より利用できるようにというところが一番のご希望だと思いますので、より丁寧に、しかも皆さんの要望どおりできるだけこれからも調整をお願いしたいというところで、不採択といたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":312,"id":"exchange-108"},{"speaker":"鈴木委員","kind":"質問・要望","question":"結論を出すで、採択でお願いしたいと思います。利用する施設が質、量ともに足りないということが根本の問題としてありますので、それは所要量も出すところから計画を立てていくというふうなことでご答弁ありましたけれども、ぜひとも施設整備の計画、基本方針、そういうものを立てて、具体的にそれをいつまでに何か所、どういう施設をというふうなところを明確に出していただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":313,"id":"exchange-109"},{"speaker":"吉田委員","kind":"質問","question":"本日結論を出す、採択でお願いいたします。この陳情の議論を伺いながら、言葉について何を選んでくるかなということは本当に難しいと思いました。頑張って施設を探して、ほかにもいろいろな、言い方は悪いですけれども、こういう手続に慣れている方は一生懸命ご自分で探して、しかるべき施設を見つけているということはされているわけです。グループホームだけでは、完成しないわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":314,"id":"exchange-110"},{"speaker":"やなぎさわ委員","kind":"意見","question":"本日結論を出すで、趣旨採択でお願いいたします。先に理由だけ言います。根本はやはり施設を増やすというところだし、しっかりとした福祉計画を立てて計画的に進めていくということが大事ではあると思うのですけれども、そういった意味で私は趣旨ではありますが、採択とさせていただければと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":315,"id":"exchange-111"}]},{"id":"topic-07","title":"令和７年陳情第３９号、自殺対策の誤解を解くために啓発内容を改める陳情","agenda":"令和７年陳情第３９号、自殺対策の誤解を解くために啓発内容を改める陳情","exchanges":[{"speaker":"やなぎさわ委員","kind":"質問","question":"ということは、もう１０年以上くらい前から正しい啓発はしてきたというような、ここに書かれた誤解というのはすでに啓発はしているというようなことだと思うのですけれども、例えばゲートキーパーの養成の講座で、いわゆるここに書かれてある東京都の自殺に関する５つの誤解は既にこのような指導をしているということでよろしいでしょうか。","respondent":"五十嵐保健予防課長","answer":"ですので、その中でこのような５つの誤解という形で伝えているわけではございませんが、やはり死ぬ死ぬと言う方が死ぬわけではないみたいなことはないということなど等は周知させいただいているところになっております。","voiceIndex":327,"id":"exchange-112"},{"speaker":"やなぎさわ委員","kind":"確認","question":"ということは、ここの５つのことはゲートキーパーの講習に入っているということで、一応確認のためにもう一度お願いいたします。","respondent":"五十嵐保健予防課長","answer":"入れしています。","voiceIndex":329,"id":"exchange-113"},{"speaker":"やなぎさわ委員","kind":"確認","question":"私も東京都自殺総合対策計画～こころといのちのサポートプランを確認させていただいたのですが、この中で実際に自殺されてしまった方の男性で１割の方が未遂をしたことがある。やはり、積極的にこの自殺に関する誤解というのは、特にここに書かれてあることなんかは本当によく語られる言説であると思うので、重点的に区としても発信していく必要があるのかと思うのですけれども、いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"我々はやはり自殺対策をやっているということもありまして、少しずつ周知されてきて浸透してきたのかと思っていたところではあるのですけれども、今回このような陳情が上がってきたということもありまして、まだまだ周知が足りなかったかと考えていますので。","voiceIndex":331,"id":"exchange-114"},{"speaker":"鈴木委員","kind":"質問・要望","question":"ここのところで審議の公開が非公開ですけれども、議事録は公開ということになっているのですけれども、議事録が公開となっていたにも関わらず見当たらなかったので、公開されているのかについてもお聞かせいただきたいと思います。","respondent":"五十嵐保健予防課長","answer":"自殺対策連絡協議会ですが、こちらのほうは立正大学の心理の先生を議長とさせていただきまして、東京都の中部総合精神保健福祉センターの方とか医師会の方、警察署、消防署、職業安定所。","voiceIndex":335,"id":"exchange-115"},{"speaker":"鈴木委員","kind":"質問・要望","question":"なので、どこにあるのか分からなかったのですけれども、もし公開されているということであれば自殺対策連絡協議会というところのホームページの中の公開の文字の下に公開していただきたいと思うのですが、そこら辺がどうなっているのかを伺いたいと思います。違うところにお金を使っていきたいということはどういうことなのかも伺いたいと思います。","respondent":"五十嵐保健予防課長","answer":"それまでは、庁内と庁外の方を交えての会議を一緒にさせていただいていたのですけれども、中間改定をするに当たって国が言っているような形に直させていただきまして、庁外の方で構成する会議に意見をいただきまして。","voiceIndex":337,"id":"exchange-116"},{"speaker":"鈴木委員","kind":"質問・要望","question":"それは負担が重いのではないかというふうな思いがしていまして、自殺だったりとかそういうふうなところで精神的にもすごく追い込まれた方の相談を私たちも受けることがすごくあるのですけれども、そういうときにもっとゆとりを持って受けられるような相談の体制というものが私は保健センターの中にも必要ではないかというふうな思いがしているのですが、いかがでしょうか。","respondent":"飛田荏原保健センター所長","answer":"なかなか重い相談もありますので、そういう時は専門医の先生とも一緒に入ってもらって対応しているところです。いずれにしろ、今回はこういう自殺対応というところもありますので、その人それぞれの個別な、真髄というか、まずはお話をしっかり聞く。","voiceIndex":339,"id":"exchange-117"},{"speaker":"鈴木委員","kind":"質問・要望","question":"だから、そういうことも含めての連携というものも必要ですし、連携ができるスキルも必要ですし、そこのところに本当に親身になって相談に乗っていかないと、なかなか相談しても救われないということにもなりかねないと思いますので、私はここのところは保健センターの体制としてもっと充実をしていただきたいということをぜひ要望させていただきたいと思います。そこのところも教えてください。","respondent":"飛田荏原保健センター所長","answer":"そこのところの受皿、そこの経過というところを皆さんでいろいろ専門機関とも相談しながら、病院にも入っていただきながら、そういうところでどういうふうにいったらその方が地域でまた生活できるか、また。","voiceIndex":341,"id":"exchange-118"},{"speaker":"吉田委員","kind":"質問","question":"自殺ということで、自ら命を絶つことをどうにかしたいという気持ちは本当に同じです。具体的な、例えば資料についてはむしろ東京都や厚労省がつくっているものについて活用したほうが有効ではないかというご答弁をいただいていますけれども、もう少し冊子を手に取ってしっかり読むとかいうことより、もう少しハードルの低い啓発のものは考えておられるのか伺いたいです。","respondent":"五十嵐保健予防課長","answer":"区としては、考えられることはやらせていただいていると考えています。何かいい手があったら逆に教えていただければ、こちらのほうも検討させていただきたいと考えていますので、よろしくお願いいたします。","voiceIndex":344,"id":"exchange-119"},{"speaker":"吉田委員","kind":"質問","question":"ただ、トイレの手を洗うところだとどうしても水分がありますので、だんだんしわっとしてきてしまったりして、定期的な置き換えとかも必要になってきて、これも一定経費と人手が必要になってしまうかと思うのですけれども、カレンダーが有効かどうか分からないのですが、そういうグッズをつくるということは一定予算が必要になってしまいますけれども、検討の余地はないでしょうか。いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"簡単に手に取ってもらえるような啓発グッズというのはなかなか難しいかと考えておりまして、先ほども申し上げましたようにちょっと相談してみようかなとか、ちょっといつもと感じが違うのではないかなというふうに気づいてもらえるようにということで。","voiceIndex":346,"id":"exchange-120"},{"speaker":"吉田委員","kind":"意見","question":"本当に難しいところかというふうに思います。ただ、この陳情の趣旨で言ったら、自死念慮のある方よりも周りへの啓発というか、そういうことが必要だよという趣旨だと思います。本当にそれは確かに必要かと、みんなが少しずつアンテナを高くするということが必要かと思いますので、難しいとは思いますけれども、今後も検討していただけたらと思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":348,"id":"exchange-121"},{"speaker":"やなぎさわ委員","kind":"質問","question":"そういった意味でいうと、学校でそういった中高生が、品川区でいえば市民科とかそういったところも含めて何か啓発、それこそここに書かれている誤解とかを含めて正しい知識を周囲に持っていただくみたいな、そういった取組を、少し横断的な取組になってしまうと思うのですけれども、これだけ中高生、１０代の方の自殺が増えているというところで、何か新たに手を打つというか。","respondent":"五十嵐保健予防課長","answer":"教育相談とかスクールソーシャルワーカーの活用とか不登校の方に対する対応など、いじめ防止対策事業などと様々やってくださっているところですが、基本的にはまずはＳＯＳを出せるようにという教育をしてくださっているというふうに認識しています。","voiceIndex":350,"id":"exchange-122"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"所管が違うので難しいと思うのですけれども、一応学校の体制とかＳＯＳを出してもらうという自発的なところではなく周囲が気付く、今回の陳情がまさに啓発というところではあるのですけれども、その辺についてもし取組で分かることがあれば教えていただきたいのですが、いかがでしょうか。","respondent":"五十嵐保健予防課長","answer":"保健予防課のほうで学校の先生たちを対象にしたゲートキーパー研修などは実施させていただいておりまして、受けていただいたりしながらその辺の生徒に対する対応とかを学んでいただいていると認識しています。","voiceIndex":352,"id":"exchange-123"},{"speaker":"鈴木委員","kind":"質問・要望","question":"本当に深刻な状況なわけですから、これは防げるものだということでこの計画が出されているので、私はこの品川区の自殺対策計画の中間改定等がされたわけですから、こういうものを品川区としてはつくりましたという説明会みたいな、そういうものでもやっていただいて、こういう取組を品川区としてはやっていますという区民向けの説明会というか学習会というか。","respondent":"五十嵐保健予防課長","answer":"区民に対する周知ですが、どこまでできるか分かりませんけれども、みんなと相談をしながら考えていきたいと思います。","voiceIndex":355,"id":"exchange-124"},{"speaker":"えのした副委員長","kind":"意見","question":"本日結論を出すで、不採択といたします。理由としましては、令和６年度に品川区自殺対策計画の中間改訂を区としては行っておりまして、ゲートキーパー研修は対象者を拡大して啓発をしていますし、学校からＰＴＡのご案内だったと記憶しておりますが、以前私も児童、生徒の保護者向けということで受講して、身近な人の悩み等に気づいたときにはどう関わっていくみたいなことは学ばせていただきました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":359,"id":"exchange-125"},{"speaker":"大倉委員","kind":"質問・要望","question":"本日結論を出すということで、不採択でお願いいたします。さっき少しお話しがあった関心の薄いところへのというところは本当に課題だと思っていますし、ぜひ進めていただきたいというところで、今話していて思ったのは、例えば１０代の自死が一番多いというところでは学校での授業というのもありましたけれども、遊びと絡めてということは一つあるのかなと思います。例えば、かるたとか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":360,"id":"exchange-126"},{"speaker":"あくつ委員","kind":"提案","question":"結論を出すで、不採択です。品川区の自殺に対する対策として先ほどからご説明があるとおり、品川区自殺対策計画中間改訂が昨年あったということで、６つの基本施策の基に着実に進めていらっしゃる。この陳情の中にあるご提案ですけれども、これに関しては長くなるので申し上げませんが、課長のご説明とご答弁でそれに尽きると考えていますので、不採択とします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":361,"id":"exchange-127"},{"speaker":"鈴木委員","kind":"質問・要望","question":"品川区もこういう形で、中間改定ということで計画も新たに出されているわけですけれども、この中でも令和４年のときは４９人で１０位だった自殺が令和５年には７位で６５人まで増えているという状況ですし、先ほども申し上げましたように１０代から３０代の死因のトップが自殺になっているという深刻な状況の中で、これは本当に対策を取ることによって。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":362,"id":"exchange-128"},{"speaker":"吉田委員","kind":"質問・要望","question":"どうしても自死願望とか念慮のある方向けの啓発の話になってしまうのだなというのが、今までの意見表明を聞いても、これはきっと難しいのですね。陳情者が求めておられるのは周りへの啓発ですけれども、かなり難しい議論なのだということが分かりました。ですので、私としては継続で審査をしたほうがいいのではないかという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":363,"id":"exchange-129"},{"speaker":"やなぎさわ委員","kind":"質問","question":"私もできれば継続して議論を深めたり、呼べればですけれども、専門的な方をお呼びしていろいろお話を聞けたりとかできたらいいのかと思いますし、やはりそういった発信をするというか、啓発をすることは非常に大事なことだと思っていて、２００６年ですか。１万人くらいですか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":364,"id":"exchange-130"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"本日結論出すということになりましたので、採択を主張させていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":368,"id":"exchange-131"}]},{"id":"topic-08","title":"令和７年陳情第４２号、犬猫の放置糞尿への対策と清掃費用の公平負担に関する陳情","agenda":"令和７年陳情第４２号、犬猫の放置糞尿への対策と清掃費用の公平負担に関する陳情","exchanges":[{"speaker":"やなぎさわ委員","kind":"確認","question":"この陳情に書いてあることの確認ですけれども、他自治体で犬猫の糞尿の残地に関して罰則規定みたいなものを設けている自治体があるような記載があるのですが、その辺の実態というのはいかがでしょうか。どれくらいの自治体があって、どういう罰則になっているのか、もしお分かりになればお願いいたします。","respondent":"赤木生活衛生課長","answer":"私どものほうで把握をさせていただいている情報ですけれども、２３区内ということになりますと、罰則規定がありますのは渋谷区の条例があります。それ以外の自治体、２２区につきましては、特段罰則を設けているような規定はないというふうに認識しております。","voiceIndex":375,"id":"exchange-132"},{"speaker":"やなぎさわ委員","kind":"質問・要望","question":"具体的に分かればいいのですけれども、どういった過料になっているのか教えていただきたいです。","respondent":"赤木生活衛生課長","answer":"渋谷区の事例について、ご説明をします。","voiceIndex":377,"id":"exchange-133"},{"speaker":"やなぎさわ委員","kind":"質問","question":"その件は、承知いたしました。実際に、品川区にこういった犬猫の糞尿のトラブルというか、苦情の相談件数は大体年間どれくらいきていらっしゃるのですか。","respondent":"赤木生活衛生課長","answer":"前年度、令和５年度につきましては６６件で、令和４年度につきましては４１件という形です。令和５年度に比べますと、令和６年度については明らかな減少が見込まれておりまして、区として様々取り組んでいった効果が一定程度出たのではないかというふうに分析をしております。","voiceIndex":379,"id":"exchange-134"},{"speaker":"やなぎさわ委員","kind":"質問","question":"とういうことは、区としてはこういった啓発活動とか、そういったものを進めていくことによって、こういった陳情で出ているようなトラブルというのは減らしていけるというような、そういったお考えということでよろしいでしょうか。","respondent":"赤木生活衛生課長","answer":"委員のおっしゃるとおりでございまして、区としましてはこういった周知啓発、短期的にすぐに効果が出るものという形では思ってはおりませんけれども、粘り強く皆様方に正しいマナーの周知啓発というところをすることによりまして。","voiceIndex":381,"id":"exchange-135"},{"speaker":"えのした副委員長","kind":"意見","question":"本日結論を出すで、不採択とします。理由は、区は条例の規定に基づいて様々な取組を行ってマナーの向上に努めておりますし、今課長からもご答弁がありましたが、苦情の件数もほぼ半減ということで効果が出ています。飼い主の基本的なマナーの問題でありますし、しつけの問題、マナーの啓発等を不採択の理由としております。引き続き、周知啓発の徹底をお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":385,"id":"exchange-136"},{"speaker":"大倉委員","kind":"意見","question":"本日結論を出すということで、不採択でお願いいたします。そういったところも合わせてさらに今後も周知啓発をしていって、獣医師との連携とかを進めながら、マナー教室等様々やる中でこういった件数が減ってきているかというところも多少理解するところではありますので、不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":386,"id":"exchange-137"},{"speaker":"あくつ委員","kind":"提案","question":"本日結論を出すで、不採択でお願いいたします。ご提案のような条例制定とか税金の付加というところのお気持ちは分かるのですけれども、多分同じ立場に立てばこういうお怒りとか憤りというものはよく分かるのですが、やはりこれは区として、行政として粘り強く取り組んでいく必要があるのかと思います。不採択でお願いいたします。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":387,"id":"exchange-138"},{"speaker":"鈴木委員","kind":"意見","question":"結論を出すで、不採択でお願いしたいと思います。先ほどからも皆さんが言われているように、区の取組、マナーの周知啓発によって苦情相談も減ってきているということでありますので、そういうところを評価するということが最も大事なことではないかというふうに思います。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","voiceIndex":388,"id":"exchange-139"},{"speaker":"吉田委員","kind":"質問・要望","question":"１個だけ。多分、これは糞のほうの話だと思うのですけれども、何年か前に尿のほうで電柱が倒れてしまったという事件があったのをご記憶ではないですか。でも、あんなペットボトルでちょっとかけたくらいでは効果がないと言われておりますので、今回の陳情は主にどうも糞のほうですけれども、やはり公共物に実害が出たわけですから、そちらのほうの啓発も忘れずにぜひ進めていっていただきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":389,"id":"exchange-140"},{"speaker":"やなぎさわ委員","kind":"質問","question":"本日結論を出す、不採択でお願いいたします。私も吉田委員から今お話がありましたけれども、昔を振り返ってみると２０年くらい前、学生の頃ですが、地元の鮫洲の運河沿いでジョギングをしていると、糞がすごいのです。夜よくジョギングをしていたものですから、下を見て走らないといつ踏んでしまうか分からない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","voiceIndex":390,"id":"exchange-141"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?Template=document&Id=7163#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2025-01-01&TermEnd=2025-12-31"}],"sourceMeta":{"pages":0,"characters":115047,"voices":399}}]);
